        fn release(&self) -> Option<&ProductReleaseId> {
            match self {
                Self::RegistryPackage { .. } => None,
                Self::ProductAsset { release, .. }
                | Self::ChecksumManifest { release, .. }
                | Self::ReleaseMetadata { release, .. } => Some(release),
            }
