    fn deserialize<D>(deserializer: D) -> Result<Self, D::Error>
    where
        D: Deserializer<'de>,
    {
        let wire = ReleaseDistributionMetadataV1Wire::deserialize(deserializer)?;
        let metadata = Self {
            schema_version: wire.schema_version,
            product_release: wire.product_release,
            intent_digest: wire.intent_digest,
            source_commit: wire.source_commit,
            payloads: wire.payloads,
            verification_policy: wire.verification_policy,
        };
        metadata.validate().map(|()| metadata).map_err(serde::de::Error::custom)
    }
}

