    fn intent_with_source_and_registry(source_commit: CommitSha, include_registry: bool) -> ReleaseIntent {
        let release = release();
        let mut slots = slots(&release);
        let mut registry_packages = Vec::new();
        let mut operations = Vec::new();
        let mut registry_ids = Vec::new();
        if include_registry {
            let package = ReleasePackageId::parse("cargo/callisto-model").unwrap();
            let registry = registry_binding();
            let slot = ReleaseArtifactSlot::RegistryPackage {
                package: package.clone(),
                version: release.version.clone(),
                registry: registry.clone(),
                format: RegistryArtifactFormat::CargoCrate,
                file_name: "callisto-model-1.2.3.crate".to_string(),
                provenance_policy: policy(),
            };
            let id = ReleaseOperationId::RegistryArtifactPublish {
                package: package.clone(),
                version: release.version.clone(),
                registry: registry.clone(),
                slot: slot.clone(),
            };
            registry_packages
                .push(ApprovedRegistryPackage::new(package, registry, RegistryArtifactFormat::CargoCrate).unwrap());
            slots.push(slot);
            registry_ids.push(id.clone());
            operations.push(ReleaseOperation::new(id, vec![]).unwrap());
        }

        let tag = ReleaseOperationId::ProductTag {
            release: release.clone(),
            tag: release.tag(),
        };
        let prepare = ReleaseOperationId::ForgePrepare {
            release: release.clone(),
            repository: GitHubRepository::parse("callisto-rs/callisto").unwrap(),
        };
        registry_ids.sort();
        operations.push(ReleaseOperation::new(tag.clone(), registry_ids).unwrap());
        operations.push(ReleaseOperation::new(prepare.clone(), vec![tag]).unwrap());
        let uploads = slots
            .iter()
            .filter(|slot| slot.release().is_some())
            .map(|slot| {
                ReleaseOperation::new(
                    ReleaseOperationId::ArtifactUpload {
                        release: release.clone(),
                        slot: slot.clone(),
                    },
                    vec![prepare.clone()],
                )
                .unwrap()
            })
            .collect::<Vec<_>>();
        let mut prerequisites = uploads.iter().map(|operation| operation.id.clone()).collect::<Vec<_>>();
        prerequisites.sort();
        operations.extend(uploads);
        operations.push(
            ReleaseOperation::new(
                ReleaseOperationId::ForgePublish {
                    release: release.clone(),
                    repository: GitHubRepository::parse("callisto-rs/callisto").unwrap(),
                },
                prerequisites,
            )
            .unwrap(),
        );
        let edges = operations
            .iter()
            .map(|operation| (operation.id.clone(), operation.prerequisites.clone()))
            .collect();
        let ordered = stable_order(&edges).unwrap();
        let lookup: BTreeMap<_, _> = operations
            .into_iter()
            .map(|operation| (operation.id.clone(), operation))
            .collect();
        ReleaseIntent::new(
            release,
            source_commit,
            registry_packages,
            ordered.into_iter().map(|id| lookup[&id].clone()).collect(),
            slots,
        )
        .unwrap()
    }

    fn intent() -> ReleaseIntent {
        intent_with_source_and_registry(commit(), false)
    }

