        }

        fn operation_index(&self, predicate: impl Fn(&ReleaseOperationId) -> bool) -> usize {
            self.operations
                .iter()
                .position(|entry| predicate(&entry.operation))
                .expect("fixture contains the requested operation role")
        }

        fn assert_evidence_rejected(&self, operations: Vec<ObservedOperation>) {
            assert!(matches!(
