        }
        assert!(ReleaseIntent::new(
            intent.product_release.clone(),
            commit(),
            intent.registry_packages.clone(),
            intent.operations.clone(),
            unsafe_slot
        )
        .is_err());
        let mut fifth_target = intent.slots.clone();
        let fifth_slot = ReleaseArtifactSlot::ProductAsset {
            release: intent.product_release.clone(),
            target: ProductTarget::Aarch64AppleDarwin,
