            .unwrap()
            .id
            .clone();
        let fifth_upload = ReleaseOperation::new(
            ReleaseOperationId::ArtifactUpload {
                release: intent.product_release.clone(),
                slot: fifth_slot,
            },
            vec![prepare],
        )
        .unwrap();
        let mut fifth_operations = intent.operations.clone();
        let publish_index = fifth_operations
            .iter()
            .position(|operation| matches!(operation.id, ReleaseOperationId::ForgePublish { .. }))
            .unwrap();
        fifth_operations[publish_index]
            .prerequisites
            .push(fifth_upload.id.clone());
        fifth_operations[publish_index].prerequisites.sort();
        fifth_operations.insert(publish_index, fifth_upload);
        assert!(matches!(
            ReleaseIntent::new(
                intent.product_release.clone(),
                commit(),
                intent.registry_packages.clone(),
                fifth_operations,
                fifth_target
            ),
            Err(SuccessorError::InvalidProductRoster)
        ));
        let mut malformed_policy = serde_json::to_value(&intent).unwrap();
        let slot = malformed_policy["slots"]
            .as_array_mut()
            .unwrap()
            .iter_mut()
            .find(|slot| slot["kind"] == "productAsset")
            .unwrap();
        assert!(slot.get("provenancePolicy").is_some());
        slot["provenancePolicy"]["githubAttestationRequired"] = serde_json::Value::Bool(false);
        let error = serde_json::from_value::<ReleaseIntent>(malformed_policy).unwrap_err();
        assert!(error.to_string().contains("artifact slot provenance is invalid"));
        let mut direct_policy = policy();
        direct_policy.github_attestation_required = false;
        assert!(matches!(
            direct_policy.validate(),
            Err(SuccessorError::InvalidProvenance)
        ));
        let mut wrong_forge = intent.operations.clone();
        if let ReleaseOperationId::ForgePublish { repository, .. } = &mut wrong_forge
            .iter_mut()
            .find(|operation| matches!(operation.id, ReleaseOperationId::ForgePublish { .. }))
            .unwrap()
            .id
        {
