            ));
        }
    }

    fn manifest_for(intent: &ReleaseIntent) -> ReleaseArtifactManifest {
        let entries = intent
            .slots
            .iter()
            .filter(|slot| {
                matches!(
                    slot,
                    ReleaseArtifactSlot::RegistryPackage { .. } | ReleaseArtifactSlot::ProductAsset { .. }
                )
            })
            .cloned()
            .map(|slot| ReleaseArtifactEntry {
                digest: ArtifactDigest::from_bytes(slot.file_name()),
                byte_length: slot.file_name().len() as u64,
                source_commit: intent.source_commit.clone(),
                provenance: slot.policy().clone(),
                slot,
            })
            .collect();
        let payloads = ValidatedPayloadEntries::new(intent, entries).unwrap();
        ReleaseArtifactManifest::complete(intent, &payloads).unwrap()
    }

    fn observation_fixture(include_registry: bool) -> ObservationFixture {
        let intent = intent_with_source_and_registry(commit(), include_registry);
        let manifest = manifest_for(&intent);
