                } = &mut operations[publish].evidence
                else {
                    unreachable!();
                };
                *asset_roster_digest = changed_digest;
                fixture.assert_evidence_rejected(operations);
            }
        }

        #[test]
        fn observation_wire_uses_canonical_camel_case_keys_only() {
            let fixture = observation_fixture(true);
            let wire = serde_json::to_value(fixture.receipt()).unwrap();
            assert_no_snake_case_keys(&wire);
            assert!(wire.get("schemaVersion").is_some());
            assert!(wire.get("intentDigest").is_some());
            assert!(wire.get("schema_version").is_none());
            assert!(wire.get("intent_digest").is_none());

            let evidence = wire["operations"].as_array().unwrap();
            assert!(evidence.iter().any(|entry| {
                entry["evidence"].get("registryKey").is_some()
                    && entry["evidence"].get("bindingDigest").is_some()
                    && entry["evidence"].get("byteLength").is_some()
            }));
            assert!(evidence
                .iter()
                .any(|entry| entry["evidence"].get("annotationDigest").is_some()));
            assert!(evidence
                .iter()
                .any(|entry| entry["evidence"].get("assetRosterDigest").is_some()));
        }
    }
}

