/// Errors in a typed semantic input snapshot.
#[derive(Clone, Debug, PartialEq, Eq, thiserror::Error)]
#[non_exhaustive]
pub enum ReleaseInputSnapshotError {
    #[error("release input snapshot repeats a package")]
    DuplicatePackage,
