#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, PartialOrd, Ord, Serialize, Deserialize, JsonSchema)]
#[serde(rename_all = "camelCase")]
pub enum RegistryArtifactFormat {
    CargoCrate,
    NpmTarball,
    PythonWheel,
    PythonSdist,
}

#[derive(Clone, Debug, PartialEq, Eq, Hash, PartialOrd, Ord, Serialize, JsonSchema)]
#[schemars(with = "String")]
pub struct NpmDistTag(String);

impl NpmDistTag {
    pub fn parse(raw: impl AsRef<str>) -> Result<Self, SuccessorError> {
        let raw = raw.as_ref();
        let valid = !raw.is_empty()
            && raw.len() <= 63
            && raw.bytes().all(|byte| {
                byte.is_ascii_lowercase() || byte.is_ascii_digit() || byte == b'-'
            })
            && raw.bytes().next().is_some_and(|byte| byte.is_ascii_lowercase())
            && raw.bytes().last().is_some_and(|byte| byte.is_ascii_alphanumeric());
        if !valid || semver::VersionReq::parse(raw).is_ok() {
            return Err(SuccessorError::InvalidNpmDistTag { raw: raw.to_string() });
        }
        Ok(Self(raw.to_string()))
    }

    pub fn as_str(&self) -> &str {
        &self.0
    }
}

impl<'de> Deserialize<'de> for NpmDistTag {
    fn deserialize<D>(deserializer: D) -> Result<Self, D::Error>
    where
        D: Deserializer<'de>,
    {
        Self::parse(String::deserialize(deserializer)?).map_err(serde::de::Error::custom)
    }
}

#[derive(Clone, Debug, PartialEq, Eq, Hash, Serialize, Deserialize, JsonSchema)]
#[serde(rename_all = "camelCase", tag = "kind", deny_unknown_fields)]
pub enum RegistryPublicationPolicy {
    Cargo,
    Npm { access: NpmAccess, dist_tag: NpmDistTag },
    Pypi,
