impl ReleaseIntent {
    const SCHEMA_VERSION: u8 = 1;

    pub fn new(
        decision: ReleaseDecisionV1,
        product_release: ProductReleaseId,
        source_commit: CommitSha,
        destination: ReleaseDestinationBinding,
        mut registry_packages: Vec<ApprovedRegistryPackage>,
        operations: Vec<ReleaseOperation>,
        mut slots: Vec<ReleaseArtifactSlot>,
    ) -> Result<Self, SuccessorError> {
        slots.sort();
        registry_packages.sort();
        let unique_registry_artifacts = registry_packages
            .iter()
            .map(|entry| (entry.package.clone(), entry.format))
            .collect::<BTreeSet<_>>();
        if unique_registry_artifacts.len() != registry_packages.len() {
            return Err(SuccessorError::DuplicateRegistryPackage);
        }
        validate_decision(&decision, &product_release, &registry_packages)?;
        validate_slot_roster(&product_release, &destination, &registry_packages, &slots)?;
        validate_operations(&product_release, &destination, &registry_packages, &operations, &slots)?;
        let digest = digest_intent(
            &decision,
            &product_release,
            &source_commit,
            &destination,
            &registry_packages,
            &operations,
            &slots,
        );
        Ok(Self {
            schema_version: Self::SCHEMA_VERSION,
            decision,
