#[derive(Debug)]
pub struct ReleaseStateStore<W = AtomicReleaseStateWriter> {
    path: PathBuf,
    writer: W,
}

impl ReleaseStateStore {
    /// Creates a production store at an explicit path.
    pub fn new(path: impl Into<PathBuf>) -> Self {
        Self::with_writer(path, AtomicReleaseStateWriter)
    }

    /// Creates a local state store outside the checkout, keyed by the exact
    /// durable intent. CI should use [`Self::new`] with an explicit path so a
    /// workflow artifact can hand state between jobs without using a cache.
    pub fn default_for(canonical_root: &Path, intent: &ReleaseIntentV1) -> Result<Self, GraphError> {
        let root = dunce::canonicalize(canonical_root).map_err(|error| GraphError::ReleaseStateRead {
            path: canonical_root.to_path_buf(),
            message: error.to_string(),
        })?;
        let mut transcript = callisto_model::CanonicalTranscript::semantic_input_v1();
        transcript.push_str("workspace-root", &root.to_string_lossy());
        let root_key = callisto_model::SemanticInputDigest::from_transcript(&transcript);
        let base = callisto_vcs::release_lock::platform_state_directory()?;
        Ok(Self::new(
            base.join("callisto")
                .join("release-state")
                .join(root_key.as_str())
                .join(format!("{}.json", intent.digest().as_str())),
        ))
    }
}

impl<W> ReleaseStateStore<W>
where
    W: ReleaseStateWriter,
{
    /// Creates a store with a narrow writer seam, primarily for deterministic
    /// failure tests. The path remains explicit and is never config-derived.
    pub fn with_writer(path: impl Into<PathBuf>, writer: W) -> Self {
        Self {
            path: path.into(),
            writer,
        }
    }

    /// Returns the caller-chosen durable state location.
    pub fn path(&self) -> &Path {
        &self.path
    }

    /// Loads state if it exists and rejects any state not exactly bound to
    /// `intent`. A missing file is not evidence of a completed release.
    pub fn load(&self, intent: &ReleaseIntentV1) -> Result<Option<ReleaseExecutionStateV1>, GraphError> {
        let content = match std::fs::read_to_string(&self.path) {
            Ok(content) => content,
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => return Ok(None),
            Err(error) => {
                return Err(GraphError::ReleaseStateRead {
                    path: self.path.clone(),
                    message: error.to_string(),
                });
            }
        };
        let state: ReleaseExecutionStateV1 =
            serde_json::from_str(&content).map_err(|error| GraphError::ReleaseStateDecode {
                path: self.path.clone(),
                message: error.to_string(),
            })?;
        state
            .validate_for_intent(intent)
            .map_err(|source| GraphError::ReleaseExecutionState { source })?;
        Ok(Some(state))
    }

    /// Loads existing state or atomically writes the exact pending roster.
    pub fn load_or_initialize(
        &self,
        intent: &ReleaseIntentV1,
        permit: &ApplyPermit,
    ) -> Result<ReleaseExecutionStateV1, GraphError> {
        if let Some(state) = self.load(intent)? {
            return Ok(state);
        }
        let state = ReleaseExecutionStateV1::pending(intent);
        self.save(intent, &state, permit)?;
        Ok(state)
    }

    /// Atomically persists only state proven to belong to `intent`.
    pub fn save(
        &self,
        intent: &ReleaseIntentV1,
        state: &ReleaseExecutionStateV1,
        permit: &ApplyPermit,
    ) -> Result<(), GraphError> {
        state
            .validate_for_intent(intent)
            .map_err(|source| GraphError::ReleaseExecutionState { source })?;
        let content = serde_json::to_string_pretty(state).expect("release state serialization is infallible") + "\n";
        self.writer
            .write(&self.path, &content, permit)
            .map_err(|error| GraphError::ReleaseStateWrite {
                path: self.path.clone(),
                message: error.to_string(),
            })
    }
}

#[cfg(test)]
mod tests {
    use std::io;

    use callisto_model::{
        Ecosystem, ExecutionTrustProfileV1, RegistryBindingDigest, RegistryBindingId, ReleaseInputSnapshotV1,
        ReleaseOperation, ReleasePackageId, SourceIdentity, Version,
    };
    use tempfile::tempdir;

    use super::*;

    fn intent(sha: char) -> ReleaseIntentV1 {
        let package = ReleasePackageId::new(Ecosystem::Cargo, "demo").unwrap();
        let registry = RegistryBindingId::new(
            "crates",
            RegistryBindingDigest::from_normalized_binding(b"crates-default"),
        )
        .unwrap();
        let operation =
            ReleaseOperation::registry_publish(package.clone(), Version::semver(1, 0, 0), registry, vec![]).unwrap();
        ReleaseIntentV1::new(
            callisto_model::ReleaseDecisionV1::new(vec![callisto_model::ReleaseDecisionEntry {
                package: package.clone(),
                target_version: Version::semver(1, 0, 0),
                reasons: vec![callisto_model::ReleaseInclusionReason::ExplicitSelection],
            }])
            .unwrap(),
            ReleaseInputSnapshotV1::new(SourceIdentity::git_commit(sha.to_string().repeat(40)).unwrap(), vec![])
                .unwrap(),
            ExecutionTrustProfileV1::GitCommit,
            vec![operation],
            vec![],
        )
        .unwrap()
    }

    #[test]
    fn initializes_then_loads_exact_intent_bound_state() {
        let directory = tempdir().unwrap();
        let store = ReleaseStateStore::new(directory.path().join("state.json"));
        let intent = intent('a');
        let permit = ApplyPermit::force_for_tests();
        let initial = store.load_or_initialize(&intent, &permit).unwrap();
        assert_eq!(store.load(&intent).unwrap(), Some(initial));
        assert!(std::fs::read_to_string(store.path()).unwrap().contains("intentDigest"));
    }

    #[test]
    fn mismatched_intent_is_never_loaded_as_state() {
        let directory = tempdir().unwrap();
        let store = ReleaseStateStore::new(directory.path().join("state.json"));
        let permit = ApplyPermit::force_for_tests();
        store.load_or_initialize(&intent('a'), &permit).unwrap();
        assert!(matches!(
            store.load(&intent('b')),
            Err(GraphError::ReleaseExecutionState { .. })
        ));
    }

    #[test]
    fn default_state_path_is_outside_the_checkout_and_intent_bound() {
        let directory = tempdir().unwrap();
        let first = ReleaseStateStore::default_for(directory.path(), &intent('a')).unwrap();
        let second = ReleaseStateStore::default_for(directory.path(), &intent('b')).unwrap();
        assert_ne!(first.path(), second.path());
        assert!(!first.path().starts_with(directory.path()));
    }

    #[derive(Clone, Copy, Debug)]
    struct FailBeforeRename;

    impl ReleaseStateWriter for FailBeforeRename {
        fn write(&self, _path: &Path, _content: &str, _permit: &ApplyPermit) -> io::Result<()> {
            Err(io::Error::other("injected pre-rename failure"))
        }
    }

    #[test]
    fn injected_pre_rename_failure_never_becomes_successful_state() {
        let directory = tempdir().unwrap();
        let path = directory.path().join("state.json");
        let store = ReleaseStateStore::with_writer(&path, FailBeforeRename);
        let permit = ApplyPermit::force_for_tests();
        assert!(matches!(
            store.load_or_initialize(&intent('a'), &permit),
            Err(GraphError::ReleaseStateWrite { .. })
        ));
        assert_eq!(
            std::fs::read_to_string(path).unwrap_err().kind(),
            io::ErrorKind::NotFound
        );
    }

    #[test]
    fn failed_replacement_preserves_the_last_durable_state() {
        let directory = tempdir().unwrap();
        let path = directory.path().join("state.json");
        let permit = ApplyPermit::force_for_tests();
        let release_intent = intent('a');
        let production = ReleaseStateStore::new(&path);
        let pending = production.load_or_initialize(&release_intent, &permit).unwrap();

        let failing = ReleaseStateStore::with_writer(&path, FailBeforeRename);
        let operation = release_intent.operations[0].id().clone();
        let mut changed = pending.clone();
        changed.mark_attempting(&operation).unwrap();
        assert!(matches!(
            failing.save(&release_intent, &changed, &permit),
            Err(GraphError::ReleaseStateWrite { .. })
        ));
        assert_eq!(production.load(&release_intent).unwrap(), Some(pending));
    }
}
//! Deterministic, graph-owned release roster decisions.
//!
//! This is deliberately separate from `PublishPlan`: it records the exact
//! package/version authority that later intent construction consumes, without
//! exposing a mutation route.

use callisto_model::{
    BumpReason, CommandRunner, CommitSha, Ecosystem, Package, ReleaseDecisionEntry, ReleaseDecisionV1,
    ReleaseInclusionReason, ReleasePackageId, Version,
};

use crate::error::{
    CommandFailure, CommitVerificationFailure, ReleasePreconditionRequirement, ReleaseSelectionInvalidReason,
    UnsupportedReleaseFeature,
};
use crate::{DependencyResolver, GraphError, VersionPlan, Workspace};

/// Computes one [`ReleasePackageId`] per canonical manifest, ecosystem-qualified
/// against `package`'s name.
///
/// This is the single derivation of release package identity shared by every
/// site that computes or verifies release authority: [`derive_release_decision`],
/// [`derive_release_commit_decision`], and `release::derive_release_inputs`.
/// Per this module's own established lesson (see the doc comment on
/// [`derive_release_commit_decision`]), independently reimplementing this
/// mapping at each call site is exactly the kind of duplicated derivation
/// that drifts -- so it lives here once instead.
pub(crate) fn release_package_ids(package: &Package) -> Result<Vec<ReleasePackageId>, GraphError> {
    package
        .canonical_manifests()
        .map(|manifest| ReleasePackageId::new(manifest.ecosystem(), package.id.name()))
        .collect::<Result<Vec<_>, _>>()
        .map_err(GraphError::from)
}

/// Reject source-only identities wherever a durable decision grants authority,
/// including causal references supplied in a serialized decision.
pub(crate) fn validate_release_units<R: CommandRunner, D: DependencyResolver>(
    workspace: &Workspace<'_, R, D>,
    decision: &ReleaseDecisionV1,
) -> Result<(), GraphError> {
    let mut excluded = std::collections::BTreeSet::new();
    for package in workspace.graph.packages() {
        if !crate::config::is_release_unit(&workspace.config, &package.id)? {
            excluded.extend(release_package_ids(package)?);
        }
    }
    for entry in &decision.entries {
        for id in std::iter::once(&entry.package).chain(entry.reasons.iter().filter_map(|reason| match reason {
            ReleaseInclusionReason::Cascade { from, .. } => Some(from),
            _ => None,
        })) {
            if excluded.contains(id) {
                return Err(GraphError::ReleasePackageNotSelected { package: id.clone() });
            }
        }
    }
    Ok(())
}

/// Derives the durable roster from a freshly computed version plan.
///
/// The caller supplies the plan from the same workspace observation; this
/// function never inspects `PublishPlan` or a caller-provided release roster.
pub fn derive_release_decision<R: callisto_model::CommandRunner, D: DependencyResolver>(
    workspace: &Workspace<'_, R, D>,
    plan: &VersionPlan,
) -> Result<ReleaseDecisionV1, GraphError> {
    let mut package_ids = std::collections::BTreeMap::new();
    for package in workspace.graph.packages() {
        if !crate::config::is_release_unit(&workspace.config, &package.id)? {
            continue;
        }
        let ids = release_package_ids(package)?;
        package_ids.insert(package.id.clone(), ids);
    }

    let mut entries = Vec::new();
    for bump in &plan.bumps {
        if !crate::config::is_release_unit(&workspace.config, &bump.package)? {
            continue;
        }
        // `plan` is contractually derived from this same workspace
        // observation (see doc comment above), so every bump's package must
        // already be a key here -- a miss means the plan/workspace pairing
        // itself is inconsistent, not a recoverable operator condition.
        let ids = package_ids
            .get(&bump.package)
            .ok_or_else(|| GraphError::ReleaseInvariant {
                detail: format!(
                    "version plan references package `{}`, which is absent from this workspace observation",
                    bump.package.display_name()
                ),
            })?;
        for id in ids {
            entries.push(ReleaseDecisionEntry {
                package: id.clone(),
                target_version: bump.to.clone(),
                reasons: vec![reason_from_bump(bump.reason.as_ref(), &package_ids)?],
            });
        }
    }
    ReleaseDecisionV1::new(entries).map_err(GraphError::from)
}

/// Derives a durable decision for explicit, exact release identities.
///
/// A linked group is one release unit: selecting any member includes every
/// member of that linked group which the version plan selected. All other
/// packages remain outside the authority boundary. The caller must pass
/// ecosystem-qualified [`ReleasePackageId`] values; this function never uses
/// `PackageId::matches`, whose bare-name wildcard semantics are unsuitable
/// for release authority.
pub fn derive_selected_release_decision<R: callisto_model::CommandRunner, D: DependencyResolver>(
    workspace: &Workspace<'_, R, D>,
    plan: &VersionPlan,
    selections: &[ReleasePackageId],
) -> Result<ReleaseDecisionV1, GraphError> {
    let complete = derive_release_decision(workspace, plan)?;

    let mut seen = std::collections::BTreeSet::new();
    if let Some(duplicate) = selections.iter().find(|selection| !seen.insert(*selection)) {
        return Err(GraphError::ReleaseSelectionInvalid {
            package: duplicate.clone(),
            reason: ReleaseSelectionInvalidReason::Duplicate,
        });
    }

    let selected = selections.iter().collect::<std::collections::BTreeSet<_>>();
    for selection in &selected {
        if !complete.entries.iter().any(|entry| &entry.package == *selection) {
            return Err(GraphError::ReleaseSelectionInvalid {
                package: (*selection).clone(),
                reason: ReleaseSelectionInvalidReason::NotInPlan,
            });
        }
    }

    let linked_groups = complete
        .entries
        .iter()
        .filter(|entry| selected.contains(&entry.package))
        .flat_map(|entry| entry.reasons.iter())
        .filter_map(|reason| match reason {
            ReleaseInclusionReason::LinkedGroup { group_id } => Some(group_id.clone()),
            _ => None,
        })
        .collect::<std::collections::BTreeSet<_>>();

    let entries = complete
        .entries
        .into_iter()
        .filter(|entry| {
            selected.contains(&entry.package)
                || entry.reasons.iter().any(|reason| {
                    matches!(reason, ReleaseInclusionReason::LinkedGroup { group_id } if linked_groups.contains(group_id))
                })
        })
        .collect();
    ReleaseDecisionV1::new(entries).map_err(GraphError::from)
}

/// Verifies the release roster a merged release commit claims, against a
/// release-decision file committed alongside it at `decision_path`.
///
/// This is intentionally *not* a second computation of changeset, fixed-group,
/// linked-group, cascade, or pre-release-policy inclusion. `plan_version`
/// (via [`derive_release_decision`]) already computed that once, correctly,
/// when the release PR was generated -- and `callisto version --emit-decision`
/// commits its exact output alongside the manifest and changelog edits.
/// Re-deriving that policy a second time here, from raw git diffs, is exactly
/// the kind of duplicated logic that drifts: an earlier version of this
/// function did just that, understood only a direct changeset match, and
/// rejected every real release in this repository once a fixed-group cascade
/// (a case its reimplementation never learned) touched an unnamed sibling.
///
/// Instead, this function reads the committed decision back and confirms the
/// commit's actual diff matches it exactly -- no more, no less.
/// [`ReleaseDecisionV1`]'s own deserializer already rejects a decision whose
/// entries don't match its content digest, so a hand-edited or corrupted
/// decision file fails before this function's own diff cross-check runs.
///
/// The caller must check out the exact merge commit in detached HEAD state
/// before creating an intent. GitHub-specific PR/approval provenance belongs
/// in the workflow boundary; this graph function verifies the local,
/// provider-neutral commit delta only.
pub fn derive_release_commit_decision<R: CommandRunner, D: DependencyResolver>(
    workspace: &Workspace<'_, R, D>,
    release_commit: &CommitSha,
    decision_path: &std::path::Path,
) -> Result<ReleaseDecisionV1, GraphError> {
    let head_args = ["rev-parse", "HEAD"];
    let head = git_stdout(workspace.runner, &workspace.root, &head_args)?;
    let head =
        CommitSha::parse(&head).map_err(|source| command_malformed_output("git", &head_args, source.to_string()))?;
    if &head != release_commit {
        return Err(GraphError::ReleaseCommitVerificationFailed {
            commit: release_commit.clone(),
            reason: CommitVerificationFailure::HeadMismatch,
        });
    }

    let parent_ref = format!("{}^", release_commit.as_str());
    let parent_args = ["rev-parse", parent_ref.as_str()];
    let parent = git_stdout(workspace.runner, &workspace.root, &parent_args)?;
    CommitSha::parse(&parent).map_err(|source| command_malformed_output("git", &parent_args, source.to_string()))?;

    let diff_tree_args = [
        "diff-tree",
        "--no-commit-id",
        "--name-status",
        "-r",
        "--no-renames",
        parent.as_str(),
        release_commit.as_str(),
    ];
    let changed = git_stdout(workspace.runner, &workspace.root, &diff_tree_args)?;
    let changed = parse_name_status(&changed, &diff_tree_args)?;

    // The decision must be freshly authored as part of *this* commit, not a
    // stale leftover an earlier release already committed and this one never
    // touched -- otherwise a commit that changes nothing real could still
    // carry forward a prior, unrelated decision's authority.
    let decision_path_str = decision_path.to_string_lossy().replace('\\', "/");
    let decision_freshly_written = changed
        .iter()
        .any(|(status, path)| path == &decision_path_str && matches!(status.as_str(), "A" | "M"));
    if !decision_freshly_written {
        return Err(GraphError::ReleaseCommitVerificationFailed {
            commit: release_commit.clone(),
            reason: CommitVerificationFailure::DecisionNotWrittenByCommit,
        });
    }

    // A cheap, independent sanity check that this commit is a real version
    // application and not just a hand-crafted decision file: some real
    // changeset was actually consumed. The decision's own entries, not this
    // changeset's content, remain the sole authority verified below.
    let changeset_dir = workspace.config.changesets_dir.to_string_lossy().replace('\\', "/");
