    fn format_matches_ecosystem(format: RegistryArtifactFormat, ecosystem: Ecosystem) -> bool {
        matches!(
            (format, ecosystem),
            (RegistryArtifactFormat::CargoCrate, Ecosystem::Cargo)
                | (RegistryArtifactFormat::NpmTarball, Ecosystem::Npm)
                | (
                    RegistryArtifactFormat::PythonWheel | RegistryArtifactFormat::PythonSdist,
                    Ecosystem::Pypi
                )
        )
    }

    fn format_matches_file_name(format: RegistryArtifactFormat, file_name: &str) -> bool {
        match format {
            RegistryArtifactFormat::CargoCrate => file_name.ends_with(".crate"),
            RegistryArtifactFormat::NpmTarball => file_name.ends_with(".tgz"),
            RegistryArtifactFormat::PythonWheel => file_name.ends_with(".whl"),
            RegistryArtifactFormat::PythonSdist => file_name.ends_with(".tar.gz"),
        }
    }

