        operations: Vec<ReleaseOperation>,
        slots: Vec<ReleaseArtifactSlot>,
        digest: IntentDigest,
    }

    impl ReleaseIntent {
        pub const SCHEMA_VERSION: u8 = 1;

        pub fn new(
            decision: ReleaseDecisionV1,
            product_release: ProductReleaseId,
            source_commit: CommitSha,
            destination: ReleaseDestinationBinding,
            mut registry_artifacts: Vec<ApprovedRegistryArtifact>,
            operations: Vec<ReleaseOperation>,
            mut slots: Vec<ReleaseArtifactSlot>,
        ) -> Result<Self, SuccessorError> {
            slots.sort();
            registry_artifacts.sort();
            let unique_registry_artifacts = registry_artifacts
                .iter()
                .map(|entry| (entry.package.clone(), entry.format, entry.file_name.clone()))
                .collect::<BTreeSet<_>>();
            if unique_registry_artifacts.len() != registry_artifacts.len() {
                return Err(SuccessorError::DuplicateRegistryArtifact);
            }
            let mut singular_artifacts = BTreeSet::new();
            if registry_artifacts.iter().any(|artifact| {
                artifact.format != RegistryArtifactFormat::PythonWheel
                    && !singular_artifacts.insert((artifact.package.clone(), artifact.format))
            }) {
                return Err(SuccessorError::DuplicateRegistryArtifact);
            }
            validate_decision(&decision, &product_release, &registry_artifacts)?;
            validate_slot_roster(&product_release, &destination, &registry_artifacts, &slots)?;
            validate_operations(&product_release, &destination, &registry_artifacts, &operations, &slots)?;
            let digest = digest_intent(
                &decision,
                &product_release,
