fn decision_for(
    release: &ProductReleaseId,
    packages: impl IntoIterator<Item = ReleasePackageId>,
) -> ReleaseDecisionV1 {
    ReleaseDecisionV1::new(
        packages
            .into_iter()
            .map(|package| ReleaseDecisionEntry {
                package,
                target_version: release.version.clone(),
                reasons: vec![ReleaseInclusionReason::ExplicitSelection],
            })
            .collect(),
    )
    .unwrap()
}

fn operations_for(
    release: &ProductReleaseId,
    destination: &ReleaseDestinationBinding,
    slots: &[ReleaseArtifactSlot],
) -> Vec<ReleaseOperation> {
    let mut operations = Vec::new();
    let mut registry_ids = slots
        .iter()
        .filter_map(|slot| match slot {
            ReleaseArtifactSlot::RegistryPackage {
                package,
                version,
                registry,
                ..
            } => Some(ReleaseOperationId::RegistryArtifactPublish {
                package: package.clone(),
                version: version.clone(),
                registry: registry.clone(),
                slot: slot.clone(),
            }),
            _ => None,
        })
        .collect::<Vec<_>>();
    registry_ids.sort();
    registry_ids.dedup();
    operations.extend(
        registry_ids
            .iter()
            .cloned()
            .map(|id| ReleaseOperation::new(id, vec![]).unwrap()),
    );
    let tag = ReleaseOperationId::ProductTag {
        release: release.clone(),
        tag: release.tag(),
    };
    let prepare = ReleaseOperationId::ForgePrepare {
        release: release.clone(),
        repository: destination.forge_repository().clone(),
    };
    operations.push(ReleaseOperation::new(tag.clone(), registry_ids).unwrap());
    operations.push(ReleaseOperation::new(prepare.clone(), vec![tag]).unwrap());

