    fn effective_release_classification_changes_fingerprint_and_rejects_authority() {
        let (dir, runner) = fixture();
        let locator = crate::IgnoreWalkLocator::new(dir.path());
        let root = canonical_root(dir.path()).unwrap();
        let workspace = Workspace::load(root.clone(), &locator, &runner).unwrap();
        let package = workspace.graph.packages().next().unwrap();
        let id = ReleasePackageId::new(Ecosystem::Cargo, package.id.name()).unwrap();
        let version = decision().entries[0].target_version.clone();
