            root.join("callisto.toml"),
            "[[package-set]]\nmatch = 'cargo:*'\nrelease-unit = 'dev-only'\npublish-to = ['crates-io']\n",
        )
        .unwrap();
        let reread = Workspace::load(root, &locator, &runner).unwrap();
        let package = reread.graph.packages().next().unwrap();
        let after = package_fingerprint(&reread, &id, package, &version, None).unwrap();
        assert_ne!(before, after);
        assert!(matches!(
            derive_release_inputs(&reread, &decision(), source),
            Err(GraphError::ReleasePackageNotSelected { .. })
        ));
    }
}

