    assert!(serde_json::from_value::<CompleteObservationReceipt>(top_level).is_err());

    let mut observed_operation = base.clone();
    observed_operation["operations"][0]["unexpected"] = serde_json::json!(true);
    assert!(serde_json::from_value::<CompleteObservationReceipt>(observed_operation).is_err());

