//! Fresh, graph-owned authorization for durable release intents.
//!
//! This module intentionally takes a root, locator, and runner rather than a
//! [`Workspace`]. A workspace caches parsed manifests and config for a normal
//! command invocation; accepting one here would make a previously observed
//! graph look current after the filesystem changed.

use std::collections::{BTreeMap, BTreeSet};
use std::path::Path;

use callisto_model::{
    ApplyPermit, ApprovedRegistryArtifact, CanonicalTranscript, CommandOutput, CommandRunner, CommitSha, Ecosystem,
    GitHubRepository, GitHubRepositoryParseError, NpmAccess, OperationOutcome, ProductName, ProductReleaseId,
    ProductTarget, RegistryArtifactFormat, RegistryBindingDigest, RegistryBindingId, RegistryKey,
    RegistryPublicationPolicy, ReleaseArtifactSlot, ReleaseDecisionV1, ReleaseDestinationBinding,
    ReleaseDestinationKind, ReleaseIntent, ReleaseOperation, ReleaseOperationId, ReleasePackageId, TagName, Version,
};
use callisto_vcs::{
    access::{GitCommitTrustEvidence, GitHeadDisposition},
    release_lock::ReleaseWorkspaceLock,
    GitAccess, GitDataSource, TagSignPolicy,
};

use crate::error::{
    CommandFailure, ReleasePreconditionRequirement, ReleaseSelectionInvalidReason, RemoteConflict,
    UnsupportedReleaseFeature,
};
use crate::{commands::registry_argv, DependencyResolver, GraphError, ProjectLocator, Workspace};

/// Reason carried by [`GraphError::ReleaseIntentStale`] (E124); real reasons are constructible only from this module.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct StaleReason {
    kind: StaleKind,
}

#[derive(Clone, Debug, PartialEq, Eq, thiserror::Error)]
enum StaleKind {
    #[error("the re-observed Git commit trust evidence no longer matches what the intent was validated against")]
    TrustEvidenceChanged,
    #[error("the re-observed source identity no longer matches what the intent was validated against")]
    SourceIdentityChanged,
    #[error("the re-observed Git push remote no longer matches what the intent was validated against")]
    GitRemoteChanged,
    #[error("a fresh derivation from the current workspace no longer matches the intent that was validated")]
    IntentDiffersFromFreshDerivation,
}

impl std::fmt::Display for StaleReason {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        std::fmt::Display::fmt(&self.kind, formatter)
    }
}

impl StaleReason {
    fn trust_evidence_changed() -> Self {
        StaleReason {
            kind: StaleKind::TrustEvidenceChanged,
        }
    }

    fn source_identity_changed() -> Self {
        StaleReason {
            kind: StaleKind::SourceIdentityChanged,
        }
    }

    fn git_remote_changed() -> Self {
        StaleReason {
            kind: StaleKind::GitRemoteChanged,
        }
    }

    fn intent_differs_from_fresh_derivation() -> Self {
        StaleReason {
            kind: StaleKind::IntentDiffersFromFreshDerivation,
        }
    }
}

/// The invocation data for one effect. This is deliberately graph-private:
/// callers can inspect the serializable intent, but cannot substitute a new
/// endpoint, tag target, or package directory at execution time.
#[allow(dead_code)] // consumed by the durable executor batch
#[derive(Debug)]
enum PreparedOperation {
    RegistryArtifactPublish {
        package_dir: std::path::PathBuf,
        artifact: ApprovedRegistryArtifact,
        registry: PreparedRegistryBinding,
    },
    ProductTag {
        name: TagName,
        target: CommitSha,
        annotation: String,
        remote: PreparedGitRemote,
    },
    ForgePrepare {
        repository: GitHubRepository,
        tag: TagName,
    },
    ArtifactUpload {
        slot: ReleaseArtifactSlot,
    },
    ForgePublish {
        repository: GitHubRepository,
        tag: TagName,
    },
}

/// Credential-free, canonical registry routing. `endpoint` is populated only
/// after parsing rejects userinfo, query, and fragments, so a later executor
/// cannot recover credentials from this capability.
#[allow(dead_code)] // consumed by the durable executor batch
#[derive(Clone, Debug, PartialEq, Eq)]
struct PreparedRegistryBinding {
    key: RegistryKey,
    endpoints: PreparedRegistryEndpoints,
    identity: RegistryBindingDigest,
    credential: PreparedCredentialEnvPolicy,
}

#[derive(Clone, Debug, PartialEq, Eq)]
enum PreparedCredentialEnvPolicy {
    CargoToken { env_name: String },
    NpmToken { env_name: &'static str },
    PypiToken {
        password_env_name: &'static str,
        username: &'static str,
    },
}

#[allow(dead_code)]
#[derive(Clone, Debug, PartialEq, Eq)]
enum PreparedRegistryEndpoints {
    Cargo {
        index: String,
        api: String,
    },
    Npm {
        registry: String,
    },
    Pypi {
        upload: String,
        metadata: String,
        simple: String,
    },
}

/// Read-only, graph-internal view of typed, credential-free registry routing.
#[derive(Clone, Copy, Debug)]
pub(super) enum PreparedRegistryEndpointsView<'a> {
    Cargo {
        index: &'a str,
        api: &'a str,
    },
    Npm {
        registry: &'a str,
    },
    Pypi {
        upload: &'a str,
        metadata: &'a str,
        simple: &'a str,
    },
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(super) enum PreparedCredentialEnvPolicyView<'a> {
    CargoToken { env_name: &'a str },
    NpmToken { env_name: &'static str },
    PypiToken {
        password_env_name: &'static str,
        username: &'static str,
    },
}

/// The exact prepared capability paired with one immutable operation.
///
/// This view is crate-private and non-serializable. It exposes only canonical,
/// credential-free identities needed by the observer/dispatcher boundary.
#[derive(Clone, Copy, Debug)]
pub(super) enum PreparedOperationView<'a> {
    RegistryArtifactPublish {
        artifact: &'a ApprovedRegistryArtifact,
        registry_key: &'a RegistryKey,
        binding_digest: &'a RegistryBindingDigest,
        endpoints: PreparedRegistryEndpointsView<'a>,
        credential: PreparedCredentialEnvPolicyView<'a>,
    },
    ProductTag {
        name: &'a TagName,
        target: &'a CommitSha,
        annotation: &'a str,
        remote_name: &'static str,
        repository: &'a GitHubRepository,
    },
    ForgePrepare {
        repository: &'a GitHubRepository,
        tag: &'a TagName,
    },
    ArtifactUpload {
        slot: &'a ReleaseArtifactSlot,
    },
    ForgePublish {
        repository: &'a GitHubRepository,
        tag: &'a TagName,
    },
}

/// Immutable, credential-free destination for Git effects. Its canonical
/// digest is included in each tag-producing package fingerprint; the URL is
/// retained only in the validated, non-serializable capability.
#[derive(Clone, Debug, PartialEq, Eq)]
struct PreparedGitRemote {
    remote_name: &'static str,
    endpoint: String,
    identity: callisto_model::SemanticInputDigest,
    github_repository: GitHubRepository,
}

/// Graph-private inputs prepared from the same fresh observation as an intent.
/// The executor will consume these when introduced; retaining them in the
/// capability prevents a validated public intent being paired with new inputs.
#[allow(dead_code)] // consumed by the durable executor batch
#[derive(Debug)]
struct PreparedReleaseInputs {
    root: std::path::PathBuf,
    source: CommitSha,
    trust: GitCommitTrustEvidence,
    git_remote: PreparedGitRemote,
    _lock: ReleaseWorkspaceLock,
    operations: BTreeMap<ReleaseOperationId, PreparedOperation>,
}

#[derive(Debug, PartialEq, Eq)]
struct ObservedTag {
    target: CommitSha,
    annotation: String,
}

#[derive(Debug, PartialEq, Eq)]
enum ForgeReleaseObservation {
    Missing,
    Exact,
    Conflict,
}

struct PreparedDerivation {
    intent: ReleaseIntent,
    operations: BTreeMap<ReleaseOperationId, PreparedOperation>,
    git_remote: PreparedGitRemote,
}

/// In-memory, non-transferable proof that an intent was rebuilt from a fresh
/// workspace observation. It is intentionally neither cloneable nor serializable.
pub struct ValidatedReleaseIntent<'a> {
    intent: ReleaseIntent,
    prepared: PreparedReleaseInputs,
    #[allow(dead_code)] // consumed by the durable execution coordinator
    runner: &'a dyn CommandRunner,
}

impl std::fmt::Debug for ValidatedReleaseIntent<'_> {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        formatter
            .debug_struct("ValidatedReleaseIntent")
            .field("intent", &self.intent)
            .finish_non_exhaustive()
    }
}

impl ValidatedReleaseIntent<'_> {
    pub fn intent(&self) -> &ReleaseIntent {
        &self.intent
    }

    #[allow(dead_code)] // consumed by the durable executor batch
    fn prepared(&self) -> &PreparedReleaseInputs {
        &self.prepared
    }

    pub(super) fn runner(&self) -> &dyn CommandRunner {
        self.runner
    }

    pub(super) fn root(&self) -> &Path {
        &self.prepared.root
    }

    pub(super) fn prepared_operation(&self, id: &ReleaseOperationId) -> Option<PreparedOperationView<'_>> {
        self.prepared.operations.get(id).map(|operation| match operation {
            PreparedOperation::RegistryArtifactPublish { artifact, registry, .. } => {
                PreparedOperationView::RegistryArtifactPublish {
                    artifact,
                    registry_key: &registry.key,
                    binding_digest: &registry.identity,
                    endpoints: match &registry.endpoints {
                        PreparedRegistryEndpoints::Cargo { index, api } => {
                            PreparedRegistryEndpointsView::Cargo { index, api }
                        }
                        PreparedRegistryEndpoints::Npm { registry } => PreparedRegistryEndpointsView::Npm { registry },
                        PreparedRegistryEndpoints::Pypi {
                            upload,
                            metadata,
                            simple,
                        } => PreparedRegistryEndpointsView::Pypi {
                            upload,
                            metadata,
                            simple,
                        },
                    },
                    credential: match &registry.credential {
                        PreparedCredentialEnvPolicy::CargoToken { env_name } => {
                            PreparedCredentialEnvPolicyView::CargoToken { env_name }
                        }
                        PreparedCredentialEnvPolicy::NpmToken { env_name } => {
                            PreparedCredentialEnvPolicyView::NpmToken { env_name }
                        }
                        PreparedCredentialEnvPolicy::PypiToken {
                            password_env_name,
                            username,
                        } => PreparedCredentialEnvPolicyView::PypiToken {
                            password_env_name,
                            username,
                        },
                    },
                }
            }
            PreparedOperation::ProductTag {
                name,
                target,
                annotation,
                remote,
            } => PreparedOperationView::ProductTag {
                name,
                target,
                annotation,
                remote_name: remote.remote_name,
                repository: &remote.github_repository,
            },
            PreparedOperation::ForgePrepare { repository, tag } => {
                PreparedOperationView::ForgePrepare { repository, tag }
            }
            PreparedOperation::ArtifactUpload { slot } => PreparedOperationView::ArtifactUpload { slot },
            PreparedOperation::ForgePublish { repository, tag } => {
                PreparedOperationView::ForgePublish { repository, tag }
            }
        })
    }

    /// Re-observes the held workspace immediately before an effect.
    #[allow(dead_code)] // consumed by the durable execution coordinator
    pub(crate) fn recheck_trust(&self) -> Result<(), GraphError> {
        let evidence =
            callisto_vcs::GitAccess::discover(&self.prepared.root, self.runner).observe_git_commit_trust()?;
        if evidence != self.prepared.trust || evidence.head() != &self.prepared.source {
            return Err(GraphError::ReleaseIntentStale {
                reason: StaleReason::trust_evidence_changed(),
            });
        }
        if prepared_git_remote(&self.prepared.root, self.runner).as_ref() != Ok(&self.prepared.git_remote) {
            return Err(GraphError::ReleaseIntentStale {
                reason: StaleReason::git_remote_changed(),
            });
        }
        Ok(())
    }
}

/// Builds a release intent from a fresh root-bound observation.
pub fn build_release_intent<L: ProjectLocator, R: CommandRunner>(
    root: &Path,
    locator: &L,
    runner: &R,
    decision: &ReleaseDecisionV1,
    profile_name: &str,
) -> Result<ReleaseIntent, GraphError> {
    let root = canonical_root(root)?;
    let workspace = Workspace::load(root.clone(), locator, runner)?;
    let source = observe_source(&workspace)?;
    let intent = derive_product_release(&workspace, decision, source.clone(), profile_name)?.intent;
        }
        let annotation = annotation.ok_or_else(|| GraphError::ReleaseInvariant {
            detail: "for-each-ref line validated as `tag`/empty-body but carried no annotation field".to_string(),
        })?;
        Ok(Some(ObservedTag {
            target,
            annotation: annotation.to_string(),
        }))
    }

    fn observed_forge_release_target(
        &self,
        tag: &TagName,
        repository: &str,
    ) -> Result<ForgeReleaseObservation, GraphError> {
        let endpoint = format!("repos/{repository}/releases/tags/{tag}");
        let api_args = [
            "api",
            "--include",
            "--method",
            "GET",
            endpoint.as_str(),
            "--repo",
            repository,
        ];
        let observed = self.runner.run("gh", &api_args, &self.prepared.root)?;
        if observed.exit_code != Some(0) {
            return Err(GraphError::ReleaseCommand {
                program: "gh".to_string(),
                args: api_args.iter().map(ToString::to_string).collect(),
                failure: CommandFailure::NonZeroExit {
                    exit_code: observed.exit_code,
                    stderr: observed.stderr,
                },
            });
        }
        let (status, body) = parse_github_api_response("gh", &api_args, &observed.stdout)?;
        if status == 404 {
            return Ok(ForgeReleaseObservation::Missing);
        }
        if status != 200 {
            return Err(GraphError::ReleaseRemoteConflict {
                conflict: RemoteConflict::ForgeApiStatus,
            });
        }
        let value: serde_json::Value = serde_json::from_str(body).map_err(|error| GraphError::ReleaseCommand {
            program: "gh".to_string(),
            args: api_args.iter().map(ToString::to_string).collect(),
            failure: CommandFailure::MalformedOutput {
                detail: error.to_string(),
            },
        })?;
        let expected = self.prepared.source.as_str();
        Ok(
            if value.get("tag_name").and_then(serde_json::Value::as_str) == Some(tag.as_str())
                && value.get("target_commitish").and_then(serde_json::Value::as_str) == Some(expected)
            {
                ForgeReleaseObservation::Exact
            } else {
                ForgeReleaseObservation::Conflict
            },
        )
    }

    fn checked_git_remote(&self) -> Result<&PreparedGitRemote, GraphError> {
        let expected = &self.prepared.git_remote;
        if prepared_git_remote(&self.prepared.root, self.runner)? != *expected {
            return Err(GraphError::ReleaseIntentStale {
                reason: StaleReason::git_remote_changed(),
            });
        }
        Ok(expected)
    }
}

fn parse_github_api_response<'a>(program: &str, args: &[&str], stdout: &'a str) -> Result<(u16, &'a str), GraphError> {
    let malformed = |detail: String| GraphError::ReleaseCommand {
        program: program.to_string(),
        args: args.iter().map(ToString::to_string).collect(),
        failure: CommandFailure::MalformedOutput { detail },
    };
    let (headers, body) = stdout
        .rsplit_once("\r\n\r\n")
        .or_else(|| stdout.rsplit_once("\n\n"))
        .ok_or_else(|| malformed("response has no blank line separating headers from body".to_string()))?;
    let status_line = headers
        .lines()
        .rev()
        .find(|line| line.trim_end_matches('\r').starts_with("HTTP/"))
        .ok_or_else(|| malformed("response headers contain no HTTP status line".to_string()))?;
    let status = status_line
        .split_whitespace()
        .nth(1)
        .ok_or_else(|| malformed(format!("HTTP status line has no status code: {status_line:?}")))?
        .parse::<u16>()
        .map_err(|error| malformed(format!("HTTP status code is not a valid number: {error}")))?;
    Ok((status, body))
}

fn derive_product_release<R: CommandRunner, D: DependencyResolver>(
    workspace: &Workspace<'_, R, D>,
    decision: &ReleaseDecisionV1,
    source: CommitSha,
    profile_name: &str,
) -> Result<PreparedDerivation, GraphError> {
    super::release_decision::validate_release_units(workspace, decision)?;
    let mut selected = BTreeMap::new();
    for package in workspace.graph.packages() {
        if !crate::config::is_release_unit(&workspace.config, &package.id)? {
            continue;
        }
        for id in super::release_decision::release_package_ids(package)?
            .into_iter()
            .collect::<BTreeSet<_>>()
        {
            if let Some(entry) = decision.entries.iter().find(|entry| entry.package == id) {
                selected.insert(id.clone(), (package, entry.target_version.clone()));
            }
        }
    }
    for entry in &decision.entries {
        let id = &entry.package;
        if !selected.contains_key(id) {
            return Err(GraphError::ReleasePackageNotSelected { package: id.clone() });
        }
    }

    let (product, profile) = workspace.config.release_profile(profile_name)?;
    let release = ProductReleaseId::from_coordinated_versions(
        ProductName::parse(&product.name)?,
        decision.entries.iter().map(|entry| entry.target_version.clone()),
    )?;
    let destination_kind = match profile.kind {
        crate::config::ReleaseProfileKind::Production => ReleaseDestinationKind::Production,
        crate::config::ReleaseProfileKind::Rehearsal => ReleaseDestinationKind::Rehearsal,
    };
    let cargo = prepared_registry_binding(&workspace.config, profile_name, Ecosystem::Cargo)?;
    let npm = prepared_registry_binding(&workspace.config, profile_name, Ecosystem::Npm)?;
    let pypi = prepared_registry_binding(&workspace.config, profile_name, Ecosystem::Pypi)?;
    let destination = ReleaseDestinationBinding::new(
        profile_name,
        destination_kind,
        profile.forge_repository.clone(),
        cargo.id()?,
        npm.id()?,
        pypi.id()?,
    )?;
    let git_remote = prepared_git_remote(&workspace.root, workspace.runner)?;
    if git_remote.github_repository != *destination.forge_repository() {
        return Err(GraphError::UnsafeGitRemote {
            reason: "origin repository does not match the selected release profile",
        });
    }
    let provenance = callisto_model::ProvenancePolicy::new(
        product.provenance_repository.clone(),
        product.build_workflow.clone(),
        source.clone(),
    )?;

    let registry_bindings = BTreeMap::from([
        (Ecosystem::Cargo, cargo),
        (Ecosystem::Npm, npm),
        (Ecosystem::Pypi, pypi),
    ]);
    let mut approved = Vec::new();
    let mut slots = Vec::new();
    let mut prepared = BTreeMap::new();
    let mut operations = BTreeMap::new();
    for (package_id, (package, version)) in &selected {
        let matching_targets = package
            .publish_to
            .iter()
            .filter(|target| target.ecosystem() == Some(package_id.ecosystem()))
            .collect::<Vec<_>>();
        let Some(target) = matching_targets.first().copied() else {
            continue;
        };
        if matching_targets.len() != 1 {
            return Err(GraphError::ReleaseSelectionInvalid {
                package: package_id.clone(),
                reason: ReleaseSelectionInvalidReason::DuplicateRegistryTarget,
            });
        }
        let binding = registry_bindings
            .get(&package_id.ecosystem())
            .ok_or(GraphError::UnsupportedRelease {
                feature: UnsupportedReleaseFeature::Ecosystem,
            })?;
        for (format, file_name) in registry_artifact_files(package_id, version)? {
            let publication_policy = match target {
                callisto_model::PublishTarget::CratesIo => RegistryPublicationPolicy::cargo(),
                callisto_model::PublishTarget::Npm { access, .. } => RegistryPublicationPolicy::npm(
                    access.unwrap_or(NpmAccess::Public),
                    if version.is_prerelease() { "next" } else { "latest" },
                )?,
                callisto_model::PublishTarget::Pypi { .. } => RegistryPublicationPolicy::pypi(),
                _ => {
                    return Err(GraphError::UnsupportedRelease {
                        feature: UnsupportedReleaseFeature::PublishTarget,
                    })
                }
            };
            let artifact = ApprovedRegistryArtifact::new(
                package_id.clone(),
                binding.id()?,
                format,
                publication_policy.clone(),
                file_name.clone(),
            )?;
            let slot = ReleaseArtifactSlot::registry_artifact(&artifact, version.clone(), provenance.clone());
            let id = ReleaseOperationId::RegistryArtifactPublish {
                package: package_id.clone(),
                version: version.clone(),
                registry: binding.id()?,
                slot: slot.clone(),
            };
            let operation = ReleaseOperation::new(id.clone(), vec![])?;
            if prepared
                .insert(
                    id.clone(),
                    PreparedOperation::RegistryArtifactPublish {
                        package_dir: package_dir(package)?,
                        artifact: artifact.clone(),
                        registry: binding.clone(),
                    },
                )
                .is_some()
            {
                return Err(GraphError::ReleaseSelectionInvalid {
                    package: package_id.clone(),
                    reason: ReleaseSelectionInvalidReason::DuplicateRegistryTarget,
                });
            }
            operations.insert(id, operation);
            approved.push(artifact);
            slots.push(slot);
        }
    }

    let mut registry_ids = operations.keys().cloned().collect::<Vec<_>>();
    registry_ids.sort();
    for target in ProductTarget::ALL {
        slots.push(ReleaseArtifactSlot::product_asset(
            release.clone(),
            target,
            provenance.clone(),
        ));
    }
    slots.push(ReleaseArtifactSlot::checksum_manifest(
        release.clone(),
        provenance.clone(),
    ));
    slots.push(ReleaseArtifactSlot::release_metadata(release.clone(), provenance));

    let tag_text = release.tag();
    // `ProductReleaseId::tag` combines a validated lowercase product name,
    // one literal `@`, and validated SemVer, so it is already a safe Git ref.
    let tag_name = TagName::new_unchecked(tag_text.clone());
    let tag_id = ReleaseOperationId::ProductTag {
        release: release.clone(),
        tag: tag_text,
    };
    operations.insert(tag_id.clone(), ReleaseOperation::new(tag_id.clone(), registry_ids)?);
    prepared.insert(
        tag_id.clone(),
        PreparedOperation::ProductTag {
            name: tag_name.clone(),
            target: source.clone(),
            annotation: format!("Release {tag_name}"),
            remote: git_remote.clone(),
        },
    );
    let prepare_id = ReleaseOperationId::ForgePrepare {
        release: release.clone(),
        repository: destination.forge_repository().clone(),
    };
    operations.insert(
        prepare_id.clone(),
        ReleaseOperation::new(prepare_id.clone(), vec![tag_id])?,
    );
    prepared.insert(
        prepare_id.clone(),
        PreparedOperation::ForgePrepare {
            repository: destination.forge_repository().clone(),
            tag: tag_name.clone(),
        },
    );
    let mut upload_ids = Vec::new();
    for slot in slots.iter().filter(|slot| slot.release().is_some()) {
        let id = ReleaseOperationId::ArtifactUpload {
            release: release.clone(),
            slot: slot.clone(),
        };
        operations.insert(id.clone(), ReleaseOperation::new(id.clone(), vec![prepare_id.clone()])?);
        prepared.insert(id.clone(), PreparedOperation::ArtifactUpload { slot: slot.clone() });
        upload_ids.push(id);
    }
    upload_ids.sort();
    let publish_id = ReleaseOperationId::ForgePublish {
        release: release.clone(),
        repository: destination.forge_repository().clone(),
    };
    operations.insert(
        publish_id.clone(),
        ReleaseOperation::new(publish_id.clone(), upload_ids)?,
    );
    prepared.insert(
        publish_id,
        PreparedOperation::ForgePublish {
            repository: destination.forge_repository().clone(),
            tag: tag_name,
        },
    );

    let operations = canonical_operation_order(operations)?;
    let intent = ReleaseIntent::new(
        decision.clone(),
        release,
        source,
        destination,
        approved,
        operations,
        slots,
    )?;
    let intent_ids = intent
        .operations()
        .iter()
        .map(|operation| operation.id().clone())
        .collect::<BTreeSet<_>>();
    if intent_ids != prepared.keys().cloned().collect() {
        return Err(GraphError::ReleaseInvariant {
            detail: "prepared operation map does not exactly match the derived intent".to_string(),
        });
    }
    Ok(PreparedDerivation {
        intent,
        operations: prepared,
        git_remote,
    })
}

fn registry_artifact_files(
    package: &ReleasePackageId,
    version: &Version,
) -> Result<Vec<(RegistryArtifactFormat, String)>, GraphError> {
    let version = version.render();
    match package.ecosystem() {
        Ecosystem::Cargo => Ok(vec![(
            RegistryArtifactFormat::CargoCrate,
            format!("{}-{version}.crate", package.name()),
        )]),
        Ecosystem::Npm => Ok(vec![(
            RegistryArtifactFormat::NpmTarball,
            format!(
                "{}-{version}.tgz",
                package.name().trim_start_matches('@').replace('/', "-")
            ),
        )]),
        Ecosystem::Pypi => Err(GraphError::ReleaseInvariant {
            detail: format!(
                "PyPI release artifact names for `{package}` require exact graph-owned distribution descriptors; wheel tags must not be guessed"
            ),
        }),
        _ => Err(GraphError::UnsupportedRelease {
            feature: UnsupportedReleaseFeature::Ecosystem,
        }),
    }
}

fn package_dir(package: &callisto_model::Package) -> Result<std::path::PathBuf, GraphError> {
    package
        .canonical_manifests()
        .next()
        .and_then(|manifest| manifest.path.parent())
        .map(std::path::Path::to_path_buf)
        .ok_or_else(|| GraphError::ReleaseInvariant {
            detail: format!("selected release package `{}` has no canonical manifest", package.id),
        })
}

fn canonical_operation_order(
    operations: BTreeMap<ReleaseOperationId, ReleaseOperation>,
) -> Result<Vec<ReleaseOperation>, GraphError> {
    let mut remaining: BTreeMap<_, usize> = operations
        .iter()
        .map(|(id, operation)| (id.clone(), operation.prerequisites().len()))
        .collect();
    let mut dependents = BTreeMap::<ReleaseOperationId, Vec<ReleaseOperationId>>::new();
    for (id, operation) in &operations {
        for prerequisite in operation.prerequisites() {
            dependents.entry(prerequisite.clone()).or_default().push(id.clone());
        }
    }
    let mut ready: BTreeSet<_> = remaining
        .iter()
        .filter_map(|(id, count)| (*count == 0).then_some(id.clone()))
        .collect();
    let mut ordered = Vec::with_capacity(operations.len());
    while let Some(id) = ready.pop_first() {
        ordered.push(operations.get(&id).expect("known operation").clone());
        for dependent in dependents.get(&id).into_iter().flatten() {
            let count = remaining.get_mut(dependent).expect("known operation");
            *count -= 1;
            if *count == 0 {
                ready.insert(dependent.clone());
            }
        }
    }
    if ordered.len() != operations.len() {
        return Err(GraphError::ReleaseInvariant {
            detail: "release operation DAG contains a cycle: topological sort could not order every operation"
                .to_string(),
        });
    }
    Ok(ordered)
}

impl PreparedRegistryBinding {
    fn id(&self) -> Result<RegistryBindingId, GraphError> {
        RegistryBindingId::new(self.key.as_str(), self.identity.clone()).map_err(GraphError::from)
    }
}

fn prepared_registry_binding(
    config: &crate::config::ResolvedConfig,
    profile_name: &str,
    ecosystem: Ecosystem,
) -> Result<PreparedRegistryBinding, GraphError> {
    let (key, endpoints) = config.release_registry(profile_name, ecosystem)?;
    let (prepared, transcript_fields): (PreparedRegistryEndpoints, Vec<(&str, &str)>) = match endpoints {
        crate::config::RegistryEndpoints::Cargo { index, api } => (
            PreparedRegistryEndpoints::Cargo {
                index: index.clone(),
                api: api.clone(),
            },
            vec![("cargo.index", index), ("cargo.api", api)],
        ),
        crate::config::RegistryEndpoints::Npm { registry } => (
            PreparedRegistryEndpoints::Npm {
                registry: registry.clone(),
            },
            vec![("npm.registry", registry)],
        ),
        crate::config::RegistryEndpoints::Pypi {
            upload,
            metadata,
            simple,
        } => (
            PreparedRegistryEndpoints::Pypi {
                upload: upload.clone(),
                metadata: metadata.clone(),
                simple: simple.clone(),
            },
            vec![
                ("pypi.upload", upload),
                ("pypi.metadata", metadata),
                ("pypi.simple", simple),
            ],
        ),
    };
    let mut transcript = CanonicalTranscript::semantic_input_v1();
    transcript.push_str("registry.key", key.as_str());
    for (field, value) in transcript_fields {
        transcript.push_str(field, value);
    }
    Ok(PreparedRegistryBinding {
        key: key.clone(),
        endpoints: prepared,
        identity: RegistryBindingDigest::from_normalized_binding(transcript.as_bytes()),
        credential: prepared_credential_policy(ecosystem, key)?,
    })
}

fn prepared_credential_policy(
    ecosystem: Ecosystem,
    key: &RegistryKey,
) -> Result<PreparedCredentialEnvPolicy, GraphError> {
    let normalized_key = key
        .as_str()
        .bytes()
        .map(|byte| match byte {
            b'a'..=b'z' => (byte - b'a' + b'A') as char,
            b'A'..=b'Z' | b'0'..=b'9' => byte as char,
            b'-' | b'_' => '_',
            _ => '\0',
        })
        .collect::<String>();
    if normalized_key.is_empty() || normalized_key.contains('\0') {
        return Err(GraphError::ReleaseInvariant {
            detail: format!("registry key `{key}` cannot form a safe credential environment name"),
        });
    }
    match ecosystem {
        Ecosystem::Cargo => Ok(PreparedCredentialEnvPolicy::CargoToken {
            env_name: if matches!(key.as_str(), "crates-io" | RegistryKey::CRATES_IO) {
                "CARGO_REGISTRY_TOKEN".to_string()
            } else {
                format!("CARGO_REGISTRIES_{normalized_key}_TOKEN")
            },
        }),
        Ecosystem::Npm => Ok(PreparedCredentialEnvPolicy::NpmToken { env_name: "NPM_TOKEN" }),
        Ecosystem::Pypi => Ok(PreparedCredentialEnvPolicy::PypiToken {
            password_env_name: "TWINE_PASSWORD",
            username: "__token__",
        }),
        _ => Err(GraphError::UnsupportedRelease {
            feature: UnsupportedReleaseFeature::Ecosystem,
        }),
    }
}

/// Maps a `url::ParseError` to a specific, static diagnostic reason for
/// [`GraphError::UnsafeRegistryBinding`]/[`GraphError::UnsafeGitRemote`],
/// rather than discarding it behind one generic "invalid URL" message.
fn url_parse_error_reason(error: url::ParseError) -> &'static str {
    match error {
        url::ParseError::RelativeUrlWithoutBase => "URL has no scheme (e.g. missing `https://`)",
        url::ParseError::EmptyHost => "URL host is empty",
        url::ParseError::InvalidPort => "URL port is invalid",
        url::ParseError::InvalidIpv4Address | url::ParseError::InvalidIpv6Address => {
            "URL host is not a valid IP address"
        }
        url::ParseError::InvalidDomainCharacter => "URL host contains an invalid character",
        url::ParseError::Overflow => "URL exceeds the maximum length",
        _ => "invalid URL",
    }
}

/// Maps a [`GitHubRepositoryParseError`] to a specific, static diagnostic
/// reason for [`GraphError::UnsafeGitRemote`], rather than discarding it
/// behind one generic message for every distinct parse failure.
fn github_repository_parse_error_reason(error: &GitHubRepositoryParseError) -> &'static str {
    match error {
        GitHubRepositoryParseError::MissingSeparator { .. } => "GitHub remote path must be in owner/repo form",
        GitHubRepositoryParseError::TooManyParts { .. } => "GitHub remote path has more than one `/`",
        GitHubRepositoryParseError::InvalidOwner { .. } => "GitHub owner name is invalid",
        GitHubRepositoryParseError::InvalidRepo { .. } => "GitHub repository name is invalid",
        #[allow(unreachable_patterns)]
        _ => "GitHub owner or repository name is invalid",
    }
}

fn prepared_git_remote(root: &Path, runner: &dyn CommandRunner) -> Result<PreparedGitRemote, GraphError> {
    let output = runner.run("git", &["remote", "get-url", "--push", "origin"], root)?;
    if output.exit_code != Some(0) {
        return Err(GraphError::UnsafeGitRemote {
            reason: "origin must have a push URL",
        });
    }
    canonical_git_remote(output.stdout.trim())
}

fn canonical_git_remote(raw: &str) -> Result<PreparedGitRemote, GraphError> {
    let ssh_url = if raw.starts_with("git@") && !raw.contains("//") {
        let (host, path) =
            raw.strip_prefix("git@")
                .and_then(|value| value.split_once(':'))
                .ok_or(GraphError::UnsafeGitRemote {
                    reason: "invalid SSH remote syntax",
                })?;
        format!("ssh://git@{host}/{path}")
    } else {
        raw.to_string()
    };
    let parsed = url::Url::parse(&ssh_url).map_err(|error| GraphError::UnsafeGitRemote {
        reason: url_parse_error_reason(error),
    })?;
    if parsed.cannot_be_a_base() || parsed.host_str().is_none() {
        return Err(GraphError::UnsafeGitRemote {
            reason: "URL must have an authority",
        });
    }
    if !matches!(parsed.scheme(), "https" | "ssh") {
        return Err(GraphError::UnsafeGitRemote {
            reason: "URL scheme must be HTTPS or SSH",
        });
    }
    if parsed.password().is_some() || parsed.query().is_some() || parsed.fragment().is_some() {
        return Err(GraphError::UnsafeGitRemote {
            reason: "credentials, query strings, and fragments are forbidden",
        });
    }
    if parsed.scheme() == "https" && !parsed.username().is_empty() {
        return Err(GraphError::UnsafeGitRemote {
            reason: "HTTPS userinfo is forbidden",
        });
    }
    if parsed.scheme() == "ssh" && parsed.username() != "git" {
        return Err(GraphError::UnsafeGitRemote {
            reason: "SSH remotes must use the git account",
        });
    }
    let host = parsed.host_str().expect("validated authority").to_ascii_lowercase();
    let mut components = parsed.path_segments().ok_or(GraphError::UnsafeGitRemote {
        reason: "remote path is invalid",
    })?;
    let owner = components
        .next()
        .filter(|value| !value.is_empty())
        .ok_or(GraphError::UnsafeGitRemote {
            reason: "remote path must name an owner and repository",
        })?;
    let repository = components
        .next()
        .filter(|value| !value.is_empty())
        .ok_or(GraphError::UnsafeGitRemote {
            reason: "remote path must name an owner and repository",
        })?;
    if components.next().is_some() || owner == "." || owner == ".." || repository == "." || repository == ".." {
        return Err(GraphError::UnsafeGitRemote {
            reason: "remote path must contain exactly an owner and repository",
        });
    }
    let repository = repository.strip_suffix(".git").unwrap_or(repository);
    if repository.is_empty() {
        return Err(GraphError::UnsafeGitRemote {
            reason: "repository name is empty",
        });
    }
    let port = parsed.port_or_known_default();
    let port_text = match (parsed.scheme(), port) {
        ("https", Some(443)) | ("ssh", Some(22)) | (_, None) => String::new(),
        (_, Some(port)) => format!(":{port}"),
    };
    let endpoint = match parsed.scheme() {
        "https" => format!("https://{host}{port_text}/{owner}/{repository}.git"),
        "ssh" => format!("ssh://git@{host}{port_text}/{owner}/{repository}.git"),
        _ => unreachable!("scheme checked above"),
    };
    let mut transcript = CanonicalTranscript::semantic_input_v1();
    transcript.push_str("gitRemote.scheme", parsed.scheme());
    transcript.push_str("gitRemote.host", &host);
    transcript.push_str(
        "gitRemote.port",
        &port.map_or_else(String::new, |port| port.to_string()),
    );
    transcript.push_str("gitRemote.owner", owner);
    transcript.push_str("gitRemote.repository", repository);
    if host != "github.com" {
        return Err(GraphError::UnsafeGitRemote {
            reason: "release forge remote must be hosted on github.com",
