/// Builds a release intent from a fresh root-bound observation.
pub fn build_release_intent<L: ProjectLocator, R: CommandRunner>(
    root: &Path,
    locator: &L,
    runner: &R,
    decision: &ReleaseDecisionV1,
    profile_name: &str,
) -> Result<ReleaseIntent, GraphError> {
    let root = canonical_root(root)?;
    let workspace = Workspace::load(root.clone(), locator, runner)?;
    let source = observe_source(&workspace)?;
    let intent = derive_product_release(&workspace, decision, source.clone(), profile_name)?.intent;

    // Recheck after all input reads. A concurrent edit or checkout cannot be
    // authorized merely because it happened after the first check.
    if observe_source(&workspace)? != source {
        return Err(GraphError::ReleaseIntentStale {
            reason: StaleReason::source_identity_changed(),
        });
    }
    Ok(intent)
}

/// Re-observes root, config, package discovery, manifests, Git evidence, and
/// the exact operation DAG before creating an opaque authorization capability.
pub fn validate_release_intent<'a, L: ProjectLocator, R: CommandRunner>(
    root: &Path,
    locator: &L,
    runner: &'a R,
    received: ReleaseIntent,
) -> Result<ValidatedReleaseIntent<'a>, GraphError> {
    validate_release_intent_with_state_directory(root, locator, runner, None, received)
}

/// Validates an intent while placing its workspace lock under an explicit
/// caller-owned state directory.
///
/// CI callers that supply an explicit durable state file must use its parent
/// here as well.  Otherwise validation would still depend on the runner's
/// implicit platform state location, defeating hermetic job handoff.
pub fn validate_release_intent_with_state_directory<'a, L: ProjectLocator, R: CommandRunner>(
    root: &Path,
    locator: &L,
    runner: &'a R,
    state_directory: Option<&Path>,
    received: ReleaseIntent,
) -> Result<ValidatedReleaseIntent<'a>, GraphError> {
    let root = canonical_root(root)?;
    let workspace = Workspace::load(root.clone(), locator, runner)?;
    let initial_trust = observe_git_trust(&workspace)?;
    let lock = ReleaseWorkspaceLock::acquire(&root, state_directory)?;
    let trust = observe_git_trust(&workspace)?;
    if trust != initial_trust {
        return Err(GraphError::ReleaseIntentStale {
            reason: StaleReason::trust_evidence_changed(),
        });
    }
    let source = trust.head().clone();
    let prepared = derive_product_release(
        &workspace,
        received.decision(),
        source.clone(),
        received.destination().profile_name(),
    )?;
    let final_trust = observe_git_trust(&workspace)?;
    if prepared.intent != received || final_trust != trust {
        return Err(GraphError::ReleaseIntentStale {
            reason: StaleReason::intent_differs_from_fresh_derivation(),
        });
    }

    Ok(ValidatedReleaseIntent {
        prepared: PreparedReleaseInputs {
            root,
            source,
            trust: final_trust,
            git_remote: prepared.git_remote,
            _lock: lock,
            operations: prepared.operations,
        },
        intent: received,
        runner,
    })
}

fn canonical_root(root: &Path) -> Result<std::path::PathBuf, GraphError> {
    dunce::canonicalize(root).map_err(|error| GraphError::ReleaseInputRead {
        path: root.to_path_buf(),
        message: error.to_string(),
    })
}

fn observe_source<R: CommandRunner, D: DependencyResolver>(
    workspace: &Workspace<'_, R, D>,
) -> Result<CommitSha, GraphError> {
    Ok(observe_git_trust(workspace)?.head().clone())
}

fn observe_git_trust<R: CommandRunner, D: DependencyResolver>(
    workspace: &Workspace<'_, R, D>,
) -> Result<GitCommitTrustEvidence, GraphError> {
    let evidence = workspace.git_access().observe_git_commit_trust()?;
    if evidence.canonical_root() != workspace.root {
        return Err(GraphError::ReleasePreconditionUnmet {
            requirement: ReleasePreconditionRequirement::CanonicalRootMatchesWorkspace,
        });
    }
    if evidence.head_disposition() != GitHeadDisposition::Detached {
        return Err(GraphError::ReleasePreconditionUnmet {
            requirement: ReleasePreconditionRequirement::DetachedHead,
        });
    }
    Ok(evidence)
}

impl ValidatedReleaseIntent<'_> {
    /// Dispatches exactly one graph-private operation prepared during fresh
    /// validation. This is intentionally the only production effect path: it
    /// never accepts a path, endpoint, tag, package name, or version from a
    /// caller.
    pub(crate) fn dispatch_prepared(
        &self,
        permit: &ApplyPermit,
        id: &ReleaseOperationId,
    ) -> Result<OperationOutcome, GraphError> {
        let operation = self
            .prepared
            .operations
            .get(id)
            .ok_or_else(|| GraphError::ReleaseInvariant {
                detail: format!("dispatch_prepared: no prepared operation for `{id:?}`"),
            })?;
        match operation {
            PreparedOperation::ProductTag {
                name,
                target,
                annotation,
                ..
            } => self.dispatch_tag(permit, name, target, annotation),
            PreparedOperation::RegistryArtifactPublish { .. }
            | PreparedOperation::ForgePrepare { .. }
            | PreparedOperation::ArtifactUpload { .. }
            | PreparedOperation::ForgePublish { .. } => Err(GraphError::ReleaseInvariant {
                detail: format!(
                    "dispatch for promoted product operation `{id:?}` is owned by the coordinated PM-005/T3 cutover"
                ),
            }),
        }
    }
}

/// Ecosystems whose publish gets confirmed against the registry before the
/// operation is marked done. Npm and Cargo are checked; PyPI has the
/// identical propagation-lag gap, deliberately deferred -- no PyPI package
/// or credentials in this workspace to test a fix against. The single
/// source of truth `dispatch_registry` actually consults, so a test on this
/// function directly proves the runtime gate, not a copy of it.
fn ecosystem_requires_registry_confirmation(ecosystem: Ecosystem) -> bool {
    matches!(ecosystem, Ecosystem::Npm | Ecosystem::Cargo)
}

/// A successful publish-client exit isn't a receipt: confirms the registry
/// itself has caught up before treating the operation as done. If not, it
/// stays `Attempting` for reconciliation, reported via its own variant
/// rather than `ReleaseIntentStale`'s false "no operation was authorized".
fn require_registry_confirmation(is_published: bool, package: &str, version: &Version) -> Result<(), GraphError> {
    if is_published {
        return Ok(());
    }
    Err(GraphError::RegistryPublishUnconfirmed {
        package: package.to_string(),
        version: version.clone(),
    })
}

/// Retries after this many unconfirmed checks: 3 retries (4 checks total).
const REGISTRY_CONFIRMATION_MAX_RETRIES: u32 = 3;

/// Exponential backoff between confirmation checks: 2s, 4s, 8s (14s worst
/// case) -- registry index propagation is normally sub-second, so this only
/// costs time on the rare lagging case, not the common one.
fn registry_confirmation_backoff(retry: u32) -> std::time::Duration {
    std::time::Duration::from_secs(2u64.pow(retry + 1))
}

/// Retries `check` up to `max_retries` more times, sleeping `backoff(retry)`
/// between attempts, and returns as soon as it reports published. Returns
/// `Ok(false)` if it never does. `sleep` is injected so tests can verify the
/// retry count and schedule without a real wall-clock wait.
fn poll_until_published(
    mut check: impl FnMut() -> Result<bool, GraphError>,
    max_retries: u32,
    backoff: impl Fn(u32) -> std::time::Duration,
    sleep: impl Fn(std::time::Duration),
) -> Result<bool, GraphError> {
    for retry in 0..=max_retries {
        if check()? {
            return Ok(true);
        }
        if retry < max_retries {
            sleep(backoff(retry));
        }
    }
    Ok(false)
}

impl ValidatedReleaseIntent<'_> {
    /// Runs a [`registry_argv::Argv`] built by the pure argv layer. This is
    /// the only place `dispatch_registry` touches [`CommandRunner`] --
    /// everything about *what* to run (program, args, cwd) was already
    /// decided by `registry_argv`.
    fn run_argv(&self, argv: &registry_argv::Argv) -> Result<CommandOutput, GraphError> {
        let args: Vec<&str> = argv.args.iter().map(String::as_str).collect();
        Ok(self.runner.run(&argv.program, &args, &argv.cwd)?)
    }

    fn npm_version_is_published(
        &self,
        package_name: &str,
        version: &Version,
        registry: Option<&str>,
    ) -> Result<bool, GraphError> {
        let spec = format!("{package_name}@{}", version.render());
        let mut args = vec!["view", spec.as_str(), "--json"];
        if let Some(registry) = registry {
            args.extend(["--registry", registry]);
        }
        let output = self
            .runner
            .run_quiet("npm", &args, &self.prepared.root, std::time::Duration::from_secs(300))?;
        if output.success() {
            return Ok(!output.stdout_trimmed().is_empty());
        }
        let details = format!("{}\n{}", output.stdout, output.stderr).to_ascii_lowercase();
        if details.contains("e404")
            || details.contains("etarget")
            || details.contains("no matching version")
            || details.contains("is not in this registry")
        {
            return Ok(false);
        }
        Err(GraphError::ReleaseCommand {
            program: "npm".to_string(),
            args: args.iter().map(ToString::to_string).collect(),
            failure: CommandFailure::NonZeroExit {
                exit_code: output.exit_code,
                stderr: output.stderr,
            },
        })
    }

    fn cargo_version_is_published(
        &self,
        package_name: &str,
        version: &Version,
        registry_key: Option<&str>,
    ) -> Result<bool, GraphError> {
        let spec = format!("{package_name}@{}", version.render());
        let mut args = vec!["info", spec.as_str()];
        if let Some(registry) = registry_key {
            args.extend(["--registry", registry]);
        }
        let output = self
            .runner
            .run_quiet("cargo", &args, &self.prepared.root, std::time::Duration::from_secs(300))?;
        registry_argv::classify_cargo_info_output(&output).map_err(|source| GraphError::Registry {
            package: package_name.to_string(),
            source,
        })
    }

    fn dispatch_tag(
        &self,
        permit: &ApplyPermit,
        name: &TagName,
        target: &CommitSha,
        annotation: &str,
    ) -> Result<OperationOutcome, GraphError> {
        if let Some(observed) = self.observed_tag(name)? {
            return if observed.target == *target && observed.annotation == annotation {
                Ok(OperationOutcome::AlreadySatisfied)
            } else {
                Err(GraphError::ReleaseRemoteConflict {
                    conflict: RemoteConflict::TagTargetDiffers,
                })
            };
        }
        // Delegates to `GitAccess::create_tag` rather than inlining `git
        // tag` argv, so this inherits its `--` end-of-options separator
        // (defends `name` against being misread as a flag) on top of the
        // `--no-sign` this durable path has always needed (this repo's CI
        // sets `tag.gpgSign`/`commit.gpgsign` globally in some contexts,
        // with no tag-signing key available here).
        let git = GitAccess::discover(&self.prepared.root, self.runner);
        git.create_tag(
            name.as_str(),
            target,
            Some(annotation),
            TagSignPolicy::ForceUnsigned,
            permit,
        )?;
        let remote_endpoint = self.checked_git_remote()?.endpoint.clone();
        let push_args = ["push", remote_endpoint.as_str(), name.as_str()];
        let pushed = self.runner.run("git", &push_args, &self.prepared.root)?;
        if pushed.exit_code != Some(0) {
            return Err(GraphError::ReleaseCommand {
                program: "git".to_string(),
                args: push_args.iter().map(ToString::to_string).collect(),
                failure: CommandFailure::NonZeroExit {
                    exit_code: pushed.exit_code,
                    stderr: pushed.stderr,
                },
            });
        }
        if self
            .observed_tag(name)?
            .is_some_and(|observed| observed.target == *target && observed.annotation == annotation)
        {
            Ok(OperationOutcome::Published)
        } else {
            Err(GraphError::ReleaseRemoteConflict {
                conflict: RemoteConflict::TagNotObservedAfterPush,
            })
        }
    }

    fn dispatch_forge_release(&self, tag: &TagName) -> Result<OperationOutcome, GraphError> {
        let remote = self.checked_git_remote()?;
        let repository = remote.github_repository.as_slug();
        match self.observed_forge_release_target(tag, &repository)? {
            ForgeReleaseObservation::Exact => return Ok(OperationOutcome::AlreadySatisfied),
            ForgeReleaseObservation::Conflict => {
                return Err(GraphError::ReleaseRemoteConflict {
                    conflict: RemoteConflict::ForgeReleaseDiffers,
                })
            }
            ForgeReleaseObservation::Missing => {}
        }
        let create_args = [
            "release",
            "create",
            tag.as_str(),
            "--repo",
            repository.as_str(),
            "--verify-tag",
            "--generate-notes",
        ];
        let created = self.runner.run("gh", &create_args, &self.prepared.root)?;
        if created.exit_code != Some(0) {
            return Err(GraphError::ReleaseCommand {
                program: "gh".to_string(),
                args: create_args.iter().map(ToString::to_string).collect(),
                failure: CommandFailure::NonZeroExit {
                    exit_code: created.exit_code,
                    stderr: created.stderr,
                },
            });
        }
        if self.observed_forge_release_target(tag, &repository)? == ForgeReleaseObservation::Exact {
            Ok(OperationOutcome::Published)
        } else {
            Err(GraphError::ReleaseRemoteConflict {
                conflict: RemoteConflict::ForgeReleaseNotObservedAfterCreate,
            })
        }
    }

    fn observed_tag(&self, name: &TagName) -> Result<Option<ObservedTag>, GraphError> {
        let reference = format!("refs/tags/{name}^{{commit}}");
        let rev_parse_args = ["rev-parse", "--verify", "--quiet", reference.as_str()];
        let observed = self.runner.run("git", &rev_parse_args, &self.prepared.root)?;
        if observed.exit_code != Some(0) {
            return Ok(None);
        }
        let target = CommitSha::parse(observed.stdout.trim()).map_err(|error| GraphError::ReleaseCommand {
            program: "git".to_string(),
            args: rev_parse_args.iter().map(ToString::to_string).collect(),
            failure: CommandFailure::MalformedOutput {
                detail: error.to_string(),
            },
        })?;
        let for_each_ref_target = format!("refs/tags/{name}");
        let for_each_ref_args = [
            "for-each-ref",
            "--format=%(objecttype)%00%(contents:subject)%00%(contents:body)",
            for_each_ref_target.as_str(),
        ];
        let details = self.runner.run("git", &for_each_ref_args, &self.prepared.root)?;
        if details.exit_code != Some(0) {
            return Err(GraphError::ReleaseCommand {
                program: "git".to_string(),
                args: for_each_ref_args.iter().map(ToString::to_string).collect(),
                failure: CommandFailure::NonZeroExit {
                    exit_code: details.exit_code,
                    stderr: details.stderr,
                },
            });
        }
        let line = details.stdout.trim_end_matches(['\r', '\n']);
        let mut fields = line.split('\0');
        let object_type = fields.next();
        let annotation = fields.next();
        let body = fields.next();
        if object_type != Some("tag") || body.is_none_or(|body| !body.trim().is_empty()) || fields.next().is_some() {
            return Err(GraphError::ReleaseCommand {
                program: "git".to_string(),
                args: for_each_ref_args.iter().map(ToString::to_string).collect(),
                failure: CommandFailure::MalformedOutput {
                    detail: format!("unexpected for-each-ref output: {line:?}"),
                },
            });
        }
        repository: destination.forge_repository().clone(),
    };
    operations.insert(
        publish_id.clone(),
        ReleaseOperation::new(publish_id.clone(), upload_ids)?,
    );
    prepared.insert(
        publish_id,
        PreparedOperation::ForgePublish {
            repository: destination.forge_repository().clone(),
            tag: tag_name,
        },
    );

    let operations = canonical_operation_order(operations)?;
    let intent = ReleaseIntent::new(
        decision.clone(),
        release,
        source,
        destination,
        approved,
        operations,
        slots,
    )?;
    let intent_ids = intent
        .operations()
        .iter()
        .map(|operation| operation.id().clone())
        .collect::<BTreeSet<_>>();
    if intent_ids != prepared.keys().cloned().collect() {
        return Err(GraphError::ReleaseInvariant {
            detail: "prepared operation map does not exactly match the derived intent".to_string(),
        });
    }
    Ok(PreparedDerivation {
        intent,
        operations: prepared,
        git_remote,
    })
}

fn registry_artifact_files(
    package: &ReleasePackageId,
    version: &Version,
) -> Result<Vec<(RegistryArtifactFormat, String)>, GraphError> {
    let version = version.render();
    match package.ecosystem() {
        Ecosystem::Cargo => Ok(vec![(
            RegistryArtifactFormat::CargoCrate,
            format!("{}-{version}.crate", package.name()),
        )]),
        Ecosystem::Npm => Ok(vec![(
            RegistryArtifactFormat::NpmTarball,
            format!(
                "{}-{version}.tgz",
                package.name().trim_start_matches('@').replace('/', "-")
            ),
        )]),
        Ecosystem::Pypi => Err(GraphError::ReleaseInvariant {
            detail: format!(
                "PyPI release artifact names for `{package}` require exact graph-owned distribution descriptors; wheel tags must not be guessed"
            ),
        }),
        _ => Err(GraphError::UnsupportedRelease {
            feature: UnsupportedReleaseFeature::Ecosystem,
        }),
    }
}

fn package_dir(package: &callisto_model::Package) -> Result<std::path::PathBuf, GraphError> {
    package
        .canonical_manifests()
        .next()
        .and_then(|manifest| manifest.path.parent())
        .map(std::path::Path::to_path_buf)
        .ok_or_else(|| GraphError::ReleaseInvariant {
            detail: format!("selected release package `{}` has no canonical manifest", package.id),
        })
}

fn canonical_operation_order(
    operations: BTreeMap<ReleaseOperationId, ReleaseOperation>,
) -> Result<Vec<ReleaseOperation>, GraphError> {
    let mut remaining: BTreeMap<_, usize> = operations
        .iter()
        .map(|(id, operation)| (id.clone(), operation.prerequisites().len()))
        .collect();
    let mut dependents = BTreeMap::<ReleaseOperationId, Vec<ReleaseOperationId>>::new();
    for (id, operation) in &operations {
        for prerequisite in operation.prerequisites() {
            dependents.entry(prerequisite.clone()).or_default().push(id.clone());
        }
    }
    let mut ready: BTreeSet<_> = remaining
        .iter()
        .filter_map(|(id, count)| (*count == 0).then_some(id.clone()))
        .collect();
    let mut ordered = Vec::with_capacity(operations.len());
    while let Some(id) = ready.pop_first() {
        ordered.push(operations.get(&id).expect("known operation").clone());
        for dependent in dependents.get(&id).into_iter().flatten() {
            let count = remaining.get_mut(dependent).expect("known operation");
            *count -= 1;
            if *count == 0 {
                ready.insert(dependent.clone());
            }
        }
    }
    if ordered.len() != operations.len() {
        return Err(GraphError::ReleaseInvariant {
            detail: "release operation DAG contains a cycle: topological sort could not order every operation"
                .to_string(),
        });
    }
    Ok(ordered)
}

impl PreparedRegistryBinding {
    fn id(&self) -> Result<RegistryBindingId, GraphError> {
        RegistryBindingId::new(self.key.as_str(), self.identity.clone()).map_err(GraphError::from)
    }
}

fn prepared_registry_binding(
    config: &crate::config::ResolvedConfig,
    profile_name: &str,
    ecosystem: Ecosystem,
) -> Result<PreparedRegistryBinding, GraphError> {
    let (key, endpoints) = config.release_registry(profile_name, ecosystem)?;
    let (prepared, transcript_fields): (PreparedRegistryEndpoints, Vec<(&str, &str)>) = match endpoints {
        crate::config::RegistryEndpoints::Cargo { index, api } => (
            PreparedRegistryEndpoints::Cargo {
                index: index.clone(),
                api: api.clone(),
            },
            vec![("cargo.index", index), ("cargo.api", api)],
        ),
        crate::config::RegistryEndpoints::Npm { registry } => (
            PreparedRegistryEndpoints::Npm {
                registry: registry.clone(),
            },
            vec![("npm.registry", registry)],
        ),
        crate::config::RegistryEndpoints::Pypi {
            upload,
            metadata,
            simple,
        } => (
            PreparedRegistryEndpoints::Pypi {
                upload: upload.clone(),
                metadata: metadata.clone(),
                simple: simple.clone(),
            },
            vec![
                ("pypi.upload", upload),
                ("pypi.metadata", metadata),
                ("pypi.simple", simple),
            ],
        ),
    };
    let mut transcript = CanonicalTranscript::semantic_input_v1();
    transcript.push_str("registry.key", key.as_str());
    for (field, value) in transcript_fields {
        transcript.push_str(field, value);
    }
    Ok(PreparedRegistryBinding {
        key: key.clone(),
        endpoints: prepared,
        identity: RegistryBindingDigest::from_normalized_binding(transcript.as_bytes()),
        credential: prepared_credential_policy(ecosystem, key)?,
    })
}

fn prepared_credential_policy(
    ecosystem: Ecosystem,
    key: &RegistryKey,
) -> Result<PreparedCredentialEnvPolicy, GraphError> {
    let normalized_key = key
        .as_str()
        .bytes()
        .map(|byte| match byte {
            b'a'..=b'z' => (byte - b'a' + b'A') as char,
            b'A'..=b'Z' | b'0'..=b'9' => byte as char,
            b'-' | b'_' => '_',
            _ => '\0',
        })
        .collect::<String>();
    if normalized_key.is_empty() || normalized_key.contains('\0') {
        return Err(GraphError::ReleaseInvariant {
            detail: format!("registry key `{key}` cannot form a safe credential environment name"),
        });
    }
    match ecosystem {
        Ecosystem::Cargo => Ok(PreparedCredentialEnvPolicy::CargoToken {
            env_name: if matches!(key.as_str(), "crates-io" | RegistryKey::CRATES_IO) {
                "CARGO_REGISTRY_TOKEN".to_string()
            } else {
                format!("CARGO_REGISTRIES_{normalized_key}_TOKEN")
            },
        }),
        Ecosystem::Npm => Ok(PreparedCredentialEnvPolicy::NpmToken { env_name: "NPM_TOKEN" }),
        Ecosystem::Pypi => Ok(PreparedCredentialEnvPolicy::PypiToken {
            password_env_name: "TWINE_PASSWORD",
            username: "__token__",
        }),
        _ => Err(GraphError::UnsupportedRelease {
            feature: UnsupportedReleaseFeature::Ecosystem,
        }),
    }
}

/// Maps a `url::ParseError` to a specific, static diagnostic reason for
/// [`GraphError::UnsafeRegistryBinding`]/[`GraphError::UnsafeGitRemote`],
/// rather than discarding it behind one generic "invalid URL" message.
fn url_parse_error_reason(error: url::ParseError) -> &'static str {
    match error {
        url::ParseError::RelativeUrlWithoutBase => "URL has no scheme (e.g. missing `https://`)",
        url::ParseError::EmptyHost => "URL host is empty",
        url::ParseError::InvalidPort => "URL port is invalid",
        url::ParseError::InvalidIpv4Address | url::ParseError::InvalidIpv6Address => {
            "URL host is not a valid IP address"
        }
        url::ParseError::InvalidDomainCharacter => "URL host contains an invalid character",
        url::ParseError::Overflow => "URL exceeds the maximum length",
        _ => "invalid URL",
    }
}

/// Maps a [`GitHubRepositoryParseError`] to a specific, static diagnostic
/// reason for [`GraphError::UnsafeGitRemote`], rather than discarding it
/// behind one generic message for every distinct parse failure.
fn github_repository_parse_error_reason(error: &GitHubRepositoryParseError) -> &'static str {
    match error {
        GitHubRepositoryParseError::MissingSeparator { .. } => "GitHub remote path must be in owner/repo form",
        GitHubRepositoryParseError::TooManyParts { .. } => "GitHub remote path has more than one `/`",
        GitHubRepositoryParseError::InvalidOwner { .. } => "GitHub owner name is invalid",
        GitHubRepositoryParseError::InvalidRepo { .. } => "GitHub repository name is invalid",
        #[allow(unreachable_patterns)]
        _ => "GitHub owner or repository name is invalid",
    }
}

fn prepared_git_remote(root: &Path, runner: &dyn CommandRunner) -> Result<PreparedGitRemote, GraphError> {
    let output = runner.run("git", &["remote", "get-url", "--push", "origin"], root)?;
    if output.exit_code != Some(0) {
        return Err(GraphError::UnsafeGitRemote {
            reason: "origin must have a push URL",
        });
    }
    canonical_git_remote(output.stdout.trim())
}

fn canonical_git_remote(raw: &str) -> Result<PreparedGitRemote, GraphError> {
    let ssh_url = if raw.starts_with("git@") && !raw.contains("//") {
        let (host, path) =
            raw.strip_prefix("git@")
                .and_then(|value| value.split_once(':'))
                .ok_or(GraphError::UnsafeGitRemote {
                    reason: "invalid SSH remote syntax",
                })?;
        format!("ssh://git@{host}/{path}")
    } else {
        raw.to_string()
    };
    let parsed = url::Url::parse(&ssh_url).map_err(|error| GraphError::UnsafeGitRemote {
        reason: url_parse_error_reason(error),
    })?;
    if parsed.cannot_be_a_base() || parsed.host_str().is_none() {
        return Err(GraphError::UnsafeGitRemote {
            reason: "URL must have an authority",
        });
    }
    if !matches!(parsed.scheme(), "https" | "ssh") {
        return Err(GraphError::UnsafeGitRemote {
            reason: "URL scheme must be HTTPS or SSH",
        });
    }
    if parsed.password().is_some() || parsed.query().is_some() || parsed.fragment().is_some() {
        return Err(GraphError::UnsafeGitRemote {
            reason: "credentials, query strings, and fragments are forbidden",
        });
    }
    if parsed.scheme() == "https" && !parsed.username().is_empty() {
        return Err(GraphError::UnsafeGitRemote {
            reason: "HTTPS userinfo is forbidden",
        });
    }
    if parsed.scheme() == "ssh" && parsed.username() != "git" {
        return Err(GraphError::UnsafeGitRemote {
            reason: "SSH remotes must use the git account",
        });
    }
    let host = parsed.host_str().expect("validated authority").to_ascii_lowercase();
    let mut components = parsed.path_segments().ok_or(GraphError::UnsafeGitRemote {
        reason: "remote path is invalid",
    })?;
    let owner = components
        .next()
        .filter(|value| !value.is_empty())
        .ok_or(GraphError::UnsafeGitRemote {
            reason: "remote path must name an owner and repository",
        })?;
    let repository = components
        .next()
        .filter(|value| !value.is_empty())
        .ok_or(GraphError::UnsafeGitRemote {
            reason: "remote path must name an owner and repository",
        })?;
    if components.next().is_some() || owner == "." || owner == ".." || repository == "." || repository == ".." {
        return Err(GraphError::UnsafeGitRemote {
            reason: "remote path must contain exactly an owner and repository",
        });
    }
    let repository = repository.strip_suffix(".git").unwrap_or(repository);
    if repository.is_empty() {
        return Err(GraphError::UnsafeGitRemote {
            reason: "repository name is empty",
        });
    }
    let port = parsed.port_or_known_default();
    let port_text = match (parsed.scheme(), port) {
        ("https", Some(443)) | ("ssh", Some(22)) | (_, None) => String::new(),
        (_, Some(port)) => format!(":{port}"),
    };
    let endpoint = match parsed.scheme() {
        "https" => format!("https://{host}{port_text}/{owner}/{repository}.git"),
        "https" => format!("https://{host}{port_text}/{owner}/{repository}.git"),
        "ssh" => format!("ssh://git@{host}{port_text}/{owner}/{repository}.git"),
        _ => unreachable!("scheme checked above"),
    };
    let mut transcript = CanonicalTranscript::semantic_input_v1();
    transcript.push_str("gitRemote.scheme", parsed.scheme());
    transcript.push_str("gitRemote.host", &host);
    transcript.push_str(
        "gitRemote.port",
        &port.map_or_else(String::new, |port| port.to_string()),
    );
    transcript.push_str("gitRemote.owner", owner);
    transcript.push_str("gitRemote.repository", repository);
    if host != "github.com" {
        return Err(GraphError::UnsafeGitRemote {
            reason: "release forge remote must be hosted on github.com",
        });
    }
    let github_repository =
        GitHubRepository::parse(&format!("{owner}/{repository}")).map_err(|error| GraphError::UnsafeGitRemote {
            reason: github_repository_parse_error_reason(&error),
        })?;
    Ok(PreparedGitRemote {
        remote_name: "origin",
        endpoint,
        identity: callisto_model::SemanticInputDigest::from_transcript(&transcript),
        github_repository,
    })
}

#[cfg(test)]
mod tests {
    use super::*;
    use callisto_model::{CommandError, CommandOutput, Ecosystem, VersionGrammar};
    use std::sync::atomic::{AtomicUsize, Ordering};
    use std::time::Duration;

    /// Regression coverage for the confirmed bug: a successful npm publish
    /// whose registry hasn't caught up yet must report `RegistryPublishUnconfirmed`
    /// -- not the unrelated `ReleaseIntentStale`, whose "no release operation
    /// was authorized" help text is false here (an operation WAS authorized
    /// and did run).
    #[test]
    fn require_registry_confirmation_rejects_unconfirmed_publish_with_its_own_variant() {
        let version = Version::parse("1.2.3", VersionGrammar::SemVer).unwrap();
        let err = require_registry_confirmation(false, "left-pad", &version).unwrap_err();
        match err {
            GraphError::RegistryPublishUnconfirmed { package, version: v } => {
                assert_eq!(package, "left-pad");
                assert_eq!(v, version);
            }
            other => panic!("expected RegistryPublishUnconfirmed, got {other:?}"),
        }
        assert!(
            !matches!(
                require_registry_confirmation(false, "left-pad", &version),
                Err(GraphError::ReleaseIntentStale { .. })
            ),
            "must not be reported as ReleaseIntentStale -- that help text would be false here"
        );
    }

    #[test]
    fn require_registry_confirmation_accepts_a_confirmed_publish() {
        let version = Version::parse("1.2.3", VersionGrammar::SemVer).unwrap();
        assert!(require_registry_confirmation(true, "left-pad", &version).is_ok());
    }

    /// Regression coverage for the confirmed bug: a Cargo publish was never
    /// confirmed against the registry at all, unlike npm's existing check.
    /// This is the exact function `dispatch_registry` gates on, so this
    /// test fails if Cargo's confirmation is ever silently dropped again.
    #[test]
    fn ecosystem_requires_registry_confirmation_covers_npm_and_cargo_only() {
        assert!(ecosystem_requires_registry_confirmation(Ecosystem::Cargo));
        assert!(ecosystem_requires_registry_confirmation(Ecosystem::Npm));
        assert!(
            !ecosystem_requires_registry_confirmation(Ecosystem::Pypi),
            "PyPI's identical gap is deliberately deferred, not silently fixed"
        );
    }

    #[test]
    fn poll_until_published_succeeds_immediately_without_sleeping() {
        let sleeps = std::cell::RefCell::new(Vec::new());
        let result = poll_until_published(
            || Ok(true),
            REGISTRY_CONFIRMATION_MAX_RETRIES,
            registry_confirmation_backoff,
            |d| sleeps.borrow_mut().push(d),
        );
        assert_eq!(result, Ok(true));
        assert!(sleeps.borrow().is_empty(), "must not sleep when already published");
    }

    #[test]
    fn poll_until_published_succeeds_on_a_later_retry() {
        let attempts = std::cell::RefCell::new(0);
        let sleeps = std::cell::RefCell::new(Vec::new());
        let result = poll_until_published(
            || {
                *attempts.borrow_mut() += 1;
                Ok(*attempts.borrow() == 3)
            },
            REGISTRY_CONFIRMATION_MAX_RETRIES,
            registry_confirmation_backoff,
            |d| sleeps.borrow_mut().push(d),
        );
        assert_eq!(result, Ok(true));
        assert_eq!(*attempts.borrow(), 3);
        assert_eq!(
            *sleeps.borrow(),
            vec![Duration::from_secs(2), Duration::from_secs(4)],
            "must sleep with the exponential schedule between the two failed checks"
        );
    }

    #[test]
    fn poll_until_published_gives_up_after_max_retries_with_no_trailing_sleep() {
        let attempts = std::cell::RefCell::new(0);
        let sleeps = std::cell::RefCell::new(Vec::new());
        let result = poll_until_published(
            || {
                *attempts.borrow_mut() += 1;
                Ok(false)
            },
            REGISTRY_CONFIRMATION_MAX_RETRIES,
            registry_confirmation_backoff,
            |d| sleeps.borrow_mut().push(d),
        );
        assert_eq!(result, Ok(false));
        assert_eq!(*attempts.borrow(), 4, "one initial check plus 3 retries");
        assert_eq!(
            *sleeps.borrow(),
            vec![Duration::from_secs(2), Duration::from_secs(4), Duration::from_secs(8)],
            "must not sleep again after the final (4th) check fails"
        );
    }

    #[test]
    fn poll_until_published_propagates_a_check_error_without_retrying() {
        let attempts = std::cell::RefCell::new(0);
        let version = Version::parse("1.2.3", VersionGrammar::SemVer).unwrap();
        let result = poll_until_published(
            || {
                *attempts.borrow_mut() += 1;
                Err(GraphError::RegistryPublishUnconfirmed {
                    package: "left-pad".to_string(),
                    version: version.clone(),
                })
            },
            REGISTRY_CONFIRMATION_MAX_RETRIES,
            registry_confirmation_backoff,
            |_| panic!("must not sleep after a hard error"),
        );
        assert!(result.is_err());
        assert_eq!(*attempts.borrow(), 1, "a check error must not be retried");
    }

    struct RealGitRunner;
    impl CommandRunner for RealGitRunner {
        fn run(&self, program: &str, args: &[&str], cwd: &Path) -> Result<CommandOutput, CommandError> {
            let output = std::process::Command::new(program)
                .args(args)
                .current_dir(cwd)
                .output()
                .map_err(|error| CommandError::Io {
                    program: program.to_string(),
                    message: error.to_string(),
                })?;
            Ok(CommandOutput {
                exit_code: output.status.code(),
                stdout: String::from_utf8_lossy(&output.stdout).into_owned(),
                stderr: String::from_utf8_lossy(&output.stderr).into_owned(),
            })
        }
    }

    /// The locator is the release authority boundary: malformed membership
    /// must stop intent construction before source observation can invoke Git
    /// (and therefore before a later execution path could reach credentials
    /// or a provider). The child package makes this a real discoverable-member
    /// case rather than a root-only parse failure.
    #[test]
    fn malformed_root_membership_stops_intent_before_any_command_or_decision() {
        struct CountingRunner(AtomicUsize);

        impl CommandRunner for CountingRunner {
            fn run(&self, program: &str, _args: &[&str], _cwd: &Path) -> Result<CommandOutput, CommandError> {
                self.0.fetch_add(1, Ordering::SeqCst);
                Err(CommandError::Io {
                    program: program.to_owned(),
                    message: "membership failure must happen before any command".to_owned(),
                })
            }
        }

        let dir = tempfile::tempdir().unwrap();
        let root = dir.path();
        std::fs::write(root.join("Cargo.toml"), "[workspace]\nmembers = [\"").unwrap();
        std::fs::create_dir_all(root.join("crates/discoverable")).unwrap();
        std::fs::write(
            root.join("crates/discoverable/Cargo.toml"),
            "[package]\nname = \"discoverable\"\nversion = \"1.0.0\"\n",
        )
        .unwrap();

        let runner = CountingRunner(AtomicUsize::new(0));
        let locator = crate::IgnoreWalkLocator::new(root);
        let decision = ReleaseDecisionV1::new(vec![callisto_model::ReleaseDecisionEntry {
            package: ReleasePackageId::new(Ecosystem::Cargo, "discoverable").unwrap(),
            target_version: Version::parse("1.0.0", VersionGrammar::SemVer).unwrap(),
            reasons: vec![callisto_model::ReleaseInclusionReason::ExplicitSelection],
        }])
        .unwrap();
        let result = build_release_intent(root, &locator, &runner, &decision, "production");

        assert!(matches!(
            result,
            Err(GraphError::Locate(crate::LocateError::MembershipParse { .. }))
        ));
        assert_eq!(
            runner.0.load(Ordering::SeqCst),
            0,
            "malformed membership must fail before Git/source observation, decision derivation, or any provider-capable command"
        );
    }

    fn fixture() -> (tempfile::TempDir, RealGitRunner) {
        let dir = tempfile::tempdir().unwrap();
        std::fs::write(
            dir.path().join("Cargo.toml"),
