/// One exact, immutable PyPI distribution expected from a release build.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ReleaseArtifactDescriptor {
    format: RegistryArtifactFormat,
    file_name_template: String,
}

impl ReleaseArtifactDescriptor {
    pub fn format(&self) -> RegistryArtifactFormat {
        self.format
    }

    /// Renders and revalidates the exact distribution basename for one
    /// coordinated product version. `None` prevents an unexpectedly long or
    /// otherwise unsafe SemVer rendering from becoming provider authority.
    pub fn file_name_for(&self, version: &callisto_model::Version) -> Option<String> {
        let rendered = self.file_name_template.replace("{version}", version.render());
        release_artifact_file_name_is_safe(&rendered, self.format).then_some(rendered)
    }
}

