    #[derive(Clone, Debug, PartialEq, Eq, Hash, Serialize, Deserialize, JsonSchema)]
    #[serde(
        rename_all = "camelCase",
        rename_all_fields = "camelCase",
        tag = "kind",
        deny_unknown_fields
    )]
    pub enum RegistryPublicationPolicy {
        Cargo,
        Npm { access: NpmAccess, dist_tag: NpmDistTag },
        Pypi,
    }

    impl PartialOrd for RegistryPublicationPolicy {
        fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
            Some(self.cmp(other))
        }
    }

    impl Ord for RegistryPublicationPolicy {
        fn cmp(&self, other: &Self) -> Ordering {
            fn key(policy: &RegistryPublicationPolicy) -> (u8, u8, &str) {
                match policy {
                    RegistryPublicationPolicy::Cargo => (0, 0, ""),
                    RegistryPublicationPolicy::Npm { access, dist_tag } => (
                        1,
                        match access {
                            NpmAccess::Public => 0,
                            NpmAccess::Restricted => 1,
                        },
                        dist_tag.as_str(),
                    ),
                    RegistryPublicationPolicy::Pypi => (2, 0, ""),
                }
            }
            key(self).cmp(&key(other))
        }
    }

    impl RegistryPublicationPolicy {
        pub const fn cargo() -> Self {
            Self::Cargo
        }

        pub fn npm(access: NpmAccess, dist_tag: impl AsRef<str>) -> Result<Self, SuccessorError> {
            Ok(Self::Npm {
                access,
                dist_tag: NpmDistTag::parse(dist_tag)?,
            })
        }

        pub const fn pypi() -> Self {
            Self::Pypi
        }
