        std::fs::write(
            dir.path().join(".changeset/release.md"),
            "---\nrelease-fixture: patch\n---\n\nRelease fixture.\n",
        )
        .unwrap();
        std::fs::write(
            dir.path().join("callisto.toml"),
            release_config(
                "[[package]]\nmatch = \"release-fixture\"\nchangelog = \"CHANGELOG.md\"\npublish-to = [\"crates-io\"]\n",
            ),
        )
        .unwrap();
        for args in [
            ["init", "-q"].as_slice(),
            ["config", "user.email", "test@example.com"].as_slice(),
            ["config", "user.name", "Test"].as_slice(),
            ["config", "commit.gpgsign", "false"].as_slice(),
            [
                "remote",
                "add",
                "origin",
                "https://github.com/example/release-fixture.git",
            ]
            .as_slice(),
            ["add", "."].as_slice(),
            ["commit", "-q", "-m", "base"].as_slice(),

item.aggregated_output:
        });
    }
    Ok(intent)
