        let Some(observed) = distributions.get(slot.file_name()) else {
            missing.insert(MissingWork::RegistryArtifact(slot));
            continue;
        };
        let Some((expected_digest, expected_length)) = expectations.artifact(&slot) else {
            return OperationObservation::Unverifiable(ObservationFailure::Capability {
                provider: ObservationProvider::ArtifactCapability,
            });
        };
        if observed.byte_length != expected_length {
            return OperationObservation::Conflict(ExternalConflict::RegistryLength {
                slot,
                observed: observed.byte_length,
            });
        }
        if &observed.digest != expected_digest {
            return OperationObservation::Conflict(ExternalConflict::RegistryDigest {
                slot,
                observed: observed.digest.clone(),
            });
        }
        exact.push(ReleaseObservationEvidence::registry_artifact(
            package.clone(),
            version.clone(),
            registry.clone(),
            slot,
            expected_digest.clone(),
            expected_length,
        ));
    }
    if missing.is_empty() {
        let evidence = exact
            .into_iter()
            .find(|evidence| matches!(evidence, ReleaseObservationEvidence::RegistryArtifact { slot, .. } if slot == current_slot))
            .expect("validated PyPI roster includes the current operation slot");
        OperationObservation::Exact(evidence)
    } else if exact.is_empty() {
        OperationObservation::Absent
    } else {
        OperationObservation::Incomplete(VerifiedPartialEvidence::new(exact, missing))
    }
}

fn observe_forge_prepare(
    session: &mut ObservationSession,
    artifacts: &ValidatedArtifactManifest<'_, '_>,
    validated: &ValidatedReleaseIntent<'_>,
    release: &ProductReleaseId,
    repository: &GitHubRepository,
    tag: &TagName,
) -> OperationObservation {
    if let Some(failure) = require_exact_remote_tag(artifacts, validated) {
        return failure;
    }
    match github_release(session, validated, repository, tag) {
        Ok(None) => OperationObservation::Absent,
        Ok(Some(observed)) if !observed.tag_matches => {
            OperationObservation::Conflict(ExternalConflict::ForgeReleaseTag)
        }
        Ok(Some(observed)) => OperationObservation::Exact(ReleaseObservationEvidence::forge_prepare(
            release.clone(),
            if observed.draft {
                ForgePrepareLifecycle::Draft
            } else {
                ForgePrepareLifecycle::PublishedSuccessor
            },
        )),
        Err(failure) => OperationObservation::Unverifiable(failure),
    }
}

fn observe_forge_asset(
    session: &mut ObservationSession,
    artifacts: &ValidatedArtifactManifest<'_, '_>,
    validated: &ValidatedReleaseIntent<'_>,
    release: &ProductReleaseId,
    slot: &ReleaseArtifactSlot,
) -> OperationObservation {
    if let Some(failure) = require_exact_remote_tag(artifacts, validated) {
        return failure;
    }
    let repository = validated.intent().destination().forge_repository();
    let tag = release.tag();
    let Ok(tag) = TagName::parse(&tag) else {
        return malformed(ObservationProvider::PreparedCapability);
    };
    let observed = match github_release(session, validated, repository, &tag) {
        Ok(Some(observed)) => observed,
        Ok(None) => return OperationObservation::Absent,
        Err(failure) => return OperationObservation::Unverifiable(failure),
    };
    if !observed.tag_matches {
        return OperationObservation::Conflict(ExternalConflict::ForgeReleaseTag);
    }
    let Some(asset) = observed.assets.get(slot.file_name()) else {
        return OperationObservation::Absent;
    };
    compare_forge_asset(artifacts, release, slot, asset)
}

fn observe_forge_publish(
    session: &mut ObservationSession,
    artifacts: &ValidatedArtifactManifest<'_, '_>,
    validated: &ValidatedReleaseIntent<'_>,
    release: &ProductReleaseId,
    repository: &GitHubRepository,
    tag: &TagName,
) -> OperationObservation {
    if let Some(failure) = require_exact_remote_tag(artifacts, validated) {
        return failure;
    }
    let observed = match github_release(session, validated, repository, tag) {
        Ok(Some(observed)) => observed,
        Ok(None) => return OperationObservation::Absent,
        Err(failure) => return OperationObservation::Unverifiable(failure),
    };
    if !observed.tag_matches {
        return OperationObservation::Conflict(ExternalConflict::ForgeReleaseTag);
    }
    let expected_slots = validated
        .intent()
        .slots()
        .iter()
        .filter(|slot| slot.release() == Some(release))
        .cloned()
        .collect::<Vec<_>>();
    let expected_names = expected_slots
        .iter()
        .map(|slot| slot.file_name().to_string())
        .collect::<BTreeSet<_>>();
    if let Some(file_name) = observed.assets.keys().find(|name| !expected_names.contains(*name)) {
        return OperationObservation::Conflict(ExternalConflict::UnexpectedForgeAsset {
            file_name: file_name.clone(),
        });
    }
    let mut exact = Vec::new();
    let mut missing = BTreeSet::new();
    for slot in expected_slots {
        let Some(asset) = observed.assets.get(slot.file_name()) else {
            missing.insert(MissingWork::ForgeAsset(slot));
            continue;
        };
        match compare_forge_asset(artifacts, release, &slot, asset) {
            OperationObservation::Exact(evidence) => exact.push(evidence),
            other => return other,
        }
    }
    if observed.draft {
        missing.insert(MissingWork::PublishForgeRelease(release.clone()));
        return OperationObservation::Incomplete(VerifiedPartialEvidence::new(exact, missing));
    }
    if !missing.is_empty() {
        return OperationObservation::Conflict(ExternalConflict::PublishedReleaseIncomplete {
            release: release.clone(),
        });
    }
    OperationObservation::Exact(ReleaseObservationEvidence::forge_publish(
        release.clone(),
        artifacts.expectations().asset_roster_digest().clone(),
    ))
}

fn compare_forge_asset(
    artifacts: &ValidatedArtifactManifest<'_, '_>,
    release: &ProductReleaseId,
    slot: &ReleaseArtifactSlot,
    observed: &GitHubAsset,
) -> OperationObservation {
    let expectations = artifacts.expectations();
    let Some((expected_digest, expected_length)) = expectations.artifact(slot) else {
        return OperationObservation::Unverifiable(ObservationFailure::Capability {
            provider: ObservationProvider::ArtifactCapability,
        });
    };
    if observed.byte_length != expected_length {
        return OperationObservation::Conflict(ExternalConflict::ForgeAssetLength {
            slot: slot.clone(),
            observed: observed.byte_length,
        });
    }
    let Some(observed_digest) = &observed.digest else {
        return OperationObservation::Unverifiable(ObservationFailure::MissingDigest {
            provider: ObservationProvider::GitHub,
            file_name: slot.file_name().to_string(),
        });
    };
    if observed_digest != expected_digest {
        return OperationObservation::Conflict(ExternalConflict::ForgeAssetDigest {
            slot: slot.clone(),
            observed: observed_digest.clone(),
        });
    }
    OperationObservation::Exact(ReleaseObservationEvidence::forge_asset(
        release.clone(),
        slot.clone(),
        expected_digest.clone(),
        expected_length,
    ))
}

fn require_exact_remote_tag(
    artifacts: &ValidatedArtifactManifest<'_, '_>,
    validated: &ValidatedReleaseIntent<'_>,
) -> Option<OperationObservation> {
    let Some(operation) = validated
        .intent()
        .operations()
        .iter()
        .find(|operation| matches!(operation.id(), ReleaseOperationId::ProductTag { .. }))
    else {
        return Some(OperationObservation::Unverifiable(ObservationFailure::Capability {
            provider: ObservationProvider::PreparedCapability,
        }));
    };
    match validated.prepared_operation(operation.id()) {
        Some(PreparedOperationView::ProductTag {
            name,
            target,
            annotation,
            remote_name,
            ..
        }) => match operation.id() {
            ReleaseOperationId::ProductTag { release, .. } => {
                match observe_tag(artifacts, validated, release, name, target, annotation, remote_name) {
                    OperationObservation::Exact(_) => None,
                    OperationObservation::Absent => Some(OperationObservation::Conflict(
                        ExternalConflict::RemoteTagMissingForForge,
                    )),
                    other => Some(other),
                }
            }
            _ => unreachable!("product-tag predicate returned another operation"),
        },
        _ => Some(OperationObservation::Unverifiable(ObservationFailure::Capability {
            provider: ObservationProvider::PreparedCapability,
        })),
    }
}

fn github_release(
    session: &mut ObservationSession,
    validated: &ValidatedReleaseIntent<'_>,
    repository: &GitHubRepository,
    tag: &TagName,
) -> CachedObservation<GitHubRelease> {
    let key = (repository.as_slug(), tag.as_str().to_string());
    session
        .github_releases
        .entry(key)
        .or_insert_with(|| fetch_github_release(validated, repository, tag))
        .clone()
}

fn fetch_github_release(
    validated: &ValidatedReleaseIntent<'_>,
    repository: &GitHubRepository,
    tag: &TagName,
) -> CachedObservation<GitHubRelease> {
    let endpoint = format!("repos/{}/releases/tags/{}", repository.as_slug(), tag.as_str());
    let args = ["api", "--include", "--method", "GET", endpoint.as_str()];
    let output = validated
        .runner()
        .run_quiet("gh", &args, validated.root(), OBSERVATION_TIMEOUT)
        .map_err(|_| ObservationFailure::Command {
            provider: ObservationProvider::GitHub,
        })?;
    let (status, body) = parse_http_response(&output).ok_or(ObservationFailure::MalformedResponse {
        provider: ObservationProvider::GitHub,
    })?;
    if status == 404 {
    if status == 404 {
        return Ok(None);
    }
    if status != 200 || !output.success() {
        return Err(ObservationFailure::HttpStatus {
            provider: ObservationProvider::GitHub,
            status,
        });
    }
    let value: serde_json::Value = serde_json::from_str(body).map_err(|_| ObservationFailure::MalformedResponse {
        provider: ObservationProvider::GitHub,
    })?;
    let tag_matches = value.get("tag_name").and_then(serde_json::Value::as_str) == Some(tag.as_str());
    let draft =
        value
            .get("draft")
            .and_then(serde_json::Value::as_bool)
            .ok_or(ObservationFailure::MalformedResponse {
                provider: ObservationProvider::GitHub,
            })?;
    let assets = parse_github_assets(value.get("assets")).ok_or(ObservationFailure::MalformedResponse {
        provider: ObservationProvider::GitHub,
    })?;
    Ok(Some(GitHubRelease {
        tag_matches,
        draft,
        assets,
    }))
}

fn parse_github_assets(value: Option<&serde_json::Value>) -> Option<BTreeMap<String, GitHubAsset>> {
    let mut parsed = BTreeMap::new();
    for asset in value?.as_array()? {
        let name = asset.get("name")?.as_str()?.to_string();
        let byte_length = asset.get("size")?.as_u64()?;
        let digest = match asset.get("digest") {
            Some(serde_json::Value::String(raw)) => {
                let raw = raw.strip_prefix("sha256:")?;
                Some(ArtifactDigest::parse(raw).ok()?)
            }
            Some(serde_json::Value::Null) | None => None,
            _ => return None,
        };
        if parsed.insert(name, GitHubAsset { digest, byte_length }).is_some() {
            return None;
        }
    }
    Some(parsed)
}

fn fetch_pypi_version(
    validated: &ValidatedReleaseIntent<'_>,
    metadata_endpoint: &str,
    package: &str,
    version: &Version,
) -> CachedObservation<BTreeMap<String, PypiDistribution>> {
    let url = append_url_segments(metadata_endpoint, &[package, &version.render(), "json"]).ok_or(
        ObservationFailure::MalformedResponse {
            provider: ObservationProvider::Pypi,
        },
    )?;
    let Some(value) = observe_json_http(validated.runner(), validated.root(), &url, ObservationProvider::Pypi)? else {
        return Ok(None);
    };
    let urls =
        value
            .get("urls")
            .and_then(serde_json::Value::as_array)
            .ok_or(ObservationFailure::MalformedResponse {
                provider: ObservationProvider::Pypi,
            })?;
    let mut distributions = BTreeMap::new();
    for file in urls {
        let file_name = file
            .get("filename")
            .and_then(serde_json::Value::as_str)
            .ok_or(ObservationFailure::MalformedResponse {
                provider: ObservationProvider::Pypi,
            })?
            .to_string();
        let byte_length =
            file.get("size")
                .and_then(serde_json::Value::as_u64)
                .ok_or(ObservationFailure::MalformedResponse {
                    provider: ObservationProvider::Pypi,
                })?;
        let digest = file
            .get("digests")
            .and_then(|digests| digests.get("sha256"))
            .and_then(serde_json::Value::as_str)
            .and_then(|raw| ArtifactDigest::parse(raw).ok())
            .ok_or_else(|| ObservationFailure::MissingDigest {
                provider: ObservationProvider::Pypi,
                file_name: file_name.clone(),
            })?;
        if distributions
            .insert(file_name, PypiDistribution { digest, byte_length })
            .is_some()
        {
            return Err(ObservationFailure::MalformedResponse {
                provider: ObservationProvider::Pypi,
            });
        }
    }
    Ok(Some(distributions))
}

fn observe_npm_bytes(
    validated: &ValidatedReleaseIntent<'_>,
    package: &str,
    version: &Version,
    registry: &str,
) -> Result<Option<Vec<u8>>, ObservationFailure> {
    let directory = tempfile::tempdir().map_err(|_| ObservationFailure::Capability {
        provider: ObservationProvider::Npm,
    })?;
    let spec = format!("{package}@{}", version.render());
    let destination = directory.path().to_string_lossy();
    let args = [
        "pack",
        spec.as_str(),
        "--json",
        "--ignore-scripts",
        "--pack-destination",
        destination.as_ref(),
        "--registry",
        registry,
    ];
    let output = validated
        .runner()
        .run_quiet("npm", &args, validated.root(), OBSERVATION_TIMEOUT)
        .map_err(|_| ObservationFailure::Command {
            provider: ObservationProvider::Npm,
        })?;
    if !output.success() {
        let lower = format!("{}\n{}", output.stdout, output.stderr).to_ascii_lowercase();
        if lower.contains("e404") || lower.contains("etarget") || lower.contains("no matching version") {
            return Ok(None);
        }
        return Err(ObservationFailure::Command {
            provider: ObservationProvider::Npm,
        });
    }
    let value: serde_json::Value =
        serde_json::from_str(&output.stdout).map_err(|_| ObservationFailure::MalformedResponse {
            provider: ObservationProvider::Npm,
        })?;
    let entries = value.as_array().ok_or(ObservationFailure::MalformedResponse {
        provider: ObservationProvider::Npm,
    })?;
    if entries.len() != 1 {
        return Err(ObservationFailure::MalformedResponse {
            provider: ObservationProvider::Npm,
        });
    }
    let file_name = entries[0].get("filename").and_then(serde_json::Value::as_str).ok_or(
        ObservationFailure::MalformedResponse {
            provider: ObservationProvider::Npm,
        },
    )?;
    if Path::new(file_name).components().count() != 1 {
        return Err(ObservationFailure::MalformedResponse {
            provider: ObservationProvider::Npm,
        });
    }
    std::fs::read(directory.path().join(file_name))
        .map(Some)
        .map_err(|_| ObservationFailure::MalformedResponse {
            provider: ObservationProvider::Npm,
        })
}

fn observe_json_http(
    runner: &dyn callisto_model::CommandRunner,
    root: &Path,
    url: &str,
    provider: ObservationProvider,
) -> Result<Option<serde_json::Value>, ObservationFailure> {
    let args = [
        "--silent",
        "--show-error",
        "--location",
        "--include",
        "--request",
        "GET",
        url,
    ];
    let output = runner
        .run_quiet("curl", &args, root, OBSERVATION_TIMEOUT)
        .map_err(|_| ObservationFailure::Command { provider })?;
    if !output.success() {
        return Err(ObservationFailure::Command { provider });
    }
    let (status, body) = parse_http_response(&output).ok_or(ObservationFailure::MalformedResponse { provider })?;
    if status == 404 {
        return Ok(None);
    }
    if status != 200 {
        return Err(ObservationFailure::HttpStatus { provider, status });
    }
    serde_json::from_str(body)
        .map(Some)
        .map_err(|_| ObservationFailure::MalformedResponse { provider })
}

fn parse_http_response(output: &CommandOutput) -> Option<(u16, &str)> {
    parse_http_stream(&output.stdout).or_else(|| parse_http_stream(&output.stderr))
}

fn parse_http_stream(stream: &str) -> Option<(u16, &str)> {
    let (headers, body) = stream.rsplit_once("\r\n\r\n").or_else(|| stream.rsplit_once("\n\n"))?;
    let status = headers
        .lines()
        .rev()
        .find(|line| line.trim_end_matches('\r').starts_with("HTTP/"))?
        .split_whitespace()
        .nth(1)?
        .parse()
        .ok()?;
    Some((status, body))
}

fn cargo_metadata_url(endpoint: &str, package: &str, version: &Version) -> Option<String> {
    let mut url = url::Url::parse(endpoint).ok()?;
    if url.path_segments()?.next_back() != Some("new") {
        return None;
    }
    let rendered_version = version.render();
    {
        let mut segments = url.path_segments_mut().ok()?;
        segments.pop_if_empty();
        segments.pop();
        segments.extend([package, rendered_version]);
    }
    Some(url.to_string())
}

fn append_url_segments(base: &str, segments: &[&str]) -> Option<String> {
    let mut url = url::Url::parse(base).ok()?;
    {
        let mut path = url.path_segments_mut().ok()?;
        path.pop_if_empty();
        path.extend(segments.iter().copied());
    }
    Some(url.to_string())
}

fn malformed(provider: ObservationProvider) -> OperationObservation {
    OperationObservation::Unverifiable(ObservationFailure::MalformedResponse { provider })
}

