    #[test]
    fn prepared_capability_retains_exact_tag_and_registry_inputs() {
        let (dir, runner) = fixture();
        let state_dir = tempfile::tempdir().unwrap();
        let locator = crate::IgnoreWalkLocator::new(dir.path());
        let intent = build_release_intent(dir.path(), &locator, &runner, &decision(), "production").unwrap();
        let validated =
            validate_release_intent_with_state_directory(dir.path(), &locator, &runner, Some(state_dir.path()), intent)
                .unwrap();
        let inputs = validated.prepared();
        assert!(inputs.root.is_absolute());
        assert_eq!(inputs.source.as_str().len(), 40);
        assert_eq!(inputs.git_remote.remote_name, "origin");
        assert_eq!(
            inputs.git_remote.github_repository,
            GitHubRepository::parse("example/release-fixture").unwrap()
        );

        let intent = validated.intent();
        let counts = intent.operations().iter().fold([0_usize; 5], |mut counts, operation| {
            let index = match operation.id() {
                ReleaseOperationId::RegistryArtifactPublish { .. } => 0,
                ReleaseOperationId::ProductTag { .. } => 1,
                ReleaseOperationId::ForgePrepare { .. } => 2,
                ReleaseOperationId::ArtifactUpload { .. } => 3,
                ReleaseOperationId::ForgePublish { .. } => 4,
            };
            counts[index] += 1;
            counts
        });
        assert_eq!(counts, [1, 1, 1, 6, 1]);
        assert_eq!(inputs.operations.len(), intent.operations().len());
        assert_eq!(
            intent
                .slots()
                .iter()
                .filter_map(ReleaseArtifactSlot::product_target)
                .collect::<BTreeSet<_>>(),
            ProductTarget::ALL.into_iter().collect()
        );
        assert_eq!(intent.product_release().tag(), "release-fixture@1.2.3");

        let tag = inputs
            .operations
            .values()
            .find_map(|operation| match operation {
                PreparedOperation::ProductTag {
                    name,
                    target,
                    annotation,
                    ..
                } => Some((name, target, annotation)),
                _ => None,
            })
            .expect("the tag operation must retain its render, target, and annotation policy");
        assert_eq!(tag.0.as_str(), "release-fixture@1.2.3");
        assert_eq!(tag.2, "Release release-fixture@1.2.3");
        assert_eq!(tag.1.as_str().len(), 40);

        let registry = inputs
            .operations
            .values()
            .find_map(|operation| match operation {
                PreparedOperation::RegistryArtifactPublish {
                    package_dir,
                    artifact,
                    registry,
                } => Some((package_dir, artifact, registry)),
                _ => None,
            })
            .expect("the publish operation must retain its exact routing input");
        assert_eq!(registry.0, &std::path::PathBuf::new());
        assert_eq!(registry.1.package().name(), "release-fixture");
        assert_eq!(registry.1.file_name(), "release-fixture-1.2.3.crate");
        assert_eq!(registry.2.key.as_str(), "cargo");
        assert!(matches!(registry.2.endpoints, PreparedRegistryEndpoints::Cargo { .. }));
    }

