//! Fresh, graph-owned authorization for durable release intents.
//!
//! This module intentionally takes a root, locator, and runner rather than a
//! [`Workspace`]. A workspace caches parsed manifests and config for a normal
//! command invocation; accepting one here would make a previously observed
//! graph look current after the filesystem changed.

use std::collections::{BTreeMap, BTreeSet};
use std::path::Path;

use callisto_model::{
    ApplyPermit, ApprovedRegistryArtifact, CanonicalTranscript, CommandRunner, CommitSha, Ecosystem, GitHubRepository,
    GitHubRepositoryParseError, NpmAccess, OperationOutcome, ProductName, ProductReleaseId, ProductTarget,
    RegistryArtifactFormat, RegistryBindingDigest, RegistryBindingId, RegistryKey, RegistryPublicationPolicy,
    ReleaseArtifactSlot, ReleaseDecisionV1, ReleaseDestinationBinding, ReleaseDestinationKind, ReleaseIntent,
    ReleaseOperation, ReleaseOperationId, ReleasePackageId, TagName, Version,
};
use callisto_vcs::{
    access::{GitCommitTrustEvidence, GitHeadDisposition},
    release_lock::ReleaseWorkspaceLock,
    GitDataSource, TagSignPolicy,
};

use crate::error::{
    CommandFailure, ReleasePreconditionRequirement, ReleaseSelectionInvalidReason, UnsupportedReleaseFeature,
};
use crate::{commands::registry_argv, DependencyResolver, GraphError, ProjectLocator, Workspace};

use super::{
    registry_artifacts::{cargo_upload_body, CargoAuthorizationHeader, PrivateArtifactFile},
    release_artifacts::ValidatedArtifactManifest,
    release_observation::{observe_prepared, MissingWork, ObservationSession, OperationObservation},
};

const PROVIDER_EFFECT_TIMEOUT: std::time::Duration = std::time::Duration::from_secs(300);

/// Reason carried by [`GraphError::ReleaseIntentStale`] (E124); real reasons are constructible only from this module.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct StaleReason {
    kind: StaleKind,
}

#[derive(Clone, Debug, PartialEq, Eq, thiserror::Error)]
enum StaleKind {
    #[error("the re-observed Git commit trust evidence no longer matches what the intent was validated against")]
    TrustEvidenceChanged,
    #[error("the re-observed source identity no longer matches what the intent was validated against")]
    SourceIdentityChanged,
    #[error("the re-observed Git push remote no longer matches what the intent was validated against")]
    GitRemoteChanged,
    #[error("a fresh derivation from the current workspace no longer matches the intent that was validated")]
    IntentDiffersFromFreshDerivation,
}

impl std::fmt::Display for StaleReason {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        std::fmt::Display::fmt(&self.kind, formatter)
    }
}

impl StaleReason {
    fn trust_evidence_changed() -> Self {
        StaleReason {
            kind: StaleKind::TrustEvidenceChanged,
        }
    }

    fn source_identity_changed() -> Self {
        StaleReason {
            kind: StaleKind::SourceIdentityChanged,
        }
    }

    fn git_remote_changed() -> Self {
        StaleReason {
            kind: StaleKind::GitRemoteChanged,
        }
    }

    fn intent_differs_from_fresh_derivation() -> Self {
        StaleReason {
            kind: StaleKind::IntentDiffersFromFreshDerivation,
        }
    }
}

/// The invocation data for one effect. This is deliberately graph-private:
/// callers can inspect the serializable intent, but cannot substitute a new
/// endpoint, tag target, or package directory at execution time.
#[allow(dead_code)] // consumed by the durable executor batch
#[derive(Debug)]
enum PreparedOperation {
    RegistryArtifactPublish {
        artifact: ApprovedRegistryArtifact,
        registry: PreparedRegistryBinding,
        npm_client: Option<registry_argv::NpmPackageManager>,
    },
    ProductTag {
        name: TagName,
        target: CommitSha,
        annotation: String,
        remote: PreparedGitRemote,
    },
    ForgePrepare {
        repository: GitHubRepository,
        tag: TagName,
    },
    ArtifactUpload {
        slot: ReleaseArtifactSlot,
    },
    ForgePublish {
        repository: GitHubRepository,
        tag: TagName,
    },
}

/// Credential-free, canonical registry routing. `endpoint` is populated only
/// after parsing rejects userinfo, query, and fragments, so a later executor
/// cannot recover credentials from this capability.
#[allow(dead_code)] // consumed by the durable executor batch
#[derive(Clone, Debug, PartialEq, Eq)]
struct PreparedRegistryBinding {
    key: RegistryKey,
    endpoints: PreparedRegistryEndpoints,
    identity: RegistryBindingDigest,
    credential: PreparedCredentialEnvPolicy,
}

#[derive(Clone, Debug, PartialEq, Eq)]
enum PreparedCredentialEnvPolicy {
    CargoToken {
        env_name: String,
    },
    NpmToken {
        env_name: &'static str,
    },
    PypiToken {
        password_env_name: &'static str,
        username: &'static str,
    },
}

#[allow(dead_code)]
#[derive(Clone, Debug, PartialEq, Eq)]
enum PreparedRegistryEndpoints {
    Cargo {
        index: String,
        api: String,
    },
    Npm {
        registry: String,
    },
    Pypi {
        upload: String,
        metadata: String,
        simple: String,
    },
}

/// Read-only, graph-internal view of typed, credential-free registry routing.
#[derive(Clone, Copy, Debug)]
pub(super) enum PreparedRegistryEndpointsView<'a> {
    Cargo {
        index: &'a str,
        api: &'a str,
    },
    Npm {
        registry: &'a str,
    },
    Pypi {
        upload: &'a str,
        metadata: &'a str,
        simple: &'a str,
    },
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(super) enum PreparedCredentialEnvPolicyView<'a> {
    CargoToken {
        env_name: &'a str,
    },
    NpmToken {
        env_name: &'static str,
    },
    PypiToken {
        password_env_name: &'static str,
        username: &'static str,
    },
}

/// The exact prepared capability paired with one immutable operation.
///
/// This view is crate-private and non-serializable. It exposes only canonical,
/// credential-free identities needed by the observer/dispatcher boundary.
#[derive(Clone, Copy, Debug)]
pub(super) enum PreparedOperationView<'a> {
    RegistryArtifactPublish {
        artifact: &'a ApprovedRegistryArtifact,
        registry_key: &'a RegistryKey,
        binding_digest: &'a RegistryBindingDigest,
        endpoints: PreparedRegistryEndpointsView<'a>,
        credential: PreparedCredentialEnvPolicyView<'a>,
    },
    ProductTag {
        name: &'a TagName,
        target: &'a CommitSha,
        annotation: &'a str,
        remote_name: &'static str,
        repository: &'a GitHubRepository,
    },
    ForgePrepare {
        repository: &'a GitHubRepository,
        tag: &'a TagName,
    },
    ArtifactUpload {
        slot: &'a ReleaseArtifactSlot,
    },
    ForgePublish {
        repository: &'a GitHubRepository,
        tag: &'a TagName,
    },
}

/// Immutable, credential-free destination for Git effects. Its canonical
/// digest is included in each tag-producing package fingerprint; the URL is
/// retained only in the validated, non-serializable capability.
#[derive(Clone, Debug, PartialEq, Eq)]
struct PreparedGitRemote {
    remote_name: &'static str,
    endpoint: String,
    identity: callisto_model::SemanticInputDigest,
    github_repository: GitHubRepository,
}

/// Graph-private inputs prepared from the same fresh observation as an intent.
/// The executor will consume these when introduced; retaining them in the
/// capability prevents a validated public intent being paired with new inputs.
#[allow(dead_code)] // consumed by the durable executor batch
#[derive(Debug)]
struct PreparedReleaseInputs {
    root: std::path::PathBuf,
    source: CommitSha,
    trust: GitCommitTrustEvidence,
    git_remote: PreparedGitRemote,
    _lock: ReleaseWorkspaceLock,
    operations: BTreeMap<ReleaseOperationId, PreparedOperation>,
}

struct PreparedDerivation {
    intent: ReleaseIntent,
    operations: BTreeMap<ReleaseOperationId, PreparedOperation>,
    git_remote: PreparedGitRemote,
}

/// In-memory, non-transferable proof that an intent was rebuilt from a fresh
/// workspace observation. It is intentionally neither cloneable nor serializable.
pub struct ValidatedReleaseIntent<'a> {
    intent: ReleaseIntent,
    prepared: PreparedReleaseInputs,
    #[allow(dead_code)] // consumed by the durable execution coordinator
    runner: &'a dyn CommandRunner,
}

impl std::fmt::Debug for ValidatedReleaseIntent<'_> {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        formatter
            .debug_struct("ValidatedReleaseIntent")
            .field("intent", &self.intent)
            .finish_non_exhaustive()
    }
}

impl ValidatedReleaseIntent<'_> {
    pub fn intent(&self) -> &ReleaseIntent {
        &self.intent
    }

    #[allow(dead_code)] // consumed by the durable executor batch
    fn prepared(&self) -> &PreparedReleaseInputs {
        &self.prepared
    }

    pub(super) fn runner(&self) -> &dyn CommandRunner {
        self.runner
    }

    pub(super) fn root(&self) -> &Path {
        &self.prepared.root
    }

    pub(super) fn prepared_operation(&self, id: &ReleaseOperationId) -> Option<PreparedOperationView<'_>> {
        self.prepared.operations.get(id).map(|operation| match operation {
            PreparedOperation::RegistryArtifactPublish { artifact, registry, .. } => {
                PreparedOperationView::RegistryArtifactPublish {
                    artifact,
                    registry_key: &registry.key,
                    binding_digest: &registry.identity,
                    endpoints: match &registry.endpoints {
                        PreparedRegistryEndpoints::Cargo { index, api } => {
                            PreparedRegistryEndpointsView::Cargo { index, api }
                        }
                        PreparedRegistryEndpoints::Npm { registry } => PreparedRegistryEndpointsView::Npm { registry },
                        PreparedRegistryEndpoints::Pypi {
                            upload,
                            metadata,
                            simple,
                        } => PreparedRegistryEndpointsView::Pypi {
                            upload,
                            metadata,
                            simple,
                        },
                    },
                    credential: match &registry.credential {
                        PreparedCredentialEnvPolicy::CargoToken { env_name } => {
                            PreparedCredentialEnvPolicyView::CargoToken { env_name }
                        }
                        PreparedCredentialEnvPolicy::NpmToken { env_name } => {
                            PreparedCredentialEnvPolicyView::NpmToken { env_name }
                        }
                        PreparedCredentialEnvPolicy::PypiToken {
                            password_env_name,
                            username,
                        } => PreparedCredentialEnvPolicyView::PypiToken {
                            password_env_name,
                            username,
                        },
                    },
                }
            }
            PreparedOperation::ProductTag {
                name,
                target,
                annotation,
                remote,
            } => PreparedOperationView::ProductTag {
                name,
                target,
                annotation,
                remote_name: remote.remote_name,
                repository: &remote.github_repository,
            },
            PreparedOperation::ForgePrepare { repository, tag } => {
                PreparedOperationView::ForgePrepare { repository, tag }
            }
            PreparedOperation::ArtifactUpload { slot } => PreparedOperationView::ArtifactUpload { slot },
            PreparedOperation::ForgePublish { repository, tag } => {
                PreparedOperationView::ForgePublish { repository, tag }
            }
        })
    }

    /// Re-observes the held workspace immediately before an effect.
    #[allow(dead_code)] // consumed by the durable execution coordinator
    pub(crate) fn recheck_trust(&self) -> Result<(), GraphError> {
        let evidence =
            callisto_vcs::GitAccess::discover(&self.prepared.root, self.runner).observe_git_commit_trust()?;
        if evidence != self.prepared.trust || evidence.head() != &self.prepared.source {
            return Err(GraphError::ReleaseIntentStale {
                reason: StaleReason::trust_evidence_changed(),
            });
        }
        if prepared_git_remote(&self.prepared.root, self.runner).as_ref() != Ok(&self.prepared.git_remote) {
            return Err(GraphError::ReleaseIntentStale {
                reason: StaleReason::git_remote_changed(),
            });
        }
        Ok(())
    }
}

/// Builds a release intent from a fresh root-bound observation.
pub fn build_release_intent<L: ProjectLocator, R: CommandRunner>(
    root: &Path,
    locator: &L,
    runner: &R,
    decision: &ReleaseDecisionV1,
    profile_name: &str,
) -> Result<ReleaseIntent, GraphError> {
    let root = canonical_root(root)?;
    let workspace = Workspace::load(root.clone(), locator, runner)?;
    let source = observe_source(&workspace)?;
    let intent = derive_product_release(&workspace, decision, source.clone(), profile_name)?.intent;

    // Recheck after all input reads. A concurrent edit or checkout cannot be
    // authorized merely because it happened after the first check.
    if observe_source(&workspace)? != source {
        return Err(GraphError::ReleaseIntentStale {
            reason: StaleReason::source_identity_changed(),
        });
    }
    Ok(intent)
}

/// Re-observes root, config, package discovery, manifests, Git evidence, and
/// the exact operation DAG before creating an opaque authorization capability.
pub fn validate_release_intent<'a, L: ProjectLocator, R: CommandRunner>(
    root: &Path,
    locator: &L,
    runner: &'a R,
    received: ReleaseIntent,
) -> Result<ValidatedReleaseIntent<'a>, GraphError> {
    validate_release_intent_with_state_directory(root, locator, runner, None, received)
}

/// Validates an intent while placing its workspace lock under an explicit
/// caller-owned state directory.
///
/// CI callers that supply an explicit durable state file must use its parent
/// here as well.  Otherwise validation would still depend on the runner's
/// implicit platform state location, defeating hermetic job handoff.
pub fn validate_release_intent_with_state_directory<'a, L: ProjectLocator, R: CommandRunner>(
    root: &Path,
    locator: &L,
    runner: &'a R,
    state_directory: Option<&Path>,
    received: ReleaseIntent,
) -> Result<ValidatedReleaseIntent<'a>, GraphError> {
    let root = canonical_root(root)?;
    let workspace = Workspace::load(root.clone(), locator, runner)?;
    let initial_trust = observe_git_trust(&workspace)?;
    let lock = ReleaseWorkspaceLock::acquire(&root, state_directory)?;
    let trust = observe_git_trust(&workspace)?;
    if trust != initial_trust {
        return Err(GraphError::ReleaseIntentStale {
            reason: StaleReason::trust_evidence_changed(),
        });
    }
    let source = trust.head().clone();
    let approved_decision = super::release_decision::derive_release_commit_decision(
        &workspace,
        received.source_commit(),
        Path::new(super::release_decision::CANONICAL_RELEASE_DECISION_PATH),
    )?;
    if &approved_decision != received.decision() {
        return Err(GraphError::ReleaseIntentStale {
            reason: StaleReason::intent_differs_from_fresh_derivation(),
        });
    }
    let prepared = derive_product_release(
        &workspace,
        &approved_decision,
        source.clone(),
        received.destination().profile_name(),
    )?;
    let final_trust = observe_git_trust(&workspace)?;
    if prepared.intent != received || final_trust != trust {
        return Err(GraphError::ReleaseIntentStale {
            reason: StaleReason::intent_differs_from_fresh_derivation(),
        });
    }

    Ok(ValidatedReleaseIntent {
        prepared: PreparedReleaseInputs {
            root,
            source,
            trust: final_trust,
            git_remote: prepared.git_remote,
            _lock: lock,
            operations: prepared.operations,
        },
        intent: received,
        runner,
    })
}

fn canonical_root(root: &Path) -> Result<std::path::PathBuf, GraphError> {
    dunce::canonicalize(root).map_err(|error| GraphError::ReleaseInputRead {
        path: root.to_path_buf(),
        message: error.to_string(),
    })
}

fn observe_source<R: CommandRunner, D: DependencyResolver>(
    workspace: &Workspace<'_, R, D>,
) -> Result<CommitSha, GraphError> {
    Ok(observe_git_trust(workspace)?.head().clone())
}

fn observe_git_trust<R: CommandRunner, D: DependencyResolver>(
    workspace: &Workspace<'_, R, D>,
) -> Result<GitCommitTrustEvidence, GraphError> {
    let evidence = workspace.git_access().observe_git_commit_trust()?;
    if evidence.canonical_root() != workspace.root {
        return Err(GraphError::ReleasePreconditionUnmet {
            requirement: ReleasePreconditionRequirement::CanonicalRootMatchesWorkspace,
        });
    }
    if evidence.head_disposition() != GitHeadDisposition::Detached {
        return Err(GraphError::ReleasePreconditionUnmet {
            requirement: ReleasePreconditionRequirement::DetachedHead,
        });
    }
    Ok(evidence)
}

impl ValidatedReleaseIntent<'_> {
    /// Dispatches exactly one graph-private operation prepared during fresh
    /// validation. This is intentionally the only production effect path: it
    /// never accepts a path, endpoint, tag, package name, or version from a
    /// caller.
    pub(crate) fn dispatch_prepared(
        &self,
        artifacts: &ValidatedArtifactManifest<'_, '_>,
        observations: &mut ObservationSession,
        permit: &ApplyPermit,
        id: &ReleaseOperationId,
    ) -> Result<OperationOutcome, GraphError> {
        let operation = self
            .prepared
            .operations
            .get(id)
            .ok_or_else(|| GraphError::ReleaseInvariant {
                detail: format!("dispatch_prepared: no prepared operation for `{id:?}`"),
            })?;
        let observed = observe_prepared(observations, artifacts, id);
        if operation_is_satisfied(id, &observed) {
            return Ok(OperationOutcome::AlreadySatisfied);
        }
        ensure_operation_is_missing(id, &observed)?;
        self.recheck_trust()?;
        match operation {
            PreparedOperation::RegistryArtifactPublish {
                artifact,
                registry,
                npm_client,
            } => self.dispatch_registry_artifact(artifacts, id, artifact, registry, *npm_client)?,
            PreparedOperation::ProductTag {
                name,
                target,
                annotation,
                remote,
            } => self.dispatch_product_tag(permit, name, target, annotation, remote)?,
            PreparedOperation::ForgePrepare { repository, tag } => self.dispatch_forge_prepare(repository, tag)?,
            PreparedOperation::ArtifactUpload { slot } => self.dispatch_forge_asset(artifacts, slot)?,
            PreparedOperation::ForgePublish { repository, tag } => self.dispatch_forge_publish(repository, tag)?,
        }
        observations.invalidate_after_effect();
        self.recheck_trust()?;
        let after = observe_prepared(observations, artifacts, id);
        if operation_is_satisfied(id, &after) {
            Ok(OperationOutcome::Published)
        } else {
            Err(observation_error(id, &after))
        }
    }
}

impl ValidatedReleaseIntent<'_> {
    fn dispatch_registry_artifact(
        &self,
        artifacts: &ValidatedArtifactManifest<'_, '_>,
        id: &ReleaseOperationId,
        artifact: &ApprovedRegistryArtifact,
        registry: &PreparedRegistryBinding,
        npm_client: Option<registry_argv::NpmPackageManager>,
    ) -> Result<(), GraphError> {
        let ReleaseOperationId::RegistryArtifactPublish {
            package, version, slot, ..
        } = id
        else {
            return Err(GraphError::ReleaseInvariant {
                detail: "registry capability paired with a non-registry operation".to_string(),
            });
        };
        if artifact.package() != package || artifact.file_name() != slot.file_name() {
            return Err(GraphError::ReleaseInvariant {
                detail: "prepared registry artifact differs from its operation slot".to_string(),
            });
        }
        let snapshot = artifacts.snapshot(slot)?;
        match (
            artifact.format(),
            artifact.publication_policy(),
            &registry.endpoints,
            &registry.credential,
        ) {
            (
                RegistryArtifactFormat::CargoCrate,
                RegistryPublicationPolicy::Cargo,
                PreparedRegistryEndpoints::Cargo { api, .. },
                PreparedCredentialEnvPolicy::CargoToken { env_name },
            ) => {
                let body = cargo_upload_body(snapshot.bytes(), package, version)?;
                let header = CargoAuthorizationHeader::from_env(env_name)?;
                let header_argument = format!("@{}", header.path().to_string_lossy());
                let args = [
                    "--silent",
                    "--show-error",
                    "--fail-with-body",
                    "--max-time",
                    "300",
                    "--request",
                    "PUT",
                    "--header",
                    "Content-Type: application/octet-stream",
                    "--header",
                    "Accept: application/json",
                    "--header",
                    header_argument.as_str(),
                    "--data-binary",
                    "@-",
                    api.as_str(),
                ];
                let output = self.runner.run_with_stdin_timeout(
                    "curl",
                    &args,
                    &self.prepared.root,
                    &body,
                    PROVIDER_EFFECT_TIMEOUT,
                )?;
                require_command_success("curl", &args, output)
            }
            (
                RegistryArtifactFormat::NpmTarball,
                RegistryPublicationPolicy::Npm { access, dist_tag },
                PreparedRegistryEndpoints::Npm { registry: endpoint },
                PreparedCredentialEnvPolicy::NpmToken { env_name },
            ) => {
                let private = PrivateArtifactFile::new(slot.file_name(), snapshot.bytes())?;
                private.write_npm_config(endpoint, env_name)?;
                let client = npm_client.ok_or_else(|| GraphError::ReleaseInvariant {
                    detail: "npm artifact has no prepared package-manager capability".to_string(),
                })?;
                let argv = registry_argv::npm_tarball_publish_argv(
                    private.path(),
                    client,
                    dist_tag.as_str(),
                    *access,
                    endpoint,
                );
                let args = argv.args.iter().map(String::as_str).collect::<Vec<_>>();
                let output =
                    self.runner
                        .run_with_timeout(&argv.program, &args, private.directory(), PROVIDER_EFFECT_TIMEOUT)?;
                require_command_success(&argv.program, &args, output)
            }
            (
                RegistryArtifactFormat::PythonWheel | RegistryArtifactFormat::PythonSdist,
                RegistryPublicationPolicy::Pypi,
                PreparedRegistryEndpoints::Pypi { upload, .. },
                PreparedCredentialEnvPolicy::PypiToken {
                    password_env_name,
                    username,
                },
            ) => {
                if std::env::var(password_env_name).is_err() {
                    return Err(GraphError::ReleasePreconditionUnmet {
                        requirement: ReleasePreconditionRequirement::RegistryCredential,
                    });
                }
                let private = PrivateArtifactFile::new(slot.file_name(), snapshot.bytes())?;
                let path = private.path().to_string_lossy();
                let args = [
                    "upload",
                    "--non-interactive",
                    "--username",
                    *username,
                    "--repository-url",
                    upload.as_str(),
                    path.as_ref(),
                ];
                let output =
                    self.runner
                        .run_with_timeout("twine", &args, private.directory(), PROVIDER_EFFECT_TIMEOUT)?;
                require_command_success("twine", &args, output)
            }
            _ => Err(GraphError::ReleaseInvariant {
                detail: "registry artifact format, policy, endpoints, and credential capability disagree".to_string(),
            }),
        }
    }

    fn dispatch_product_tag(
        &self,
        permit: &ApplyPermit,
        name: &TagName,
        target: &CommitSha,
        annotation: &str,
        remote: &PreparedGitRemote,
    ) -> Result<(), GraphError> {
        if remote.remote_name != "origin" || *remote != self.prepared.git_remote {
            return Err(GraphError::ReleaseInvariant {
                detail: "tag operation is not bound to the validated fixed origin".to_string(),
            });
        }
        callisto_vcs::GitAccess::discover(&self.prepared.root, self.runner).create_tag(
            name.as_str(),
            target,
            Some(annotation),
            TagSignPolicy::ForceUnsigned,
            permit,
        )?;
        let reference = format!("refs/tags/{name}:refs/tags/{name}");
        let args = ["push", remote.remote_name, reference.as_str()];
        let output = self.runner.run("git", &args, &self.prepared.root)?;
        require_command_success("git", &args, output)
    }

    fn dispatch_forge_prepare(&self, repository: &GitHubRepository, tag: &TagName) -> Result<(), GraphError> {
        let repository = repository.as_slug();
        let title = tag.as_str();
        let args = [
            "release",
            "create",
            tag.as_str(),
            "--repo",
            repository.as_str(),
            "--verify-tag",
            "--draft",
            "--title",
            title,
            "--notes",
            "",
        ];
        let output = self
            .runner
            .run_with_timeout("gh", &args, &self.prepared.root, PROVIDER_EFFECT_TIMEOUT)?;
        require_command_success("gh", &args, output)
    }

    fn dispatch_forge_asset(
        &self,
        artifacts: &ValidatedArtifactManifest<'_, '_>,
        slot: &ReleaseArtifactSlot,
    ) -> Result<(), GraphError> {
        let snapshot = artifacts.snapshot(slot)?;
        let private = PrivateArtifactFile::new(slot.file_name(), snapshot.bytes())?;
        let tag = self.intent.product_release().tag();
        let repository = self.intent.destination().forge_repository().as_slug();
        let path = private.path().to_string_lossy();
        let args = [
            "release",
            "upload",
            tag.as_str(),
            path.as_ref(),
            "--repo",
            repository.as_str(),
        ];
        let output = self
            .runner
            .run_with_timeout("gh", &args, private.directory(), PROVIDER_EFFECT_TIMEOUT)?;
        require_command_success("gh", &args, output)
    }

    fn dispatch_forge_publish(&self, repository: &GitHubRepository, tag: &TagName) -> Result<(), GraphError> {
        let repository = repository.as_slug();
        let args = [
            "release",
            "edit",
            tag.as_str(),
            "--repo",
            repository.as_str(),
            "--verify-tag",
            "--draft=false",
        ];
        let output = self
            .runner
            .run_with_timeout("gh", &args, &self.prepared.root, PROVIDER_EFFECT_TIMEOUT)?;
        require_command_success("gh", &args, output)
    }

item.stdout:
    }
}

fn operation_is_satisfied(id: &ReleaseOperationId, observed: &OperationObservation) -> bool {
    match observed {
        OperationObservation::Exact(_) => true,
        OperationObservation::Incomplete(partial) => match id {
            ReleaseOperationId::RegistryArtifactPublish { slot, .. } => {
                !partial.missing().contains(&MissingWork::RegistryArtifact(slot.clone()))
            }
            _ => false,
        },
        _ => false,
    }
}

fn ensure_operation_is_missing(id: &ReleaseOperationId, observed: &OperationObservation) -> Result<(), GraphError> {
    match observed {
        OperationObservation::Absent
            if matches!(
                id,
                ReleaseOperationId::RegistryArtifactPublish { .. }
                    | ReleaseOperationId::ProductTag { .. }
                    | ReleaseOperationId::ForgePrepare { .. }
                    | ReleaseOperationId::ArtifactUpload { .. }
            ) =>
        {
            Ok(())
        }
        OperationObservation::Incomplete(partial) => match id {
            ReleaseOperationId::RegistryArtifactPublish { slot, .. }
                if partial.missing().contains(&MissingWork::RegistryArtifact(slot.clone())) =>
            {
                Ok(())
            }
            ReleaseOperationId::ForgePublish { release, .. }
                if partial.missing().len() == 1
                    && partial
                        .missing()
                        .contains(&MissingWork::PublishForgeRelease(release.clone())) =>
            {
                Ok(())
            }
            _ => Err(GraphError::ReleaseOperationNotMissing { operation: id.clone() }),
        },
        OperationObservation::Conflict(_) => Err(GraphError::ReleaseObservationConflict { operation: id.clone() }),
        OperationObservation::Unverifiable(_) => {
            Err(GraphError::ReleaseObservationUnverifiable { operation: id.clone() })
        }
        _ => Err(GraphError::ReleaseOperationNotMissing { operation: id.clone() }),
    }
}

fn observation_error(id: &ReleaseOperationId, observed: &OperationObservation) -> GraphError {
    match observed {
        OperationObservation::Conflict(_) => GraphError::ReleaseObservationConflict { operation: id.clone() },
        OperationObservation::Unverifiable(_) => GraphError::ReleaseObservationUnverifiable { operation: id.clone() },
        _ => GraphError::ReleaseOperationNotMissing { operation: id.clone() },
    }
}

fn require_command_success(
    program: &str,
    args: &[&str],
    output: callisto_model::CommandOutput,
) -> Result<(), GraphError> {
    if output.success() {
        Ok(())
    } else {
        Err(GraphError::ReleaseCommand {
            program: program.to_string(),
            args: args.iter().map(ToString::to_string).collect(),
            failure: CommandFailure::NonZeroExit {
                exit_code: output.exit_code,
                stderr: output.redacted_stderr(),
            },
        })
    }
}

fn derive_product_release<R: CommandRunner, D: DependencyResolver>(
    workspace: &Workspace<'_, R, D>,
    decision: &ReleaseDecisionV1,
    source: CommitSha,
    profile_name: &str,
) -> Result<PreparedDerivation, GraphError> {
    super::release_decision::validate_release_units(workspace, decision)?;
    let mut selected = BTreeMap::new();
    for package in workspace.graph.packages() {
        if !crate::config::is_release_unit(&workspace.config, &package.id)? {
            continue;
        }
        for id in super::release_decision::release_package_ids(package)?
            .into_iter()
            .collect::<BTreeSet<_>>()
        {
            if let Some(entry) = decision.entries.iter().find(|entry| entry.package == id) {
                selected.insert(id.clone(), (package, entry.target_version.clone()));
            }
        }
    }
    for entry in &decision.entries {
        let id = &entry.package;
        if !selected.contains_key(id) {
            return Err(GraphError::ReleasePackageNotSelected { package: id.clone() });
        }
    }

    let (product, profile) = workspace.config.release_profile(profile_name)?;
    let release = ProductReleaseId::from_coordinated_versions(
        ProductName::parse(&product.name)?,
        decision.entries.iter().map(|entry| entry.target_version.clone()),
    )?;
    let destination_kind = match profile.kind {
        crate::config::ReleaseProfileKind::Production => ReleaseDestinationKind::Production,
        crate::config::ReleaseProfileKind::Rehearsal => ReleaseDestinationKind::Rehearsal,
    };
    let cargo = prepared_registry_binding(&workspace.config, profile_name, Ecosystem::Cargo)?;
    let npm = prepared_registry_binding(&workspace.config, profile_name, Ecosystem::Npm)?;
    let pypi = prepared_registry_binding(&workspace.config, profile_name, Ecosystem::Pypi)?;
    let destination = ReleaseDestinationBinding::new(
        profile_name,
        destination_kind,
        profile.forge_repository.clone(),
        cargo.id()?,
        npm.id()?,
        pypi.id()?,
    )?;
    let git_remote = prepared_git_remote(&workspace.root, workspace.runner)?;
    if git_remote.github_repository != *destination.forge_repository() {
        return Err(GraphError::UnsafeGitRemote {
            reason: "origin repository does not match the selected release profile",
        });
    }
    let provenance = callisto_model::ProvenancePolicy::new(
        product.provenance_repository.clone(),
        product.build_workflow.clone(),
        source.clone(),
    )?;

    let registry_bindings = BTreeMap::from([
        (Ecosystem::Cargo, cargo),
        (Ecosystem::Npm, npm),
        (Ecosystem::Pypi, pypi),
    ]);
    let mut approved = Vec::new();
    let mut slots = Vec::new();
    let mut prepared = BTreeMap::new();
    let mut operations = BTreeMap::new();
    for (package_id, (package, version)) in &selected {
        let matching_targets = package
            .publish_to
            .iter()
            .filter(|target| target.ecosystem() == Some(package_id.ecosystem()))
            .collect::<Vec<_>>();
        let Some(target) = matching_targets.first().copied() else {
            continue;
        };
        if matching_targets.len() != 1 {
            return Err(GraphError::ReleaseSelectionInvalid {
                package: package_id.clone(),
                reason: ReleaseSelectionInvalidReason::DuplicateRegistryTarget,
            });
        }
        let binding = registry_bindings
            .get(&package_id.ecosystem())
            .ok_or(GraphError::UnsupportedRelease {
                feature: UnsupportedReleaseFeature::Ecosystem,
            })?;
        let configured_artifacts = crate::config::resolve_package_config(&package.id, &workspace.config)?
            .and_then(|config| config.release_artifacts.as_deref());
        for (format, file_name) in registry_artifact_files(package_id, version, configured_artifacts)? {
            let publication_policy = match target {
                callisto_model::PublishTarget::CratesIo => RegistryPublicationPolicy::cargo(),
                callisto_model::PublishTarget::Npm { access, .. } => RegistryPublicationPolicy::npm(
                    access.unwrap_or(NpmAccess::Public),
                    if version.is_prerelease() { "next" } else { "latest" },
                )?,
                callisto_model::PublishTarget::Pypi { .. } => RegistryPublicationPolicy::pypi(),
                _ => {
                    return Err(GraphError::UnsupportedRelease {
                        feature: UnsupportedReleaseFeature::PublishTarget,
                    })
                }
            };
            let artifact = ApprovedRegistryArtifact::new(
                package_id.clone(),
                binding.id()?,
                format,
                publication_policy.clone(),
                file_name.clone(),
            )?;
            let slot = ReleaseArtifactSlot::registry_artifact(&artifact, version.clone(), provenance.clone());
            let id = ReleaseOperationId::RegistryArtifactPublish {
                package: package_id.clone(),
                version: version.clone(),
                registry: binding.id()?,
                slot: slot.clone(),
            };
            let operation = ReleaseOperation::new(id.clone(), vec![])?;
            if prepared
                .insert(
                    id.clone(),
                    PreparedOperation::RegistryArtifactPublish {
                        artifact: artifact.clone(),
                        registry: binding.clone(),
                        npm_client: (package_id.ecosystem() == Ecosystem::Npm)
                            .then(|| registry_argv::detect_npm_package_manager(&workspace.root)),
                    },
                )
                .is_some()
            {
                return Err(GraphError::ReleaseSelectionInvalid {
                    package: package_id.clone(),
                    reason: ReleaseSelectionInvalidReason::DuplicateRegistryTarget,
                });
            }
            operations.insert(id, operation);
            approved.push(artifact);
            slots.push(slot);
        }
    }

    let mut registry_ids = operations.keys().cloned().collect::<Vec<_>>();
    registry_ids.sort();
    for target in ProductTarget::ALL {
        slots.push(ReleaseArtifactSlot::product_asset(
            release.clone(),
            target,
            provenance.clone(),
        ));
    }
    slots.push(ReleaseArtifactSlot::checksum_manifest(
        release.clone(),
        provenance.clone(),
    ));
    slots.push(ReleaseArtifactSlot::release_metadata(release.clone(), provenance));

    let tag_text = release.tag();
    // `ProductReleaseId::tag` combines a validated lowercase product name,
    // one literal `@`, and validated SemVer, so it is already a safe Git ref.
    let tag_name = TagName::new_unchecked(tag_text.clone());
    let tag_id = ReleaseOperationId::ProductTag {
        release: release.clone(),
        tag: tag_text,
    };
    operations.insert(tag_id.clone(), ReleaseOperation::new(tag_id.clone(), registry_ids)?);
    prepared.insert(
        tag_id.clone(),
        PreparedOperation::ProductTag {
            name: tag_name.clone(),
            target: source.clone(),
            annotation: format!("Release {tag_name}"),
            remote: git_remote.clone(),
        },
    );
    let prepare_id = ReleaseOperationId::ForgePrepare {
        release: release.clone(),
        repository: destination.forge_repository().clone(),
    };
    operations.insert(
        prepare_id.clone(),
        ReleaseOperation::new(prepare_id.clone(), vec![tag_id])?,
    );
    prepared.insert(
        prepare_id.clone(),
        PreparedOperation::ForgePrepare {
            repository: destination.forge_repository().clone(),
            tag: tag_name.clone(),
        },
    );
    let mut upload_ids = Vec::new();
    for slot in slots.iter().filter(|slot| slot.release().is_some()) {
        let id = ReleaseOperationId::ArtifactUpload {
            release: release.clone(),
            slot: slot.clone(),
        };
        operations.insert(id.clone(), ReleaseOperation::new(id.clone(), vec![prepare_id.clone()])?);
        prepared.insert(id.clone(), PreparedOperation::ArtifactUpload { slot: slot.clone() });
        upload_ids.push(id);
    }
    upload_ids.sort();
    let publish_id = ReleaseOperationId::ForgePublish {
        release: release.clone(),
        repository: destination.forge_repository().clone(),
    };
    operations.insert(
        publish_id.clone(),
        ReleaseOperation::new(publish_id.clone(), upload_ids)?,
    );
    prepared.insert(
    #[error("remote release state conflicts with this release intent: {conflict}")]
    #[diagnostic(
        code(E167),
        help(
            "A tag or forge release already exists remotely with content that differs from this \
             release intent. Reconcile the remote state by hand -- this intent's authorization is \
             not in question."
        )
    )]
    ReleaseRemoteConflict {
        #[source]
        conflict: RemoteConflict,
    },

    #[error("unsupported release {feature}")]
    #[diagnostic(
        code(E168),
        help("This combination is not implemented for release; adjust the release configuration to use a supported combination.")
    )]
    UnsupportedRelease { feature: UnsupportedReleaseFeature },

    #[error("release selection for package `{package}` is invalid: {reason}")]
    #[diagnostic(
        code(E169),
        help("Adjust the release selection so each package appears at most once and matches an entry in the release plan.")
    )]
    ReleaseSelectionInvalid {
        package: callisto_model::ReleasePackageId,
        reason: ReleaseSelectionInvalidReason,
    },

    #[error("release precondition unmet: requires {requirement}")]
    #[diagnostic(
        code(E170),
        help("Satisfy the reported precondition (for example a detached HEAD or a configured GitHub remote) before retrying.")
    )]
    ReleasePreconditionUnmet {
        requirement: ReleasePreconditionRequirement,
    },

    #[error("internal release invariant violated: {detail}")]
    #[diagnostic(
        code(E171),
        help(
            "This is an internal callisto defect, not an operator action; report it along with the full error detail."
        )
    )]
    ReleaseInvariant { detail: String },

    #[error("external state conflicts with release operation `{operation:?}`")]
    #[diagnostic(
        code(E193),
        help("Reconcile the conflicting provider object manually; Callisto did not overwrite it.")
    )]
    ReleaseObservationConflict {
        operation: callisto_model::ReleaseOperationId,
    },

    #[error("external state for release operation `{operation:?}` could not be verified")]
    #[diagnostic(
        code(E194),
        help("Restore provider connectivity and credentials, then retry observation before applying any effect.")
    )]
    ReleaseObservationUnverifiable {
        operation: callisto_model::ReleaseOperationId,
    },

    #[error("release operation `{operation:?}` is not the exact missing work authorized by provider observation")]
    #[diagnostic(
        code(E195),
        help(
            "Run reconciliation in dependency order; Callisto did not apply work whose prerequisites remain missing."
        )
    )]
    ReleaseOperationNotMissing {
        operation: callisto_model::ReleaseOperationId,
    },
}

/// Why a workspace package that a `--package` filter named is nonetheless
/// absent from the computed [`crate::commands::plan_publish`] plan, distinct
/// from [`GraphError::UnknownPackage`] (which means the name matched no
/// workspace package at all).
#[derive(Clone, Copy, Debug, PartialEq, Eq, thiserror::Error)]
pub enum NotInPlanReason {
    #[error("its on-disk version already matches its last release tag; there is nothing pending to publish")]
    NotARelease,
    #[error("it configures no publish target with an implemented dispatch (e.g. only NuGet or GitHub Release)")]
    NoDispatchableTarget,
}

/// Source of a [`GraphError::ReleaseCommand`] (E164) failure: either the
/// subprocess exited non-zero, or it exited zero but produced output this
/// crate could not parse.
#[derive(Clone, Debug, PartialEq, Eq, thiserror::Error)]
pub enum CommandFailure {
    #[error("exited with status {exit_code:?}: {stderr}")]
    NonZeroExit { exit_code: Option<i32>, stderr: String },
    #[error("produced malformed output: {detail}")]
    MalformedOutput { detail: String },
}
use std::path::Path;
use std::time::Duration;

use crate::registry::{known_credential_env_values, redact_known_secrets};

/// The minimum `git` version callisto supports, as a [`semver::VersionReq`] grammar string
/// consumed directly by [`check_git_version`] — the single place this floor is defined, so
/// the requirement used for the actual comparison and the one rendered in
/// [`CommandError::IncompatibleVersion`]'s message can never drift apart.
pub const REQUIRED_GIT: &str = ">=2.20";

/// Trait for executing subprocess commands.
pub trait CommandRunner: Send + Sync {
    fn run(&self, program: &str, args: &[&str], cwd: &Path) -> Result<CommandOutput, CommandError>;

    /// Run a command with a hard wall-clock timeout. If the process does not
    /// exit before `timeout` elapses it is killed and
    /// [`CommandError::TimedOut`] is returned.
    ///
    /// The default implementation ignores `timeout` and delegates to [`Self::run`].
    /// Implementors that control a real subprocess should override this with an
    /// actual deadline check.
    fn run_with_timeout(
        &self,
        program: &str,
        args: &[&str],
        cwd: &Path,
        _timeout: Duration,
    ) -> Result<CommandOutput, CommandError> {
        self.run(program, args, cwd)
    }

    /// Like [`Self::run_with_timeout`], but for an internal existence/probe
    /// check whose stderr looks like a failure on the common path (e.g.
    /// `npm view` against an unpublished package prints a 404-shaped "not
    /// found" to stderr normally) -- unlike a real, user-facing mutating
    /// command, this must not stream that noise live to the terminal, only
    /// capture it into [`CommandOutput`] for the caller to classify.
    ///
    /// Default implementation just delegates to [`Self::run_with_timeout`]
    /// (streams live); implementors doing their own live-streaming should
    /// override this to suppress it for probe calls.
    fn run_quiet(
        &self,
        program: &str,
        args: &[&str],
        cwd: &Path,
        timeout: Duration,
    ) -> Result<CommandOutput, CommandError> {
        self.run_with_timeout(program, args, cwd, timeout)
    }

    /// Like [`Self::run`], but pipes `stdin` to the child process before
    /// reading its output. Needed for subcommands with a line-oriented
    /// input protocol -- e.g. `git cat-file --batch`, which reads one
    /// object identifier per line from stdin and streams each object's
    /// contents back on stdout, letting many objects be fetched in one
    /// subprocess round trip instead of one invocation per object.
    ///
    /// The default implementation returns [`CommandError::Unsupported`]:
    /// the great majority of [`CommandRunner`] implementors in this
    /// workspace (test doubles, `moon`'s own dispatch, etc.) never pipe
    /// stdin to a child process, so they don't need to implement this --
    /// only a real subprocess-backed runner used for such a call should
    /// override it.
    fn run_with_stdin(
        &self,
        program: &str,
        _args: &[&str],
        _cwd: &Path,
        _stdin: &[u8],
    ) -> Result<CommandOutput, CommandError> {
        Err(CommandError::Unsupported {
            program: program.to_string(),
            reason: "this CommandRunner does not support piping input to the child process".to_string(),
        })
    }

    /// Pipes `stdin` while enforcing a hard wall-clock timeout.
    ///
    /// The default fails closed: delegating to either unbounded primitive
    /// would silently discard one of the two guarantees this operation asks
    /// for. Real subprocess runners must override it explicitly.
    fn run_with_stdin_timeout(
        &self,
        program: &str,
        _args: &[&str],
        _cwd: &Path,
        _stdin: &[u8],
        _timeout: Duration,
    ) -> Result<CommandOutput, CommandError> {
        Err(CommandError::Unsupported {
            program: program.to_string(),
            reason: "this CommandRunner does not support bounded execution with piped input".to_string(),
        })
    }
}

/// Output from executing a command.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct CommandOutput {
    pub exit_code: Option<i32>,
    pub stdout: String,
    pub stderr: String,
}

impl CommandOutput {
    pub fn success(&self) -> bool {
        self.exit_code == Some(0)
    }

    pub fn stdout_trimmed(&self) -> &str {
        self.stdout.trim()
    }

    pub fn stdout_lines(&self) -> impl Iterator<Item = &str> {
        self.stdout.lines().map(|l| l.trim()).filter(|l| !l.is_empty())
    }

    /// Redacts known registry/VCS credential env-var values and any URL
    /// userinfo component from this command's raw stderr before it's
    /// embedded in a caller's user-facing error -- a failing subprocess
    /// invocation can surface an authenticated remote URL (e.g. GitHub
    /// Actions' `REDACTED`) verbatim in
    /// its own error output, and that text flows into `--format json` and
    /// miette diagnostic output downstream.
    ///
    /// The single shared definition of "how do we redact a subprocess's
    /// stderr in this workspace" -- composes [`redact_known_secrets`] and
    /// [`known_credential_env_values`] once here instead of each caller
    /// reimplementing the same one-line composition locally.
    pub fn redacted_stderr(&self) -> String {
        redact_known_secrets(&self.stderr, &known_credential_env_values(std::env::vars()))
    }
}

/// Errors occurring during command execution.
#[derive(Clone, Debug, thiserror::Error, miette::Diagnostic, PartialEq, Eq)]
#[non_exhaustive]
pub enum CommandError {
    #[error("`{program}` was not found; callisto requires it to be available")]
    #[diagnostic(code(E020), help("Ensure program is installed and available on system PATH."))]
    NotFound { program: String },

    #[error("`{program}` reports version `{found}`, but callisto requires {required}")]
    #[diagnostic(code(E021), help("Upgrade program to meet version requirement."))]
    IncompatibleVersion {
        program: String,
        found: String,
        required: String,
    },

    #[error("executing `{program}` is not supported on this surface: {reason}")]
    #[diagnostic(code(E022))]
    Unsupported { program: String, reason: String },

    #[error("`{program}` failed with exit code {exit_code:?}: {stderr}")]
    #[diagnostic(code(E023))]
    Failed {
        program: String,
        exit_code: Option<i32>,
        stderr: String,
    },

    #[error("failed to run `{program}`: {message}")]
    #[diagnostic(code(E024))]
    Io { program: String, message: String },

    #[error("`{program}` timed out after {seconds}s")]
    #[diagnostic(code(E025), help("The process did not exit within the allowed time. This usually indicates a network stall or a registry that is unreachable."))]
    TimedOut { program: String, seconds: u64 },
}

/// Returns the leading run of ASCII digits in `s`, stopping at the first
/// non-digit character (or the end of the string). Used to strip anything
/// `semver` would otherwise interpret as pre-release/build metadata (a
/// hyphen or plus) or a non-numeric trailing suffix, since a git version's
/// own reported string was never intended to carry semver's meaning for
/// those -- see [`check_git_version`]'s doc comment.
fn leading_digits(s: &str) -> &str {
    let end = s.find(|c: char| !c.is_ascii_digit()).unwrap_or(s.len());
    &s[..end]
}

/// Validates git version against the [`REQUIRED_GIT`] floor.
///
/// `reported` is raw `git --version` output (e.g. `"git version 2.39.5"`,
/// `"...2.39.5.windows.1"` on Windows, `"...2.39.5-rc1"` for a pre-release).
/// Only the leading `major.minor.patch` triple is parsed, each component
/// truncated at its first non-digit char (`5-rc1` -> `5`) before reaching
/// `semver`: an unstripped hyphenated suffix would make `semver::VersionReq`
/// exclude it from the `>=2.20` floor entirely, since semver reqs never
/// match a pre-release unless the requirement itself carries a matching
/// tag -- irrelevant to a real git build tag. Extra dot-separated
/// components (`.windows.1`) are ignored; a missing minor/patch defaults
/// to `0`.
///
/// Comparison itself is delegated to [`semver::VersionReq`] parsing
/// [`REQUIRED_GIT`], so the floor lives in one place, not a hand-maintained
/// duplicate that could drift from the error message's constant.
pub fn check_git_version(reported: &str) -> Result<(), CommandError> {
    let incompatible = || CommandError::IncompatibleVersion {
        program: "git".to_string(),
        found: reported.to_string(),
        required: REQUIRED_GIT.to_string(),
    };

    let version_str = reported.trim();
    let digits = version_str
        .split_whitespace()
        .find(|word| word.chars().next().is_some_and(|c| c.is_ascii_digit()))
        .unwrap_or(version_str);

    let mut parts = digits.splitn(4, '.').take(3);
    let major = leading_digits(parts.next().unwrap_or("0"));
    let minor = leading_digits(parts.next().unwrap_or("0"));
    let patch = leading_digits(parts.next().unwrap_or("0"));
    let core = format!("{major}.{minor}.{patch}");

    let version = semver::Version::parse(&core).map_err(|_parse_err| incompatible())?;
    let required = semver::VersionReq::parse(REQUIRED_GIT).map_err(|_parse_err| incompatible())?;

    if required.matches(&version) {
        Ok(())
    } else {
        Err(incompatible())
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    struct RunOnly;

    impl CommandRunner for RunOnly {
        fn run(&self, program: &str, _args: &[&str], _cwd: &Path) -> Result<CommandOutput, CommandError> {
            Err(CommandError::Unsupported {
                program: program.to_string(),
                reason: "not used".to_string(),
            })
        }
    }

    #[test]
    fn bounded_stdin_fails_closed_without_an_explicit_runner_override() {
        let error = RunOnly
            .run_with_stdin_timeout("publisher", &[], Path::new("."), b"payload", Duration::from_secs(1))
            .unwrap_err();
        assert!(matches!(error, CommandError::Unsupported { .. }));
    }

    #[test]
    fn parses_git_version() {
        assert!(check_git_version("git version 2.39.5").is_ok());
        assert!(check_git_version("git version 2.20.0").is_ok());
        assert!(check_git_version("git version 1.8.5").is_err());
    }

    /// Boundary check: REQUIRED_GIT's floor is exactly 2.20 -- one patch
    /// below and one minor below must both be rejected, matching the
    /// version-requirement string itself rather than a separately
    /// hand-maintained numeric comparison that could silently drift from it.
    #[test]
    fn rejects_versions_just_below_the_required_floor() {
        assert!(check_git_version("git version 2.19.9").is_err());
        assert!(check_git_version("git version 1.99.99").is_err());
    }

    /// Regression: `semver::VersionReq`'s `>=2.20` never matches a
    /// pre-release version unless the requirement itself carries a matching
    /// pre-release tag, which would make a hyphenated git build tag like
    /// `-rc1` falsely reject an otherwise-satisfying version if passed
    /// through to `semver::Version::parse` unstripped. A pre-release build
    /// well above the floor must still be accepted.
    #[test]
    fn accepts_hyphenated_prerelease_suffix_above_the_floor() {
        assert!(check_git_version("git version 2.39.5-rc1").is_ok());
        assert!(check_git_version("git version 2.19.9-rc1").is_err());
    }

    /// Git for Windows appends a non-semver `.windows.N` suffix onto the
    /// real version (e.g. `2.39.5.windows.1`). Only the leading
    /// major.minor.patch triple must be parsed; the suffix must not cause a
    /// spurious parse failure.
    #[test]
    fn ignores_trailing_windows_suffix() {
        assert!(check_git_version("git version 2.39.5.windows.1").is_ok());
        assert!(check_git_version("git version 2.19.9.windows.1").is_err());
    }

    /// A truncated report (major.minor with no patch) must not be rejected
    /// outright -- the missing patch is treated as 0, same as the original
    /// hand-rolled comparison's behavior.
    #[test]
    fn treats_missing_patch_as_zero() {
        assert!(check_git_version("git version 2.20").is_ok());
        assert!(check_git_version("git version 2.19").is_err());
    }

    /// Garbage input must be rejected as incompatible, not silently
    /// defaulted to 0 and evaluated as if it were a real (if very old)
    /// version -- there is a real difference between "we don't know what
    /// version this is" and "this version is definitely too old", even
    /// though both currently produce the same IncompatibleVersion error.
    #[test]
    fn rejects_unparseable_version_string() {
        assert!(check_git_version("git version unknown").is_err());
        assert!(check_git_version("").is_err());
    }

    /// A leaking authenticated remote URL in a subprocess's stderr (the
    /// realistic GitHub Actions shape: `REDACTED`)
    /// must not survive `CommandOutput::redacted_stderr` -- this is the
    /// single shared implementation every crate-level `redact_*_stderr`
    /// call site now delegates to instead of reimplementing.
    #[test]
    fn redacted_stderr_strips_authenticated_remote_url_userinfo() {
        let output = CommandOutput {
            exit_code: Some(128),
            stdout: String::new(),
            stderr: "fatal: unable to access 'REDACTED': The requested URL returned error: 403".to_string(),
        };
        let redacted = output.redacted_stderr();
        assert!(!redacted.contains("REDACTED"), "got: {redacted}");
        assert!(redacted.contains("[REDACTED]"), "got: {redacted}");
    }
}
use std::io::{Read, Write};
use std::path::Path;
use std::process::Stdio;
use std::time::{Duration, Instant};

use callisto_model::{known_credential_env_values, redact_known_secrets, CommandError, CommandOutput, CommandRunner};

/// Caps how much of a subprocess's stdout/stderr this process will retain
/// in memory. The pipe is still drained in full past this point (bytes
/// beyond the cap are read and discarded, never accumulated) so a chatty
/// child can never deadlock waiting on a full OS pipe buffer -- this
/// bounds memory, not duration (`PUBLISH_TIMEOUT_SECS` bounds that
/// separately).
const MAX_CAPTURED_OUTPUT_BYTES: usize = 10 * 1024 * 1024;

pub struct CliCommandRunner;

impl CommandRunner for CliCommandRunner {
    fn run(&self, program: &str, args: &[&str], cwd: &Path) -> Result<CommandOutput, CommandError> {
        let output = std::process::Command::new(program)
            .args(args)
            .current_dir(cwd)
            .stdin(Stdio::null())
            .stdout(Stdio::piped())
            .stderr(Stdio::piped())
            .output();

        match output {
            Ok(o) => {
                let stderr = String::from_utf8_lossy(&o.stderr).into_owned();
                // Keep raw stderr available to callers for protocol/error
                // classification, but never leak credentials to the terminal.
                if !stderr.is_empty() {
                    let secrets = known_credential_env_values(std::env::vars());
                    eprint!("{}", redact_known_secrets(&stderr, &secrets));
                }
                Ok(CommandOutput {
                    exit_code: o.status.code(),
                    stdout: String::from_utf8_lossy(&o.stdout).into_owned(),
                    stderr,
                })
            }
            Err(e) if e.kind() == std::io::ErrorKind::NotFound => Err(CommandError::NotFound {
                program: program.to_string(),
            }),
            Err(e) => Err(CommandError::Io {
                program: program.to_string(),
                message: e.to_string(),
            }),
        }
    }

    fn run_with_timeout(
        &self,
        program: &str,
        args: &[&str],
        cwd: &Path,
        timeout: Duration,
    ) -> Result<CommandOutput, CommandError> {
        // `known_credential_env_values` is scanned here, at the trait-method
        // call site, rather than inside `run_with_timeout_impl` itself: this
        // keeps the impl fn pure and directly unit-testable with a synthetic
        // secrets list (no process-env mutation, which would race against
        // other tests running in parallel in this binary).
        run_with_timeout_impl(
            program,
            args,
            cwd,
            timeout,
            StderrMode::Live,
            known_credential_env_values(std::env::vars()),
        )
    }

    fn run_quiet(
        &self,
        program: &str,
        args: &[&str],
        cwd: &Path,
        timeout: Duration,
    ) -> Result<CommandOutput, CommandError> {
        // Quiet mode never echoes stderr live (see `StderrMode::Quiet`
        // below), so there's nothing to redact -- pass an empty secrets
        // list rather than paying for an env scan that can only go unused.
        run_with_timeout_impl(program, args, cwd, timeout, StderrMode::Quiet, Vec::new())
    }

    fn run_with_stdin(
        &self,
        program: &str,
        args: &[&str],
        cwd: &Path,
        stdin: &[u8],
    ) -> Result<CommandOutput, CommandError> {
        let mut child = std::process::Command::new(program)
            .args(args)
            .current_dir(cwd)
            .stdin(Stdio::piped())
            .stdout(Stdio::piped())
            .stderr(Stdio::piped())
            .spawn()
            .map_err(|e| {
                if e.kind() == std::io::ErrorKind::NotFound {
                    CommandError::NotFound {
                        program: program.to_string(),
                    }
                } else {
                    CommandError::Io {
                        program: program.to_string(),
                        message: e.to_string(),
                    }
                }
            })?;

        // Write the payload on its own thread, concurrently with this
        // thread draining stdout/stderr via `wait_with_output` below.
        // A protocol like `git cat-file --batch` replies to each stdin
        // line as it arrives, so writing everything up front on the same
        // thread that also has to read the reply back could deadlock once
        // either the stdin or the stdout pipe buffer fills -- exactly the
        // hazard `run_with_timeout_impl` above uses dedicated reader
        // threads to avoid, mirrored here for the write side.
        let mut stdin_pipe = child.stdin.take().expect("stdin was requested as piped");
        let payload = stdin.to_vec();
        let writer = std::thread::spawn(move || {
            // A closed read end (the child exited early, e.g. on a bad
            // invocation) would otherwise surface as a `BrokenPipe` write
            // error here; the child's actual exit code/stderr, captured by
            // `wait_with_output` below, is the caller-facing signal for
            // that failure, so a write error on this thread is dropped
            // rather than reported.
            drop(stdin_pipe.write_all(&payload));
            drop(stdin_pipe.flush());
        });

        let output = child.wait_with_output();
        // The writer thread only writes then drops its handle, so it must
        // already be finished (or about to finish) by the time the child
        // has exited and `wait_with_output` has drained its output --
        // joining here can't block indefinitely.
        drop(writer.join());

        match output {
            Ok(o) => {
                let stderr = String::from_utf8_lossy(&o.stderr).into_owned();
                if !stderr.is_empty() {
                    let secrets = known_credential_env_values(std::env::vars());
                    eprint!("{}", redact_known_secrets(&stderr, &secrets));
                }
                Ok(CommandOutput {
                    exit_code: o.status.code(),
                    stdout: String::from_utf8_lossy(&o.stdout).into_owned(),
                    stderr,
                })
            }
            Err(e) => Err(CommandError::Io {
                program: program.to_string(),
                message: e.to_string(),
            }),
        }
    }

    fn run_with_stdin_timeout(
        &self,
        program: &str,
        args: &[&str],
        cwd: &Path,
        stdin: &[u8],
        timeout: Duration,
    ) -> Result<CommandOutput, CommandError> {
        run_with_timeout_and_stdin_impl(
            program,
            args,
            cwd,
            timeout,
            StderrMode::Live,
            known_credential_env_values(std::env::vars()),
            Some(stdin.to_vec()),
        )
    }
}

/// Controls whether [`run_with_timeout_impl`]'s stderr reader thread prints
/// each line live as it arrives. Captured `CommandOutput.stderr` is
/// identical either way -- this only affects what's echoed to the
/// terminal while the subprocess runs.
#[derive(Clone, Copy, PartialEq, Eq)]
enum StderrMode {
    Live,
    Quiet,
}

/// `live_secrets`: known-credential values (see
/// [`callisto_model::known_credential_env_values`]) to redact from each
/// line *before* it's echoed live to the terminal via `eprintln!`. This is
/// deliberately separate from -- and does not affect -- the `captured`
/// buffer that becomes the returned `CommandOutput.stderr`: that copy must
/// stay byte-for-byte raw so downstream classifiers (e.g.
/// `extract_retry_after_duration`, `detect_auth_failure`) can still match
/// exact upstream text. Callers pass the secrets list in rather than this
/// function reading the environment itself, keeping it pure and testable
/// with a synthetic list.
fn run_with_timeout_impl(
    program: &str,
    args: &[&str],
    cwd: &Path,
    timeout: Duration,
    stderr_mode: StderrMode,
    live_secrets: Vec<String>,
) -> Result<CommandOutput, CommandError> {
    run_with_timeout_and_stdin_impl(program, args, cwd, timeout, stderr_mode, live_secrets, None)
}

fn run_with_timeout_and_stdin_impl(
    program: &str,
    args: &[&str],
    cwd: &Path,
    timeout: Duration,
    stderr_mode: StderrMode,
    live_secrets: Vec<String>,
    stdin_payload: Option<Vec<u8>>,
) -> Result<CommandOutput, CommandError> {
    let mut child = std::process::Command::new(program)
        .args(args)
        .current_dir(cwd)
        .stdin(if stdin_payload.is_some() {
            Stdio::piped()
        } else {
            Stdio::null()
        })
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()
        .map_err(|e| {
            if e.kind() == std::io::ErrorKind::NotFound {
                CommandError::NotFound {
                    program: program.to_string(),
                }
            } else {
                CommandError::Io {
                    program: program.to_string(),
                    message: e.to_string(),
                }
            }
        })?;

    if let Some(payload) = stdin_payload {
        let mut stdin_pipe = child.stdin.take().expect("stdin was requested as piped");
        std::thread::spawn(move || {
            drop(stdin_pipe.write_all(&payload));
            drop(stdin_pipe.flush());
        });
    }

    // Read stdout/stderr in separate threads to prevent pipe-buffer deadlock
    // when the child produces output while we wait for it to exit.
    let stdout_handle = child.stdout.take().unwrap();
    let stderr_handle = child.stderr.take().unwrap();

    // The reader threads signal completion over a channel rather than
    // being joined directly. Killing (or the natural exit of) the
    // direct child does NOT close pipe fds held open by a descendant
    // process that inherited them (common for npm/cargo/python publish
    // lifecycle scripts spawning subprocesses). If that happens, the
    // blocking `read()` inside these threads never returns. Using
    // `recv_timeout` below lets us bound how long we wait for them
    // without ever blocking the caller indefinitely.
    let (stdout_tx, stdout_rx) = std::sync::mpsc::channel::<String>();
    let (stderr_tx, stderr_rx) = std::sync::mpsc::channel::<String>();

    std::thread::spawn(move || {
        let mut reader = stdout_handle;
        let mut captured: Vec<u8> = Vec::new();
        let mut truncated = false;
        let mut chunk = [0u8; 65536];
        loop {
            match reader.read(&mut chunk) {
                Ok(0) => break,
                Ok(n) => {
                    // Bytes past the cap are still read (draining the
                    // pipe so the child never blocks on a full buffer)
                    // but not retained.
                    if !truncated {
                        let remaining = MAX_CAPTURED_OUTPUT_BYTES - captured.len();
                        let take = n.min(remaining);
                        captured.extend_from_slice(&chunk[..take]);
                        if take < n {
                            truncated = true;
                        }
                    }
                }
                Err(_) => break,
            }
        }
        let mut text = String::from_utf8_lossy(&captured).into_owned();
        if truncated {
            text.push_str("\n...[output truncated]\n");
        }
        drop(stdout_tx.send(text));
    });
    // Stream stderr line-by-line so publish progress (cargo/npm/twine
    // write to stderr) appears in real time rather than after the
    // process exits, while capping the accumulated text returned to
    // the caller. Deliberately reads raw bytes rather than using
    // `BufReader::lines()`: that iterator has no size bound on a
    // single line, so a flood with no newlines at all would still
    // buffer unboundedly inside it before ever yielding a line to cap.
    // `stderr_mode` gates only the live eprintln -- captured output is
    // identical either way (Live vs. Quiet).
    //
    // NOTE: captured output is no longer necessarily byte-identical to
    // what was printed live. Each line handed to `eprintln!` is redacted
    // via `live_secrets` first (registry CLIs can echo a credential
    // verbatim in their own stderr diagnostics), while `captured` -- and
    // therefore the returned `CommandOutput.stderr` -- deliberately stays
    // raw so error classifiers keep matching exact upstream text. For a
    // credential-bearing line, the terminal sees `[REDACTED]`; the
    // returned `CommandOutput.stderr` still has the real value.
    std::thread::spawn(move || {
        let mut reader = stderr_handle;
        let mut captured: Vec<u8> = Vec::new();
        let mut truncated = false;
        let mut pending_line: Vec<u8> = Vec::new();
        let mut chunk = [0u8; 65536];
        loop {
            match reader.read(&mut chunk) {
                Ok(0) => break,
                Ok(n) => {
                    let data = &chunk[..n];
                    for &b in data {
                        if b == b'\n' {
                            if pending_line.last() == Some(&b'\r') {
                                pending_line.pop();
                            }
                            if stderr_mode == StderrMode::Live {
                                let line = redact_known_secrets(&String::from_utf8_lossy(&pending_line), &live_secrets);
                                eprintln!("{line}");
                            }
                            pending_line.clear();
                        } else if pending_line.len() < MAX_CAPTURED_OUTPUT_BYTES {
                            pending_line.push(b);
                        }
                    }
                    if !truncated {
                        let remaining = MAX_CAPTURED_OUTPUT_BYTES - captured.len();
                        let take = data.len().min(remaining);
                        captured.extend_from_slice(&data[..take]);
                        if take < data.len() {
                            truncated = true;
                        }
                    }
                }
                Err(_) => break,
            }
        }
        if !pending_line.is_empty() {
            if pending_line.last() == Some(&b'\r') {
                pending_line.pop();
            }
            if stderr_mode == StderrMode::Live {
                let line = redact_known_secrets(&String::from_utf8_lossy(&pending_line), &live_secrets);
                eprintln!("{line}");
            }
        }
        let mut text = String::from_utf8_lossy(&captured).into_owned();
        if truncated {
            text.push_str("\n...[output truncated]\n");
        }
        drop(stderr_tx.send(text));
    });

    // Grace period to wait for the reader threads after the direct
    // child has exited (or been killed). Bounded so a lingering
    // descendant holding the pipe open can never hang the caller.
    const READER_GRACE: Duration = Duration::from_secs(3);

    let deadline = Instant::now() + timeout;
    let status = loop {
        match child.try_wait().map_err(|e| CommandError::Io {
