use std::fmt;
use std::path::{Path, PathBuf};

use callisto_model::{ApplyPermit, CommandError, CommitRecord, CommitSha, CommitWalkError, CommitWalker, TagName};
use sha2::{Digest, Sha256};
use thiserror::Error;

pub mod access;
pub mod release_lock;
pub mod shell;

pub use access::GitAccess;
pub use shell::ShellGit;

/// SHA-256 of the canonical message bytes in an annotated Git tag.
///
/// Callisto stores exactly one final newline after its normalized message.
/// Release callers construct this value from the logical annotation they pass to
/// [`GitDataSource::create_tag`], while remote observation hashes the raw
/// message bytes in the fetched tag object. Keeping that conversion here
/// prevents the graph layer from having a second, subtly different notion of
/// annotated-tag equality.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub struct TagAnnotationDigest(String);

impl TagAnnotationDigest {
    /// Hashes an annotation using Callisto's canonical tag-message encoding.
    pub fn from_annotation(annotation: &str) -> Self {
        Self::from_tag_object_message(canonical_tag_annotation_message(annotation).as_bytes())
    }

    /// Hashes raw annotation bytes from a parsed annotated tag object.
    pub fn from_tag_object_message(message: &[u8]) -> Self {
        Self(format!("{:x}", Sha256::digest(message)))
    }

    /// Returns the canonical lowercase SHA-256 rendering.
    pub fn as_str(&self) -> &str {
        &self.0
    }
}

/// Produces the one annotation serialization every release tag backend must
/// write and every expected digest must represent. Git's `-m` interface
/// otherwise applies cleanup that native gix tag creation does not, which can
/// make byte-identical logical release annotations compare differently after
/// push/readback.
pub(crate) fn canonical_tag_annotation_message(annotation: &str) -> String {
    let mut canonical = annotation.trim_end_matches(['\r', '\n']).to_string();
    canonical.push('\n');
    canonical
}

impl fmt::Display for TagAnnotationDigest {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        formatter.write_str(&self.0)
    }
}

/// The complete, remote-only result of comparing an annotated release tag to
/// its immutable expectation. A matching local tag is intentionally absent
/// from this vocabulary: it provides no proof about the configured remote.
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum RemoteAnnotatedTagObservation {
    Absent,
    Exact,
    Conflict(RemoteAnnotatedTagConflict),
}

/// The closed reasons a remote tag can fail an exact annotated-tag check.
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum RemoteAnnotatedTagConflict {
    /// The remote name resolves to a lightweight tag, which cannot carry the
    /// required annotation.
    LightweightTag,
    /// The tag peels to a commit other than the immutable release source.
    Target { expected: CommitSha, actual: CommitSha },
    /// The annotated tag object's declared target is inconsistent with the
    /// peeled remote ref, so its content cannot be accepted as proof.
    MalformedTarget,
    /// The tag object does not contain the expected annotated-tag header.
    MalformedTagObject,
    /// The tag annotation bytes differ from the release intent.
    Annotation {
        expected: TagAnnotationDigest,
        actual: TagAnnotationDigest,
    },
}

#[derive(Clone, Debug, Error, miette::Diagnostic, PartialEq, Eq)]
#[non_exhaustive]
pub enum VcsError {
    #[error("failed to discover Git repository at `{path}`: {message}")]
    #[diagnostic(code(E050), help("Ensure target directory is inside a valid Git repository."))]
    RepoNotFound { path: PathBuf, message: String },

    #[error("git error: {0}")]
    #[diagnostic(code(E051))]
    Git(String),

    #[error("reference `{ref_name}` was not found")]
    #[diagnostic(code(E052), help("Check if reference or tag exists in local or remote Git refs."))]
    RefNotFound { ref_name: String },

    #[error("tag glob pattern `{pattern}` is not a valid glob: {message}")]
    #[diagnostic(
        code(E053),
        help("Fix the glob syntax (e.g. balance `{{`/`}}` and `[`/`]`) or use a literal tag name.")
    )]
    InvalidGlob { pattern: String, message: String },

    /// Wraps a [`CommandError`] surfaced by the [`ShellGit`] (`CommandRunner`-
    /// shelled) backend -- e.g. the `git` binary itself couldn't be spawned.
    /// Kept `transparent` so callers that only care about the underlying
    /// `CommandError` (most of them, since it's the same error every direct
    /// `CommandRunner::run` call site already surfaces) can match through it.
    #[error(transparent)]
    Command(#[from] CommandError),
}

/// Narrows a [`VcsError`] to the Layer 1 [`CommitWalkError`] vocabulary at
/// the [`CommitWalker`] boundary.
///
/// [`CommitWalkError::Command`] and [`CommitWalkError::RefNotFound`] survive
/// as themselves -- they are the two distinctions consumers branch on. Every
/// other variant is gix- or repository-specific with no Layer 1 equivalent,
