fn successful_push_with_non_exact_readback_returns_typed_conflict_and_hardens_argv() {
    let tag_object = "b".repeat(40);
    let target = "a".repeat(40);
    let target_for_response = target.clone();
    let runner = FakeRunner {
        calls: Mutex::new(Vec::new()),
        response: Box::new(move |args| {
            match args[0] {
            "push" => Ok(ok("")),
            "ls-remote" => Ok(ok(format!(
                "{tag_object}\trefs/tags/release-readback-conflict\n{target_for_response}\trefs/tags/release-readback-conflict^{{}}\n"
            ))),
            "fetch" => Ok(ok("")),
            "--no-replace-objects" => Ok(ok(format!(
                "object {target_for_response}\ntype commit\ntag release-readback-conflict\ntagger Test <test@example.com> 0 +0000\n\nwrong annotation\n"
            ))),
            other => panic!("unexpected command: {other:?} ({args:?})"),
        }
        }),
    };
    let git = ShellGit::new(&runner, PathBuf::from("."));
    let name = TagName::parse("release-readback-conflict").unwrap();
    let target = CommitSha::parse(&target).unwrap();
    let digest = TagAnnotationDigest::from_annotation("Expected annotation");

    assert!(matches!(
        git.push_annotated_tag_and_confirm("origin", &name, &target, &digest, &permit()),
        Ok(RemoteAnnotatedTagObservation::Conflict(
            RemoteAnnotatedTagConflict::Annotation { .. }
        ))
    ));
    assert_eq!(
        *runner.calls.lock().unwrap(),
        vec![
            vec![
                "push",
                "--no-follow-tags",
                "--",
                "origin",
                "refs/tags/release-readback-conflict:refs/tags/release-readback-conflict",
            ],
            vec![
                "ls-remote",
                "--tags",
                "--",
                "origin",
                "refs/tags/release-readback-conflict",
                "refs/tags/release-readback-conflict^{}",
            ],
            vec![
                "fetch",
                "--no-tags",
                "--no-write-fetch-head",
                "--",
                "origin",
                "refs/tags/release-readback-conflict",
            ],
            vec![
                "--no-replace-objects",
                "cat-file",
                "-p",
                "--",
                "bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb"
            ],
        ]
    );
