fn remote_annotated_tag_observation_distinguishes_absent_exact_conflicts_and_local_only() {
    let (_remote, local, first) = remote_fixture();
    let runner = RealGitRunner;
    let git = GitAccess::discover(local.path(), &runner);
    let absent = TagName::parse("release-absent").unwrap();
    let annotation = "Release absent";
    let digest = TagAnnotationDigest::from_annotation(annotation);

    assert_eq!(
        git.observe_remote_annotated_tag("origin", &absent, &first, &digest)
            .unwrap(),
        RemoteAnnotatedTagObservation::Absent
    );

    let local_only = TagName::parse("release-local-only").unwrap();
    run_git(
        local.path(),
        &[
            "-c",
            "tag.gpgSign=false",
            "tag",
            "-a",
            "-m",
            annotation,
            local_only.as_str(),
            first.as_str(),
        ],
    );
    assert_eq!(
        git.observe_remote_annotated_tag("origin", &local_only, &first, &digest)
            .unwrap(),
        RemoteAnnotatedTagObservation::Absent,
        "a matching local tag must never prove the configured remote"
    );

    let exact = TagName::parse("release-exact").unwrap();
    create_and_push_annotated_tag(local.path(), &exact, &first, annotation);
    let native = GitRepository::discover(local.path()).unwrap();
    assert_eq!(
        native
            .observe_remote_annotated_tag("origin", &exact, &first, &digest)
            .unwrap(),
        RemoteAnnotatedTagObservation::Exact,
        "direct native repository access must use the same remote contract"
    );
    assert_eq!(
        git.observe_remote_annotated_tag("origin", &exact, &first, &digest)
            .unwrap(),
        RemoteAnnotatedTagObservation::Exact
    );

    std::fs::write(local.path().join("release.txt"), "second\n").unwrap();
    run_git(local.path(), &["add", "."]);
    run_git(local.path(), &["commit", "-q", "-m", "second"]);
    let second = GitDataSource::head_sha(&git).unwrap();
