            vec![
                "fetch",
                "--no-tags",
                "--no-write-fetch-head",
                "--",
                "origin",
                "refs/tags/release-readback-conflict",
            ],
            vec![
                "--no-replace-objects",
                "cat-file",
                "-p",
                "--",
                "bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb"
            ],
        ]
    );
}

