    use callisto_model::{
        CommandError, CommandOutput, CommitSha, GitHubRepository, ProductName, ProductReleaseId, ProductTarget,
        RegistryBindingDigest, RegistryBindingId, ReleaseArtifactEntry, ReleaseDecisionEntry, ReleaseDecisionV1,
        ReleaseDestinationBinding, ReleaseDestinationKind, ReleaseInclusionReason, ReleaseIntent, ReleaseOperation,
        ReleaseOperationId, ReleasePackageId, ValidatedPayloadEntries, Version,
                .expect("piped stdin")
                .write_all(stdin)
                .map_err(|error| CommandError::Io {
                    program: program.to_string(),
                    message: error.to_string(),
                })?;
            let output = child.wait_with_output().map_err(|error| CommandError::Io {
                program: program.to_string(),
                message: error.to_string(),
            })?;
            Ok(CommandOutput {
                exit_code: output.status.code(),
                stdout: String::from_utf8_lossy(&output.stdout).into_owned(),
                stderr: String::from_utf8_lossy(&output.stderr).into_owned(),
            })
