#[cfg(test)]
mod tests {
    use std::{
        collections::VecDeque,
        io::Write as _,
        path::Path,
        process::{Command, Stdio},
        sync::{Arc, Mutex},
    };

    use callisto_model::{
        CommandError, CommandRunner, Ecosystem, ReleaseArtifactEntry, ReleaseDecisionEntry, ReleaseDecisionV1,
        ReleaseInclusionReason, ValidatedPayloadEntries, VersionGrammar,
    };

    use super::*;

    #[derive(Clone, Default)]
    struct RecordingRunner {
        calls: Arc<Mutex<Vec<(String, Vec<String>)>>>,
        outputs: Arc<Mutex<VecDeque<Result<CommandOutput, CommandError>>>>,
    }

    impl CommandRunner for RecordingRunner {
        fn run(&self, program: &str, args: &[&str], _cwd: &Path) -> Result<CommandOutput, CommandError> {
            self.calls.lock().unwrap().push((
                program.to_string(),
                args.iter().map(|value| value.to_string()).collect(),
            ));
            self.outputs.lock().unwrap().pop_front().unwrap()
        }
    }

    fn output(exit_code: i32, stdout: &str, stderr: &str) -> Result<CommandOutput, CommandError> {
        Ok(CommandOutput {
            exit_code: Some(exit_code),
            stdout: stdout.to_string(),
            stderr: stderr.to_string(),
        })
    }

    #[derive(Clone, Debug)]
    enum RemoteTagPlan {
        Absent,
        Exact {
            name: String,
            target: String,
            annotation: String,
        },
    }

    impl Default for RemoteTagPlan {
        fn default() -> Self {
            Self::Absent
        }
    }

    #[derive(Clone, Debug)]
    struct NpmPlan {
        output: CommandOutput,
        file: Option<(String, Vec<u8>)>,
    }

    #[derive(Clone, Default)]
    struct CapabilityRunner {
        calls: Arc<Mutex<Vec<(String, Vec<String>)>>>,
        github: Arc<Mutex<VecDeque<CommandOutput>>>,
        http: Arc<Mutex<VecDeque<CommandOutput>>>,
        npm: Arc<Mutex<VecDeque<NpmPlan>>>,
        remote_tag: Arc<Mutex<RemoteTagPlan>>,
        promote_remote_on_push: Arc<Mutex<Option<RemoteTagPlan>>>,
    }

    impl CapabilityRunner {
        fn command_output(program: &str, args: &[&str], cwd: &Path) -> Result<CommandOutput, CommandError> {
            let output = Command::new(program)
                .args(args)
                .current_dir(cwd)
