                    OperationObservation::Conflict(ExternalConflict::RegistryLength {
                        slot: slot.clone(),
                        observed,
                    })
                }
                Ok(NpmArtifactObservation::Bytes(observed)) => {
                    if observed == expected_digest {
                        exact()
                    } else {
                        OperationObservation::Conflict(ExternalConflict::RegistryDigest {
                            slot: slot.clone(),
                            observed,
                        })
                    }
                }
                Err(failure) => OperationObservation::Unverifiable(failure),
            }
        }
        PreparedRegistryEndpointsView::Pypi { metadata, .. }
            if matches!(
                slot,
                ReleaseArtifactSlot::RegistryPackage {
                    format: RegistryArtifactFormat::PythonWheel | RegistryArtifactFormat::PythonSdist,
                    ..
                }
            ) =>
        {
            observe_pypi(
                session, artifacts, validated, package, version, registry, slot, metadata,
            )
        }
        _ => OperationObservation::Unverifiable(ObservationFailure::Capability {
            provider: ObservationProvider::PreparedCapability,
        }),
    }
}

