    #[derive(Clone, Default)]
    pub(super) struct CapabilityRunner {
        calls: Arc<Mutex<Vec<(String, Vec<String>)>>>,
        github: Arc<Mutex<VecDeque<CommandOutput>>>,
        http: Arc<Mutex<VecDeque<CommandOutput>>>,
        npm: Arc<Mutex<VecDeque<NpmPlan>>>,
        remote_tag: Arc<Mutex<RemoteTagPlan>>,
        promote_remote_on_push: Arc<Mutex<Option<RemoteTagPlan>>>,
    }

    impl CapabilityRunner {
        fn command_output(program: &str, args: &[&str], cwd: &Path) -> Result<CommandOutput, CommandError> {
            let output = Command::new(program)
                .args(args)
                .current_dir(cwd)
                .output()
                .map_err(|error| CommandError::Io {
                    program: program.to_string(),
                    message: error.to_string(),
                })?;
            Ok(CommandOutput {
                exit_code: output.status.code(),
                stdout: String::from_utf8_lossy(&output.stdout).into_owned(),
                stderr: String::from_utf8_lossy(&output.stderr).into_owned(),
            })
        }

        fn set_exact_remote_tag(&self, name: &TagName, target: &callisto_model::CommitSha, annotation: &str) {
            *self.remote_tag.lock().unwrap() = RemoteTagPlan::Exact {
                name: name.as_str().to_string(),
                target: target.as_str().to_string(),
                annotation: annotation.to_string(),
            };
        }

        fn set_remote_tag_after_push(&self, name: &TagName, target: &callisto_model::CommitSha, annotation: &str) {
            *self.promote_remote_on_push.lock().unwrap() = Some(RemoteTagPlan::Exact {
                name: name.as_str().to_string(),
                target: target.as_str().to_string(),
                annotation: annotation.to_string(),
            });
        }

        fn push_github(&self, exit_code: i32, status: u16, body: serde_json::Value) {
            self.github.lock().unwrap().push_back(CommandOutput {
                exit_code: Some(exit_code),
                stdout: format!("HTTP/2 {status} status\r\ncontent-type: application/json\r\n\r\n{body}"),
                stderr: String::new(),
            });
        }

        fn push_http(&self, status: u16, body: serde_json::Value) {
            self.http.lock().unwrap().push_back(CommandOutput {
                exit_code: Some(0),
                stdout: format!("HTTP/1.1 {status} status\r\ncontent-type: application/json\r\n\r\n{body}"),
                stderr: String::new(),
            });
        }
    }

    impl CommandRunner for CapabilityRunner {
        fn run(&self, program: &str, args: &[&str], cwd: &Path) -> Result<CommandOutput, CommandError> {
            self.calls.lock().unwrap().push((
                program.to_string(),
                args.iter().map(|value| value.to_string()).collect(),
            ));
            match (program, args.first().copied()) {
                ("gh", Some("attestation")) => output(0, "", ""),
                ("gh", Some("api")) => Ok(self.github.lock().unwrap().pop_front().expect("queued GitHub response")),
                ("curl", _) => Ok(self.http.lock().unwrap().pop_front().expect("queued HTTP response")),
                ("npm", Some("pack")) => {
                    let plan = self.npm.lock().unwrap().pop_front().expect("queued npm response");
                    if let Some((file_name, bytes)) = &plan.file {
                        let destination = args
                            .iter()
                            .position(|argument| *argument == "--pack-destination")
                            .and_then(|index| args.get(index + 1))
                            .expect("npm pack destination");
                        std::fs::write(Path::new(destination).join(file_name), bytes).unwrap();
                    }
                    Ok(plan.output)
                }
                ("git", Some("ls-remote")) => match self.remote_tag.lock().unwrap().clone() {
                    RemoteTagPlan::Absent => output(0, "", ""),
                    RemoteTagPlan::Exact { name, target, .. } => output(
                        0,
                        &format!(
                            "{}\trefs/tags/{name}\n{target}\trefs/tags/{name}^{{}}\n",
                            "b".repeat(40)
                        ),
                        "",
                    ),
                },
                ("git", Some("fetch")) => output(0, "", ""),
                ("git", Some("push")) => {
                    if let Some(promoted) = self.promote_remote_on_push.lock().unwrap().take() {
                        *self.remote_tag.lock().unwrap() = promoted;
                    }
                    output(0, "", "")
                }
                ("git", Some("--no-replace-objects")) => match self.remote_tag.lock().unwrap().clone() {
                    RemoteTagPlan::Exact {
                        name,
                        target,
                        annotation,
                    } => output(
                        0,
                        &format!(
                            "object {target}\ntype commit\ntag {name}\ntagger Test <test@example.com> 0 +0000\n\n{annotation}\n"
                        ),
                        "",
                    ),
                    RemoteTagPlan::Absent => panic!("cat-file is unreachable for an absent tag"),
                },
                _ => Self::command_output(program, args, cwd),
            }
        }

        fn run_with_stdin(
            &self,
            program: &str,
            args: &[&str],
            cwd: &Path,
            stdin: &[u8],
        ) -> Result<CommandOutput, CommandError> {
            let mut child = Command::new(program)
                .args(args)
                .current_dir(cwd)
                .stdin(Stdio::piped())
                .stdout(Stdio::piped())
                .stderr(Stdio::piped())
                .spawn()
                .map_err(|error| CommandError::Io {
                    program: program.to_string(),
                    message: error.to_string(),
                })?;
            child.stdin.take().unwrap().write_all(stdin).unwrap();
            let output = child.wait_with_output().unwrap();
            Ok(CommandOutput {
                exit_code: output.status.code(),
                stdout: String::from_utf8_lossy(&output.stdout).into_owned(),
                stderr: String::from_utf8_lossy(&output.stderr).into_owned(),
            })
        }
    }

    fn run_git(root: &Path, args: &[&str]) {
        assert!(Command::new("git")
            .args(args)
            .current_dir(root)
            .status()
            .unwrap()
            .success());
    }

