                _ => None,
            }
        }

        pub fn validate(&self, release: &ProductReleaseId) -> Result<(), SuccessorError> {
            if !is_safe_artifact_component(self.file_name()) {
                return Err(SuccessorError::UnsafeArtifactSlot);
            }
            self.policy().validate()?;
            match self {
