            let Some(version) = versions
                .iter()
                .find(|candidate| candidate.grammar() == VersionGrammar::SemVer)
                .cloned()
            else {
                return Err(SuccessorError::NonSemverProductVersion {
                    version: Box::new(first.clone()),
                });
            };
            let canonical = version.render();
            for candidate in &versions {
                if candidate.render() != canonical {
                    return Err(SuccessorError::DivergentCoordinatedVersion {
                        expected: Box::new(version.clone()),
                        found: Box::new(candidate.clone()),
                    });
                }
            }
            Self::new(product, version)
        }

        pub fn product(&self) -> &ProductName {
            &self.product
        }

        pub fn version(&self) -> &Version {
            &self.version
        }

        pub fn tag(&self) -> String {
            if !self.github_attestation_required || !is_safe_workflow_path(&self.workflow_path) {
                return Err(SuccessorError::InvalidProvenance);
            }
            Ok(())
        }
    }

    impl<'de> Deserialize<'de> for ProvenancePolicy {
        fn deserialize<D>(deserializer: D) -> Result<Self, D::Error>
        where
            D: Deserializer<'de>,
        {
            let wire = ProvenancePolicyWire::deserialize(deserializer)?;
            let value = Self {
                repository: wire.repository,
                workflow_path: wire.workflow_path,
                workflow_commit: wire.workflow_commit,
                github_attestation_required: wire.github_attestation_required,
            };
            value.validate().map(|()| value).map_err(serde::de::Error::custom)
        }
    }

    #[derive(Clone, Debug, PartialEq, Eq, Hash, Serialize, Deserialize, JsonSchema)]
