    pub enum ReleaseArtifactSlot {
        RegistryPackage {
            package: ReleasePackageId,
            version: Version,
            #[serde(flatten)]
            registry: RegistryBindingId,
            format: RegistryArtifactFormat,
            #[serde(rename = "publicationPolicy")]
            publication_policy: RegistryPublicationPolicy,
