    impl ReleaseArtifactSlot {
        pub fn registry_artifact(
            artifact: &ApprovedRegistryArtifact,
            version: Version,
            provenance_policy: ProvenancePolicy,
        ) -> Self {
            Self::RegistryPackage {
                package: artifact.package.clone(),
                version,
                registry: artifact.registry.clone(),
                format: artifact.format,
                publication_policy: artifact.publication_policy.clone(),
                file_name: artifact.file_name.clone(),
                provenance_policy,
            }
        }

        pub fn product_asset(
            release: ProductReleaseId,
            target: ProductTarget,
            provenance_policy: ProvenancePolicy,
        ) -> Self {
            Self::ProductAsset {
                release,
                target,
                artifact_kind: target.artifact_kind(),
                file_name: target.file_name().to_string(),
                provenance_policy,
            }
        }

        pub fn checksum_manifest(release: ProductReleaseId, provenance_policy: ProvenancePolicy) -> Self {
            Self::ChecksumManifest {
                release,
                file_name: CHECKSUM_FILE_NAME.to_string(),
                provenance_policy,
            }
        }

        pub fn release_metadata(release: ProductReleaseId, provenance_policy: ProvenancePolicy) -> Self {
            Self::ReleaseMetadata {
                release,
                file_name: METADATA_FILE_NAME.to_string(),
                provenance_policy,
            }
        }

        pub fn release(&self) -> Option<&ProductReleaseId> {
            match self {
                Self::RegistryPackage { .. } => None,
                Self::ProductAsset { release, .. }
                | Self::ChecksumManifest { release, .. }
                | Self::ReleaseMetadata { release, .. } => Some(release),
            }
        }

        pub fn file_name(&self) -> &str {
            match self {
                Self::RegistryPackage { file_name, .. }
                | Self::ProductAsset { file_name, .. }
                | Self::ChecksumManifest { file_name, .. }
                | Self::ReleaseMetadata { file_name, .. } => file_name,
            }
        }

        pub fn policy(&self) -> &ProvenancePolicy {
            match self {
                Self::RegistryPackage { provenance_policy, .. }
                | Self::ProductAsset { provenance_policy, .. }
                | Self::ChecksumManifest { provenance_policy, .. }
                | Self::ReleaseMetadata { provenance_policy, .. } => provenance_policy,
            }
        }

        pub fn product_target(&self) -> Option<ProductTarget> {
            match self {
                Self::ProductAsset { target, .. } => Some(*target),
                _ => None,
            }
        }

        pub fn product_artifact_kind(&self) -> Option<ProductArtifactKind> {
            match self {
                Self::ProductAsset { artifact_kind, .. } => Some(*artifact_kind),
                _ => None,
            }
        }

        pub fn validate(&self, release: &ProductReleaseId) -> Result<(), SuccessorError> {
            if !is_safe_artifact_component(self.file_name()) {
                return Err(SuccessorError::UnsafeArtifactSlot);
            }
            self.policy().validate()?;
            match self {
                Self::RegistryPackage { version, .. } if version.grammar() != VersionGrammar::SemVer => {
                    Err(SuccessorError::NonSemverProductVersion {
                        version: Box::new(version.clone()),
                    })
                }
                Self::RegistryPackage { package, format, .. }
                    if !format_matches_ecosystem(*format, package.ecosystem()) =>
                {
                    Err(SuccessorError::RegistryFormatMismatch)
                }
                Self::RegistryPackage { format, file_name, .. } if !format_matches_file_name(*format, file_name) => {
                    Err(SuccessorError::UnsafeRegistryArtifactFileName)
                }
                Self::RegistryPackage {
                    package,
                    publication_policy,
                    ..
                } if publication_policy.ecosystem() != package.ecosystem() => {
                    Err(SuccessorError::RegistryPublicationPolicyMismatch)
                }
                Self::ProductAsset {
                    release: slot_release, ..
                }
                | Self::ChecksumManifest {
                    release: slot_release, ..
                }
                | Self::ReleaseMetadata {
                    release: slot_release, ..
                } if slot_release != release => Err(SuccessorError::ForeignProductRelease),
                Self::ProductAsset {
                    target,
                    artifact_kind,
                    file_name,
                    ..
                } if *artifact_kind != target.artifact_kind() || file_name != target.file_name() => {
                    Err(SuccessorError::MismatchedProductPayload)
                }
                Self::ChecksumManifest { file_name, .. } if file_name != CHECKSUM_FILE_NAME => {
                    Err(SuccessorError::WrongReservedFileName)
                }
                Self::ReleaseMetadata { file_name, .. } if file_name != METADATA_FILE_NAME => {
                    Err(SuccessorError::WrongReservedFileName)
                }
                _ => Ok(()),
            }
        }
    }

    impl PartialOrd for ReleaseArtifactSlot {
        fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
            Some(self.cmp(other))
        }
    }

    impl Ord for ReleaseArtifactSlot {
        fn cmp(&self, other: &Self) -> Ordering {
            fn rank(slot: &ReleaseArtifactSlot) -> u8 {
                match slot {
                    ReleaseArtifactSlot::RegistryPackage { .. } => 0,
                    ReleaseArtifactSlot::ProductAsset { .. } => 1,
                    ReleaseArtifactSlot::ChecksumManifest { .. } => 2,
                    ReleaseArtifactSlot::ReleaseMetadata { .. } => 3,
                }
            }
            match (self, other) {
                (
                    Self::RegistryPackage {
                        package: left_package,
                        version: left_version,
                        registry: left_registry,
                        format: left_format,
                        publication_policy: left_publication,
                        file_name: left_file,
                        provenance_policy: left_provenance,
                    },
                    Self::RegistryPackage {
                        package: right_package,
                        version: right_version,
                        registry: right_registry,
                        format: right_format,
                        publication_policy: right_publication,
                        file_name: right_file,
                        provenance_policy: right_provenance,
                    },
                ) => (
                    left_package,
                    version_ord_key(left_version),
                    left_registry,
                    left_format,
                    left_publication,
                    left_file,
                    provenance_ord_key(left_provenance),
                )
                    .cmp(&(
                        right_package,
                        version_ord_key(right_version),
                        right_registry,
                        right_format,
                        right_publication,
                        right_file,
                        provenance_ord_key(right_provenance),
                    )),
                (
                    Self::ProductAsset {
                        release: left_release,
                        target: left_target,
                        artifact_kind: left_kind,
                        file_name: left_file,
                        provenance_policy: left_provenance,
                    },
                    Self::ProductAsset {
                        release: right_release,
                        target: right_target,
                        artifact_kind: right_kind,
                        file_name: right_file,
                        provenance_policy: right_provenance,
                    },
                ) => (
                    left_release,
                    left_target,
                    left_kind,
                    left_file,
                    provenance_ord_key(left_provenance),
                )
                    .cmp(&(
                        right_release,
                        right_target,
                        right_kind,
                        right_file,
                        provenance_ord_key(right_provenance),
                    )),
                (
                    Self::ChecksumManifest {
                        release: left_release,
                        file_name: left_file,
                        provenance_policy: left_provenance,
                    },
                    Self::ChecksumManifest {
                        release: right_release,
                        file_name: right_file,
                        provenance_policy: right_provenance,
                    },
                )
                | (
                    Self::ReleaseMetadata {
                        release: left_release,
                        file_name: left_file,
                        provenance_policy: left_provenance,
                    },
                    Self::ReleaseMetadata {
                        release: right_release,
                        file_name: right_file,
                        provenance_policy: right_provenance,
                    },
                ) => (left_release, left_file, provenance_ord_key(left_provenance)).cmp(&(
                    right_release,
                    right_file,
                    provenance_ord_key(right_provenance),
                )),
                _ => rank(self).cmp(&rank(other)),
            }
        }
    }

    fn provenance_ord_key(policy: &ProvenancePolicy) -> ((&str, &str), &str, &str, bool) {
        (
            (policy.repository.owner(), policy.repository.repo()),
            &policy.workflow_path,
            policy.workflow_commit.as_str(),
            policy.github_attestation_required,
        )
    }

