    impl fmt::Display for ProductName {
        fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
            f.write_str(&self.0)
        }
    }

    impl<'de> Deserialize<'de> for ProductName {
        fn deserialize<D>(deserializer: D) -> Result<Self, D::Error>
        where
            D: Deserializer<'de>,
        {
            Self::parse(String::deserialize(deserializer)?).map_err(serde::de::Error::custom)
        }
    }

    #[derive(Clone, Debug, PartialEq, Eq, Hash, Serialize, JsonSchema)]
    #[serde(rename_all = "camelCase", deny_unknown_fields)]
    pub struct ProductReleaseId {
        product: ProductName,
        version: Version,
    }

    #[derive(Deserialize)]
    #[serde(rename_all = "camelCase", deny_unknown_fields)]
    struct ProductReleaseIdWire {
        product: ProductName,
        version: Version,
    }

    impl ProductReleaseId {
        pub fn new(product: ProductName, version: Version) -> Result<Self, SuccessorError> {
            if version.grammar() != VersionGrammar::SemVer {
                return Err(SuccessorError::NonSemverProductVersion {
                    version: Box::new(version),
                });
            }
            Ok(Self { product, version })
        }

        pub fn from_coordinated_versions(
            product: ProductName,
            versions: impl IntoIterator<Item = Version>,
        ) -> Result<Self, SuccessorError> {
            let versions = versions.into_iter().collect::<Vec<_>>();
            let Some(first) = versions.first() else {
                return Err(SuccessorError::EmptyCoordinatedRoster);
            };
            let Some(version) = versions
                .iter()
                .find(|candidate| candidate.grammar() == VersionGrammar::SemVer)
                .cloned()
            else {
                return Err(SuccessorError::NonSemverProductVersion {
                    version: Box::new(first.clone()),
                });
            };
            let canonical = version.render();
            for candidate in &versions {
                if candidate.render() != canonical {
                    return Err(SuccessorError::DivergentCoordinatedVersion {
                        expected: Box::new(version.clone()),
                        found: Box::new(candidate.clone()),
                    });
                }
            }
            Self::new(product, version)
        }

        pub fn product(&self) -> &ProductName {
            &self.product
        }

        pub fn version(&self) -> &Version {
            &self.version
        }

        pub fn tag(&self) -> String {
            if !self.github_attestation_required || !is_safe_workflow_path(&self.workflow_path) {
                return Err(SuccessorError::InvalidProvenance);
            }
            Ok(())
        }
    }

    impl<'de> Deserialize<'de> for ProvenancePolicy {
        fn deserialize<D>(deserializer: D) -> Result<Self, D::Error>
        where
            D: Deserializer<'de>,
        {
            let wire = ProvenancePolicyWire::deserialize(deserializer)?;
            let value = Self {
                repository: wire.repository,
                workflow_path: wire.workflow_path,
                workflow_commit: wire.workflow_commit,
                github_attestation_required: wire.github_attestation_required,
            };
            value.validate().map(|()| value).map_err(serde::de::Error::custom)
        }
    }

    #[derive(Clone, Debug, PartialEq, Eq, Hash, Serialize, Deserialize, JsonSchema)]
    #[serde(rename_all = "camelCase", tag = "kind", deny_unknown_fields)]
    pub enum ReleaseArtifactSlot {
        RegistryPackage {
            package: ReleasePackageId,
            version: Version,
            #[serde(flatten)]
            registry: RegistryBindingId,
            format: RegistryArtifactFormat,
            #[serde(rename = "publicationPolicy")]
            publication_policy: RegistryPublicationPolicy,
            #[serde(rename = "fileName")]
            file_name: String,
            #[serde(rename = "provenancePolicy")]
            provenance_policy: ProvenancePolicy,
        },
        ProductAsset {
            release: ProductReleaseId,
            target: ProductTarget,
            #[serde(rename = "artifactKind")]
            artifact_kind: ProductArtifactKind,
            #[serde(rename = "fileName")]
            file_name: String,
            #[serde(rename = "provenancePolicy")]
            provenance_policy: ProvenancePolicy,
        },
        ChecksumManifest {
            release: ProductReleaseId,
            #[serde(rename = "fileName")]
            file_name: String,
            #[serde(rename = "provenancePolicy")]
            provenance_policy: ProvenancePolicy,
        },
        ReleaseMetadata {
            release: ProductReleaseId,
            #[serde(rename = "fileName")]
            file_name: String,
            #[serde(rename = "provenancePolicy")]
            provenance_policy: ProvenancePolicy,
        },
    }

    impl ReleaseArtifactSlot {
        pub fn registry_artifact(
            artifact: &ApprovedRegistryArtifact,
            version: Version,
            provenance_policy: ProvenancePolicy,
        ) -> Self {
            Self::RegistryPackage {
                package: artifact.package.clone(),
                version,
                registry: artifact.registry.clone(),
                format: artifact.format,
                publication_policy: artifact.publication_policy.clone(),
                file_name: artifact.file_name.clone(),
                provenance_policy,
            }
        }

        pub fn product_asset(
            release: ProductReleaseId,
            target: ProductTarget,
            provenance_policy: ProvenancePolicy,
        ) -> Self {
            Self::ProductAsset {
                release,
                target,
                artifact_kind: target.artifact_kind(),
                file_name: target.file_name().to_string(),
                provenance_policy,
            }
        }

        pub fn checksum_manifest(release: ProductReleaseId, provenance_policy: ProvenancePolicy) -> Self {
            Self::ChecksumManifest {
                release,
                file_name: CHECKSUM_FILE_NAME.to_string(),
                provenance_policy,
            }
        }

        pub fn release_metadata(release: ProductReleaseId, provenance_policy: ProvenancePolicy) -> Self {
            Self::ReleaseMetadata {
                release,
                file_name: METADATA_FILE_NAME.to_string(),
                provenance_policy,
            }
        }

        pub fn release(&self) -> Option<&ProductReleaseId> {
            match self {
                Self::RegistryPackage { .. } => None,
                Self::ProductAsset { release, .. }
                | Self::ChecksumManifest { release, .. }
                | Self::ReleaseMetadata { release, .. } => Some(release),
            }
        }

        pub fn file_name(&self) -> &str {
            match self {
                Self::RegistryPackage { file_name, .. }
                | Self::ProductAsset { file_name, .. }
                | Self::ChecksumManifest { file_name, .. }
                | Self::ReleaseMetadata { file_name, .. } => file_name,
            }
        }

        pub fn policy(&self) -> &ProvenancePolicy {
            match self {
                Self::RegistryPackage { provenance_policy, .. }
                | Self::ProductAsset { provenance_policy, .. }
                | Self::ChecksumManifest { provenance_policy, .. }
                | Self::ReleaseMetadata { provenance_policy, .. } => provenance_policy,
            }
        }

        pub fn product_target(&self) -> Option<ProductTarget> {
            match self {
                Self::ProductAsset { target, .. } => Some(*target),
                _ => None,
            }
        }

        pub fn product_artifact_kind(&self) -> Option<ProductArtifactKind> {
            match self {
                Self::ProductAsset { artifact_kind, .. } => Some(*artifact_kind),
                _ => None,
            }
        }

        pub fn validate(&self, release: &ProductReleaseId) -> Result<(), SuccessorError> {
            if !is_safe_artifact_component(self.file_name()) {
                return Err(SuccessorError::UnsafeArtifactSlot);
            }
            self.policy().validate()?;
            match self {
                Self::RegistryPackage { version, .. } if version.grammar() != VersionGrammar::SemVer => {
                    Err(SuccessorError::NonSemverProductVersion {
                        version: Box::new(version.clone()),
                    })
                }
                Self::RegistryPackage { package, format, .. }
                    if !format_matches_ecosystem(*format, package.ecosystem()) =>
                {
                    Err(SuccessorError::RegistryFormatMismatch)
                }
                Self::RegistryPackage { format, file_name, .. } if !format_matches_file_name(*format, file_name) => {
                    Err(SuccessorError::UnsafeRegistryArtifactFileName)
                }
                Self::RegistryPackage {
                    package,
                    publication_policy,
                    ..
                } if publication_policy.ecosystem() != package.ecosystem() => {
                    Err(SuccessorError::RegistryPublicationPolicyMismatch)
                }
                Self::ProductAsset {
                    release: slot_release, ..
                }
                | Self::ChecksumManifest {
                    release: slot_release, ..
                }
                | Self::ReleaseMetadata {
                    release: slot_release, ..
                } if slot_release != release => Err(SuccessorError::ForeignProductRelease),
                Self::ProductAsset {
                    target,
                    artifact_kind,
                    file_name,
                    ..
                } if *artifact_kind != target.artifact_kind() || file_name != target.file_name() => {
                    Err(SuccessorError::MismatchedProductPayload)
                }
                Self::ChecksumManifest { file_name, .. } if file_name != CHECKSUM_FILE_NAME => {
                    Err(SuccessorError::WrongReservedFileName)
                }
                Self::ReleaseMetadata { file_name, .. } if file_name != METADATA_FILE_NAME => {
                    Err(SuccessorError::WrongReservedFileName)
                }
                _ => Ok(()),
            }
        }
    }

    impl PartialOrd for ReleaseArtifactSlot {
        fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
            Some(self.cmp(other))
        }
    }

    impl Ord for ReleaseArtifactSlot {
        fn cmp(&self, other: &Self) -> Ordering {
            fn rank(slot: &ReleaseArtifactSlot) -> u8 {
                match slot {
                    ReleaseArtifactSlot::RegistryPackage { .. } => 0,
                    ReleaseArtifactSlot::ProductAsset { .. } => 1,
                    ReleaseArtifactSlot::ChecksumManifest { .. } => 2,
                    ReleaseArtifactSlot::ReleaseMetadata { .. } => 3,
                }
            }
            match (self, other) {
                (
                    Self::RegistryPackage {
                        package: left_package,
                        version: left_version,
                        registry: left_registry,
                        format: left_format,
                        publication_policy: left_publication,
                        file_name: left_file,
                        provenance_policy: left_provenance,
                    },
                    Self::RegistryPackage {
                        package: right_package,
                        version: right_version,
                        registry: right_registry,
                        format: right_format,
                        publication_policy: right_publication,
                        file_name: right_file,
                        provenance_policy: right_provenance,
                    },
                ) => (
                    left_package,
                    version_ord_key(left_version),
                    left_registry,
                    left_format,
                    left_publication,
                    left_file,
                    provenance_ord_key(left_provenance),
                )
                    .cmp(&(
                        right_package,
                        version_ord_key(right_version),
                        right_registry,
                        right_format,
                        right_publication,
                        right_file,
                        provenance_ord_key(right_provenance),
                    )),
                (
                    Self::ProductAsset {
                        release: left_release,
                        target: left_target,
                        artifact_kind: left_kind,
                        file_name: left_file,
                        provenance_policy: left_provenance,
                    },
                    Self::ProductAsset {
                        release: right_release,
                        target: right_target,
                        artifact_kind: right_kind,
                        file_name: right_file,
                        provenance_policy: right_provenance,
                    },
                ) => (
                    left_release,
                    left_target,
                    left_kind,
                    left_file,
                    provenance_ord_key(left_provenance),
                )
                    .cmp(&(
                        right_release,
                        right_target,
                        right_kind,
                        right_file,
                        provenance_ord_key(right_provenance),
                    )),
                (
                    Self::ChecksumManifest {
                        release: left_release,
                        file_name: left_file,
                        provenance_policy: left_provenance,
                    },
                    Self::ChecksumManifest {
                        release: right_release,
                        file_name: right_file,
                        provenance_policy: right_provenance,
                    },
                )
                | (
                    Self::ReleaseMetadata {
                        release: left_release,
                        file_name: left_file,
                        provenance_policy: left_provenance,
                    },
                    Self::ReleaseMetadata {
                        release: right_release,
                        file_name: right_file,
                        provenance_policy: right_provenance,
                    },
                ) => (left_release, left_file, provenance_ord_key(left_provenance)).cmp(&(
                    right_release,
                    right_file,
                    provenance_ord_key(right_provenance),
                )),
                _ => rank(self).cmp(&rank(other)),
            }
        }
    }

    fn provenance_ord_key(policy: &ProvenancePolicy) -> ((&str, &str), &str, &str, bool) {
        (
            (policy.repository.owner(), policy.repository.repo()),
            &policy.workflow_path,
            policy.workflow_commit.as_str(),
            policy.github_attestation_required,
        )
    }

    #[derive(Clone, Debug, PartialEq, Eq, Hash, Serialize, Deserialize, JsonSchema)]
    #[serde(rename_all = "camelCase", tag = "kind", deny_unknown_fields)]
    pub enum ReleaseOperationId {
        RegistryArtifactPublish {
            package: ReleasePackageId,
            version: Version,
            #[serde(flatten)]
            registry: RegistryBindingId,
            slot: ReleaseArtifactSlot,
        },
        ProductTag {
            release: ProductReleaseId,
            tag: String,
        },
        ForgePrepare {
            release: ProductReleaseId,
            repository: GitHubRepository,
        },
        ArtifactUpload {
            release: ProductReleaseId,
            slot: ReleaseArtifactSlot,
        },
        ForgePublish {
            release: ProductReleaseId,
            repository: GitHubRepository,
        },
    }

    impl ReleaseOperationId {
        pub fn release(&self) -> Option<&ProductReleaseId> {
            match self {
                Self::RegistryArtifactPublish { .. } => None,
                Self::ProductTag { release, .. }
                | Self::ForgePrepare { release, .. }
                | Self::ArtifactUpload { release, .. }
                | Self::ForgePublish { release, .. } => Some(release),
            }
        }

        pub fn validate(&self, release: &ProductReleaseId) -> Result<(), SuccessorError> {
            match self {
                Self::RegistryArtifactPublish {
                    package,
                    version,
                    registry,
                    slot:
                        ReleaseArtifactSlot::RegistryPackage {
                            package: slot_package,
                            version: slot_version,
                            registry: slot_registry,
                            ..
                        },
                } if package == slot_package && version == slot_version && registry == slot_registry => Ok(()),
                Self::RegistryArtifactPublish { .. } => Err(SuccessorError::InvalidPackageOperation),
                Self::ProductTag { release: id, tag } if id == release && tag == &release.tag() => Ok(()),
                Self::ForgePrepare { release: id, .. } | Self::ForgePublish { release: id, .. } if id == release => {
                    Ok(())
                }
                Self::ArtifactUpload { release: id, slot } if id == release && slot.release() == Some(id) => Ok(()),
                _ => Err(SuccessorError::InvalidProductOperation),
            }
        }
    }

    impl PartialOrd for ReleaseOperationId {
        fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
            Some(self.cmp(other))
        }
    }

    impl Ord for ReleaseOperationId {
        fn cmp(&self, other: &Self) -> Ordering {
            fn rank(id: &ReleaseOperationId) -> u8 {
                match id {
                return Err(ReleaseExecutionStateError::UnsupportedSchema {
                    found: wire.schema_version,
                });
            }
            let mut operations = BTreeMap::new();
            for entry in wire.operations {
                if operations.insert(entry.operation.clone(), entry.state).is_some() {
                    return Err(ReleaseExecutionStateError::DuplicateOperation {
                        id: Box::new(entry.operation),
                    });
                }
            }
            Ok(Self {
                schema_version: wire.schema_version,
                intent_digest: wire.intent_digest,
                operations,
            })
        }
    }

    #[derive(Clone, Debug, PartialEq, Eq, thiserror::Error)]
    #[non_exhaustive]
    pub enum ReleaseExecutionStateError {
        #[error("unsupported release execution state schema version {found}")]
        UnsupportedSchema { found: u8 },
        #[error("release state is bound to a different intent")]
        MismatchedIntent,
        #[error("release state operation roster differs from the bound intent")]
        MismatchedOperationRoster,
        #[error("release state contains duplicate operation `{id:?}`")]
        DuplicateOperation { id: Box<ReleaseOperationId> },
        #[error("release state does not contain operation `{id:?}`")]
        UnknownOperation { id: Box<ReleaseOperationId> },
        #[error("operation `{id:?}` cannot transition from {from:?}")]
        InvalidTransition {
            id: Box<ReleaseOperationId>,
            from: ReleaseOperationState,
        },
    }

    fn validate_decision(
        decision: &ReleaseDecisionV1,
        release: &ProductReleaseId,
        approved: &[ApprovedRegistryArtifact],
    ) -> Result<(), SuccessorError> {
        let derived = ProductReleaseId::from_coordinated_versions(
            release.product.clone(),
            decision.entries.iter().map(|entry| entry.target_version.clone()),
        )?;
        if &derived != release {
            return Err(SuccessorError::DecisionProductMismatch);
        }
        let decision_versions = decision
            .entries
            .iter()
            .map(|entry| (&entry.package, &entry.target_version))
            .collect::<BTreeMap<_, _>>();
        if approved
            .iter()
            .any(|entry| decision_versions.get(&entry.package).copied() != Some(&release.version))
        {
            return Err(SuccessorError::RegistryArtifactOutsideDecision);
        }
        Ok(())
    }

    fn validate_slot_roster(
        release: &ProductReleaseId,
        destination: &ReleaseDestinationBinding,
        approved: &[ApprovedRegistryArtifact],
        slots: &[ReleaseArtifactSlot],
    ) -> Result<(), SuccessorError> {
        if slots.windows(2).any(|pair| pair[0] == pair[1]) {
            return Err(SuccessorError::DuplicateSlot);
        }
        for slot in slots {
            slot.validate(release)?;
        }
        let mut product_policies = slots.iter().filter_map(|slot| match slot {
            ReleaseArtifactSlot::ProductAsset { provenance_policy, .. } => Some(provenance_policy),
            _ => None,
        });
        if let Some(first) = product_policies.next() {
            if product_policies.any(|policy| policy != first) {
                return Err(SuccessorError::HeterogeneousProductProvenance);
            }
