//! Observation-authoritative convergence for one validated release.
//!
//! Local execution state is diagnostic only. Every invocation derives its
//! authority from fresh provider observation, performs each proven-missing
//! effect at most once, and persists a receipt only after a separate final
//! pass proves the complete canonical operation roster exact.

use std::{collections::BTreeMap, path::Path};

use callisto_model::{
    ApplyPermit, CommandRunner, CompleteObservationReceipt, ObservationProvenance, ObservedOperation, OperationOutcome,
    ProductReleaseId, ReleaseArtifactManifest, ReleaseArtifactSlot, ReleaseIntent, ReleaseObservationEvidence,
    ReleaseOperationId,
};
use serde::{Deserialize, Serialize};

use crate::{locate::ProjectLocator, GraphError};

use super::{
    release::{validate_release_intent_with_state_directory, ValidatedReleaseIntent},
    release_artifacts::{verify_artifact_manifest, ValidatedArtifactManifest},
    release_observation::{
        observe_prepared, ExternalConflict, MissingWork, ObservationFailure, ObservationProvider, ObservationSession,
        OperationObservation, VerifiedPartialEvidence,
    },
    release_receipt_store::{ReleaseReceiptStore, ReleaseReceiptWriter},
};

/// Executes one release through the sealed validation, artifact-verification,
/// observation, dispatch, and final-receipt pipeline.
///
/// Callers provide only serialized model inputs and explicit filesystem
/// locations. The capabilities that authorize provider effects remain private
/// to the graph crate and cannot be retained or fabricated by a caller.
#[allow(clippy::too_many_arguments)]
pub fn execute_release_from_artifacts<L: ProjectLocator, R: CommandRunner>(
    root: &Path,
    locator: &L,
    runner: &R,
    explicit_state_directory: Option<&Path>,
    intent: ReleaseIntent,
    artifact_manifest: ReleaseArtifactManifest,
    artifact_directory: &Path,
    receipt_path: &Path,
    permit: &ApplyPermit,
) -> Result<CompleteObservationReceipt, GraphError> {
    let capability =
        validate_release_intent_with_state_directory(root, locator, runner, explicit_state_directory, intent)?;
    let artifacts = verify_artifact_manifest(&capability, artifact_manifest, artifact_directory, runner)?;
    let receipt_store = ReleaseReceiptStore::new(receipt_path);
    converge_release(&capability, &artifacts, &receipt_store, permit)
}

/// A provider-neutral, secret-free observation state for one exact release
/// operation.
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "kebab-case", tag = "state", content = "summary")]
pub enum ReleaseReadinessState {
    Absent,
    Incomplete {
        exact: Vec<ReleaseObservationEvidence>,
        missing: Vec<ReleaseMissingWork>,
    },
    Exact(ReleaseObservationEvidence),
    Conflict(ReleaseConflictKind),
    Unverifiable(ReleaseObservationFailure),
}

/// One closed piece of work proven absent from an otherwise partially exact
/// external object.
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "kebab-case", tag = "kind", content = "identity")]
pub enum ReleaseMissingWork {
    RegistryArtifact(ReleaseArtifactSlot),
    ForgeAsset(ReleaseArtifactSlot),
    PublishForgeRelease(ProductReleaseId),
}

/// Secret-free conflict categories. Provider response bodies are never
/// retained in this public report.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "kebab-case")]
pub enum ReleaseConflictKind {
    RemoteTag,
    RemoteTagMissingForForge,
    RegistryDigest,
    RegistryLength,
    UnexpectedRegistryDistribution,
    ForgeReleaseTag,
    ForgeAssetDigest,
    ForgeAssetLength,
    UnexpectedForgeAsset,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "kebab-case")]
pub enum ReleaseObservationProvider {
    Git,
    GitHub,
    Cargo,
    Npm,
    Pypi,
    ArtifactCapability,
    PreparedCapability,
}

/// Closed, redacted provider failure summary.
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "kebab-case", tag = "kind")]
pub enum ReleaseObservationFailure {
    TrustChanged {
        provider: ReleaseObservationProvider,
    },
    Command {
        provider: ReleaseObservationProvider,
    },
    HttpStatus {
        provider: ReleaseObservationProvider,
        status: u16,
    },
    MalformedResponse {
        provider: ReleaseObservationProvider,
    },
    MissingDigest {
        provider: ReleaseObservationProvider,
        file_name: String,
    },
    Capability {
        provider: ReleaseObservationProvider,
    },
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct ReleaseReadinessOperation {
    operation: ReleaseOperationId,
    observation: ReleaseReadinessState,
}

impl ReleaseReadinessOperation {
    pub fn operation(&self) -> &ReleaseOperationId {
        &self.operation
    }

    pub fn observation(&self) -> &ReleaseReadinessState {
        &self.observation
    }
}

/// One fresh, read-only observation of the canonical release DAG.
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct ReleaseReadinessReport {
    operations: Vec<ReleaseReadinessOperation>,
}

impl ReleaseReadinessReport {
    pub fn operations(&self) -> &[ReleaseReadinessOperation] {
        &self.operations
    }

    pub fn is_ready(&self) -> bool {
        self.operations
            .iter()
            .all(|operation| matches!(operation.observation, ReleaseReadinessState::Exact(_)))
    }
}

/// Revalidates the intent and artifact bytes, then observes every canonical
/// operation without constructing an effect permit or persisting a receipt.
#[allow(clippy::too_many_arguments)]
pub fn reconcile_release_from_artifacts<L: ProjectLocator, R: CommandRunner>(
    root: &Path,
    locator: &L,
    runner: &R,
    explicit_state_directory: Option<&Path>,
    intent: ReleaseIntent,
    artifact_manifest: ReleaseArtifactManifest,
    artifact_directory: &Path,
) -> Result<ReleaseReadinessReport, GraphError> {
) -> Result<ReleaseReadinessReport, GraphError> {
    let capability =
        validate_release_intent_with_state_directory(root, locator, runner, explicit_state_directory, intent)?;
    let artifacts = verify_artifact_manifest(&capability, artifact_manifest, artifact_directory, runner)?;
    let mut session = ObservationSession::default();
    let operations = capability
        .intent()
        .operations()
        .iter()
        .map(|operation| ReleaseReadinessOperation {
            operation: operation.id().clone(),
            observation: readiness_state(observe_prepared(&mut session, &artifacts, operation.id())),
        })
        .collect();
    Ok(ReleaseReadinessReport { operations })
}

/// Converges one validated release from external truth and writes its strict
/// final observation receipt atomically. No journal or prior receipt is read.
pub(super) fn converge_release<W: ReleaseReceiptWriter>(
    capability: &ValidatedReleaseIntent<'_>,
    artifacts: &ValidatedArtifactManifest<'_, '_>,
    receipt_store: &ReleaseReceiptStore<W>,
    permit: &ApplyPermit,
) -> Result<CompleteObservationReceipt, GraphError> {
    let intent = capability.intent();
    let mut observations = ObservationSession::default();
    let mut provenance = BTreeMap::new();

    for operation in intent.operations() {
        let id = operation.id();
        let observed = observe_prepared(&mut observations, artifacts, id);
        if observation_satisfies_operation(id, &observed) {
            provenance.insert(id.clone(), ObservationProvenance::AlreadyPresent);
            continue;
        }
        require_dispatchable_missing_work(id, &observed)?;
        let outcome = capability.dispatch_prepared(artifacts, &mut observations, permit, id)?;
        provenance.insert(
            id.clone(),
            match outcome {
                OperationOutcome::Published => ObservationProvenance::NewlyProduced,
                OperationOutcome::AlreadySatisfied => ObservationProvenance::AlreadyPresent,
                OperationOutcome::Failed | OperationOutcome::Blocked { .. } => {
                    return Err(GraphError::ReleaseOperationNotMissing { operation: id.clone() });
                }
                _ => return Err(GraphError::ReleaseOperationNotMissing { operation: id.clone() }),
            },
        );
    }

    observations.invalidate_after_effect();
    let mut exact = Vec::with_capacity(intent.operations().len());
    for operation in intent.operations() {
        let id = operation.id();
        let evidence = match observe_prepared(&mut observations, artifacts, id) {
            OperationObservation::Exact(evidence) => evidence,
            OperationObservation::Conflict(_) => {
                return Err(GraphError::ReleaseObservationConflict { operation: id.clone() });
            }
            OperationObservation::Unverifiable(_) => {
                return Err(GraphError::ReleaseObservationUnverifiable { operation: id.clone() });
            }
            OperationObservation::Absent | OperationObservation::Incomplete(_) => {
                return Err(GraphError::ReleaseOperationNotMissing { operation: id.clone() });
            }
        };
        exact.push(ObservedOperation::new(
            id.clone(),
            evidence,
            provenance
                .get(id)
                .copied()
                .unwrap_or(ObservationProvenance::AlreadyPresent),
        ));
    }

    let expectations = artifacts.expectations();
    let receipt = CompleteObservationReceipt::new(intent, &expectations, exact).map_err(|source| {
        GraphError::ReleaseInvariant {
            detail: format!("final exact observation roster did not form a receipt: {source}"),
        }
    })?;
    receipt_store.save(intent, &expectations, &receipt, permit)?;
    Ok(receipt)
}

fn observation_satisfies_operation(id: &ReleaseOperationId, observed: &OperationObservation) -> bool {
    match observed {
        OperationObservation::Exact(_) => true,
        OperationObservation::Incomplete(partial) => match id {
            ReleaseOperationId::RegistryArtifactPublish { slot, .. } => {
                !partial.missing().contains(&MissingWork::RegistryArtifact(slot.clone()))
            }
            _ => false,
        },
        OperationObservation::Absent | OperationObservation::Conflict(_) | OperationObservation::Unverifiable(_) => {
            false
        }
    }
}

fn require_dispatchable_missing_work(
    id: &ReleaseOperationId,
    observed: &OperationObservation,
) -> Result<(), GraphError> {
    match observed {
        OperationObservation::Absent
            if matches!(
                id,
                ReleaseOperationId::RegistryArtifactPublish { .. }
                    | ReleaseOperationId::ProductTag { .. }
                    | ReleaseOperationId::ForgePrepare { .. }
                    | ReleaseOperationId::ArtifactUpload { .. }
            ) =>
        {
            Ok(())
        }
        OperationObservation::Incomplete(partial) if incomplete_authorizes_operation(id, partial) => Ok(()),
        OperationObservation::Conflict(_) => Err(GraphError::ReleaseObservationConflict { operation: id.clone() }),
        OperationObservation::Unverifiable(_) => {
            Err(GraphError::ReleaseObservationUnverifiable { operation: id.clone() })
        }
        OperationObservation::Absent | OperationObservation::Incomplete(_) | OperationObservation::Exact(_) => {
            Err(GraphError::ReleaseOperationNotMissing { operation: id.clone() })
        }
    }
}

fn incomplete_authorizes_operation(id: &ReleaseOperationId, partial: &VerifiedPartialEvidence) -> bool {
    match id {
        ReleaseOperationId::RegistryArtifactPublish { slot, .. } => {
            partial.missing().contains(&MissingWork::RegistryArtifact(slot.clone()))
        }
        ReleaseOperationId::ForgePublish { release, .. } => {
            partial.missing().len() == 1
                && partial
                    .missing()
                    .contains(&MissingWork::PublishForgeRelease(release.clone()))
        }
        ReleaseOperationId::ProductTag { .. }
        | ReleaseOperationId::ForgePrepare { .. }
        | ReleaseOperationId::ArtifactUpload { .. } => false,
    }
}

fn readiness_state(observation: OperationObservation) -> ReleaseReadinessState {
    match observation {
        OperationObservation::Absent => ReleaseReadinessState::Absent,
        OperationObservation::Incomplete(partial) => ReleaseReadinessState::Incomplete {
            exact: partial.exact().to_vec(),
            missing: partial
                .missing()
                .iter()
                .cloned()
                .map(ReleaseMissingWork::from)
                .collect(),
        },
        OperationObservation::Exact(evidence) => ReleaseReadinessState::Exact(evidence),
        OperationObservation::Conflict(conflict) => ReleaseReadinessState::Conflict(conflict.into()),
        OperationObservation::Unverifiable(failure) => ReleaseReadinessState::Unverifiable(failure.into()),
    }
}

impl From<MissingWork> for ReleaseMissingWork {
    fn from(missing: MissingWork) -> Self {
        match missing {
            MissingWork::RegistryArtifact(slot) => Self::RegistryArtifact(slot),
            MissingWork::ForgeAsset(slot) => Self::ForgeAsset(slot),
            MissingWork::PublishForgeRelease(release) => Self::PublishForgeRelease(release),
        }
    }
}

impl From<ExternalConflict> for ReleaseConflictKind {
    fn from(conflict: ExternalConflict) -> Self {
        match conflict {
            ExternalConflict::RemoteTag(_) => Self::RemoteTag,
            ExternalConflict::RemoteTagMissingForForge => Self::RemoteTagMissingForForge,
            ExternalConflict::RegistryDigest { .. } => Self::RegistryDigest,
            ExternalConflict::RegistryLength { .. } => Self::RegistryLength,
            ExternalConflict::UnexpectedRegistryDistribution { .. } => Self::UnexpectedRegistryDistribution,
            ExternalConflict::ForgeReleaseTag => Self::ForgeReleaseTag,
            ExternalConflict::ForgeAssetDigest { .. } => Self::ForgeAssetDigest,
            ExternalConflict::ForgeAssetLength { .. } => Self::ForgeAssetLength,
            ExternalConflict::UnexpectedForgeAsset { .. } => Self::UnexpectedForgeAsset,
        }
    }
}

impl From<ObservationProvider> for ReleaseObservationProvider {
    fn from(provider: ObservationProvider) -> Self {
        match provider {
            ObservationProvider::Git => Self::Git,
            ObservationProvider::GitHub => Self::GitHub,
            ObservationProvider::Cargo => Self::Cargo,
            ObservationProvider::Npm => Self::Npm,
            ObservationProvider::Pypi => Self::Pypi,
            ObservationProvider::ArtifactCapability => Self::ArtifactCapability,
            ObservationProvider::PreparedCapability => Self::PreparedCapability,
        }
        }
    }
}

impl From<ObservationFailure> for ReleaseObservationFailure {
    fn from(failure: ObservationFailure) -> Self {
        match failure {
            ObservationFailure::TrustChanged { provider } => Self::TrustChanged {
                provider: provider.into(),
            },
            ObservationFailure::Command { provider } => Self::Command {
                provider: provider.into(),
            },
            ObservationFailure::HttpStatus { provider, status } => Self::HttpStatus {
                provider: provider.into(),
                status,
            },
            ObservationFailure::MalformedResponse { provider } => Self::MalformedResponse {
                provider: provider.into(),
            },
            ObservationFailure::MissingDigest { provider, file_name } => Self::MissingDigest {
                provider: provider.into(),
                file_name,
            },
            ObservationFailure::Capability { provider } => Self::Capability {
                provider: provider.into(),
            },
            ObservationFailure::CommandSource { provider, cause: _ } => Self::Command {
                provider: provider.into(),
            },
            ObservationFailure::MalformedResponseSource { provider, cause: _ } => Self::MalformedResponse {
                provider: provider.into(),
            },
            ObservationFailure::CapabilitySource { provider, cause: _ } => Self::Capability {
                provider: provider.into(),
            },
        }
    }
}

