/// A provider-neutral, secret-free observation state for one exact release
/// operation.
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "kebab-case", tag = "state", content = "summary")]
pub enum ReleaseReadinessState {
    Absent,
    Incomplete {
        exact: Vec<ReleaseObservationEvidence>,
        missing: Vec<ReleaseMissingWork>,
    },
    Exact(ReleaseObservationEvidence),
    Conflict(ReleaseConflictKind),
    Unverifiable(ReleaseObservationFailure),
